// AST for the markdown parser (comrak-like)

#[derive(Debug, Clone, PartialEq)]
pub enum ListType {
    Bullet,
    Ordered,
}

#[derive(Debug, Clone)]
pub struct ListData {
    pub list_type: ListType,
    pub marker_offset: usize,
    pub padding: usize,
    pub start: usize,
    pub delimiter: u8,
    pub bullet_char: u8,
    pub tight: bool,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Align {
    None,
    Left,
    Center,
    Right,
}

#[derive(Debug, Clone)]
pub enum NodeValue {
    Document,
    BlockQuote,
    List(ListData),
    Item(ListData),
    TaskItem(bool),
    DescriptionList,
    DescriptionItem(usize, usize),
    DescriptionTerm,
    DescriptionDetails,
    CodeBlock {
        fenced: bool,
        fence_char: u8,
        fence_length: usize,
        fence_offset: usize,
        info: String,
        literal: String,
    },
    HtmlBlock {
        block_type: u8,
        literal: String,
    },
    Paragraph,
    Heading {
        level: u8,
        setext: bool,
    },
    ThematicBreak,
    FootnoteDefinition(String),
    Table(Vec<Align>),
    TableRow(bool),
    TableCell,
    // inlines
    Text(String),
    SoftBreak,
    LineBreak,
    Code(String),
    HtmlInline(String),
    Emph,
    Strong,
    Strikethrough,
    Superscript,
    Subscript,
    Link { url: String, title: String },
    Image { url: String, title: String },
    FootnoteReference(String),
}

#[derive(Debug, Clone)]
pub struct Node {
    pub value: NodeValue,
    pub parent: Option<usize>,
    pub children: Vec<usize>,
    pub open: bool,
    pub last_line_blank: bool,
    pub content: String,
    pub start_line: usize,
    pub table_visited: bool,
    pub internal_offset: usize,
}

pub struct Arena {
    pub nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Arena {
        Arena { nodes: Vec::new() }
    }
    pub fn alloc(&mut self, value: NodeValue) -> usize {
        self.nodes.push(Node {
            value,
            parent: None,
            children: Vec::new(),
            open: true,
            last_line_blank: false,
            content: String::new(),
            start_line: 0,
            table_visited: false,
            internal_offset: 0,
        });
        self.nodes.len() - 1
    }
    pub fn append(&mut self, parent: usize, child: usize) {
        self.nodes[child].parent = Some(parent);
        self.nodes[parent].children.push(child);
    }
    pub fn detach(&mut self, child: usize) {
        if let Some(p) = self.nodes[child].parent {
            self.nodes[p].children.retain(|&c| c != child);
        }
        self.nodes[child].parent = None;
    }
    pub fn last_child(&self, n: usize) -> Option<usize> {
        self.nodes[n].children.last().cloned()
    }
    pub fn first_child(&self, n: usize) -> Option<usize> {
        self.nodes[n].children.first().cloned()
    }
}
EOF
