        if p + 1 < s.len() && s[p + 1].is_ascii_alphabetic() {
            let mut i = p + 1;
            while i < s.len() {
                if s[i] == b'>' {
                    return i + 1;
                }
                i += 1;
            }
            return 0;
        }
        return 0;
    }
    if c == b'?' {
        let mut i = p + 1;
        while i + 2 <= s.len() {
            if &s[i..i + 2] == b"?>" {
                return i + 2;
            }
            i += 1;
        }
        return 0;
    }
    if c == b'/' {
        return scan_closing_tag(s, p + 1);
    }
    scan_open_tag(s, p)
}

pub fn scan_autolink_uri(s: &[u8], pos: usize) -> usize {
