// Scanners for markdown block/inline constructs
use crate::entities::{PUNCT_RANGES, SYMBOL_RANGES};

pub fn is_line_end(c: Option<&u8>) -> bool {
    match c {
        None => true,
        Some(b'\n') | Some(b'\r') => true,
        _ => false,
    }
}

pub fn is_space_or_tab(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

pub fn is_ascii_punct(c: u8) -> bool {
    matches!(c, b'!'..=b'/' | b':'..=b'@' | b'['..=b'`' | b'{'..=b'~')
}

fn in_ranges(c: u32, ranges: &[(u32, u32)]) -> bool {
    let mut lo = 0usize;
    let mut hi = ranges.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = ranges[mid];
        if c < a {
            hi = mid;
        } else if c > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

pub fn is_punctuation(c: char) -> bool {
    let u = c as u32;
    if u < 128 {
        return is_ascii_punct(u as u8);
    }
    in_ranges(u, PUNCT_RANGES)
}

#[allow(dead_code)]
pub fn is_symbol(c: char) -> bool {
    in_ranges(c as u32, SYMBOL_RANGES)
}

pub fn is_unicode_space(c: char) -> bool {
    let u = c as u32;
    u == 9
        || u == 10
        || u == 12
        || u == 13
        || u == 32
        || u == 160
        || u == 0x1680
        || (0x2000..=0x200A).contains(&u)
        || u == 0x202F
        || u == 0x205F
        || u == 0x3000
}

/// ATX heading start: returns length matched (hashes + following space) or 0
pub fn atx_heading_start(line: &[u8], pos: usize) -> usize {
    let mut i = pos;
    let mut n = 0;
    while i < line.len() && line[i] == b'#' {
        n += 1;
        i += 1;
    }
    if n == 0 || n > 6 {
        return 0;
    }
    if i >= line.len() || line[i] == b'\n' || line[i] == b'\r' {
        return i - pos;
    }
    if line[i] == b' ' || line[i] == b'\t' {
        while i < line.len() && (line[i] == b' ' || line[i] == b'\t') {
            i += 1;
        }
        return i - pos;
    }
    0
}

/// Opening code fence: returns length of fence or 0
pub fn open_code_fence(line: &[u8], pos: usize) -> usize {
    if pos >= line.len() {
        return 0;
    }
    let c = line[pos];
    if c != b'`' && c != b'~' {
        return 0;
    }
    let mut i = pos;
    while i < line.len() && line[i] == c {
        i += 1;
    }
    let n = i - pos;
    if n < 3 {
        return 0;
    }
    if c == b'`' {
        // info string may not contain backticks
        let mut j = i;
        while j < line.len() && line[j] != b'\n' && line[j] != b'\r' {
            if line[j] == b'`' {
                return 0;
            }
            j += 1;
        }
    }
    n
}

/// closing code fence: returns length or 0
pub fn close_code_fence(line: &[u8], pos: usize) -> usize {
    if pos >= line.len() {
        return 0;
    }
    let c = line[pos];
    if c != b'`' && c != b'~' {
        return 0;
    }
    let mut i = pos;
    while i < line.len() && line[i] == c {
        i += 1;
    }
    let n = i - pos;
    if n < 3 {
        return 0;
    }
    let mut j = i;
    while j < line.len() && (line[j] == b' ' || line[j] == b'\t') {
        j += 1;
    }
    if j >= line.len() || line[j] == b'\n' || line[j] == b'\r' {
        return n;
    }
    0
}

/// thematic break; returns true if matched
pub fn thematic_break(line: &[u8], pos: usize) -> bool {
    if pos >= line.len() {
        return false;
    }
    let c = line[pos];
    if c != b'*' && c != b'-' && c != b'_' {
        return false;
    }
    let mut count = 0;
    let mut i = pos;
    while i < line.len() {
        let d = line[i];
        if d == c {
            count += 1;
        } else if d == b' ' || d == b'\t' {
        } else if d == b'\n' || d == b'\r' {
            break;
        } else {
            return false;
        }
        i += 1;
    }
    count >= 3
}

/// setext heading underline: returns level (1 or 2) or 0
pub fn setext_heading_line(line: &[u8], pos: usize) -> u8 {
    if pos >= line.len() {
        return 0;
    }
    let c = line[pos];
    if c != b'=' && c != b'-' {
        return 0;
    }
    let mut i = pos;
    while i < line.len() && line[i] == c {
        i += 1;
    }
    while i < line.len() && (line[i] == b' ' || line[i] == b'\t') {
        i += 1;
    }
    if i >= line.len() || line[i] == b'\n' || line[i] == b'\r' {
        if c == b'=' {
            1
        } else {
            2
        }
    } else {
        0
    }
}

const BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center",
    "col", "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset",
    "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5",
    "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link", "main", "menu",
    "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param", "search", "section",
    "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title", "tr", "track", "ul",
];

fn lower_starts_with(line: &[u8], pos: usize, s: &str) -> bool {
    let sb = s.as_bytes();
    if pos + sb.len() > line.len() {
        return false;
    }
    for k in 0..sb.len() {
        if line[pos + k].to_ascii_lowercase() != sb[k] {
            return false;
        }
    }
    true
}

/// HTML block start conditions 1-6
pub fn html_block_start(line: &[u8], pos: usize) -> u8 {
    if pos >= line.len() || line[pos] != b'<' {
        return 0;
    }
    let p = pos + 1;
    // type 1
    for t in &["script", "pre", "style", "textarea"] {
        if lower_starts_with(line, p, t) {
            let after = p + t.len();
            match line.get(after) {
                None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') | Some(b'>') => return 1,
                _ => {}
            }
        }
    }
    if line[p..].starts_with(b"!--") {
        return 2;
    }
    if line.get(p) == Some(&b'?') {
        return 3;
    }
    if line.get(p) == Some(&b'!') {
        if let Some(c) = line.get(p + 1) {
            if c.is_ascii_alphabetic() {
                return 4;
            }
        }
        if line[p..].starts_with(b"![CDATA[") {
            return 5;
        }
    }
    // type 6
    let mut q = p;
    if line.get(q) == Some(&b'/') {
        q += 1;
    }
    let start = q;
    while q < line.len() && line[q].is_ascii_alphanumeric() {
        q += 1;
    }
    if q > start {
        let name: String = String::from_utf8_lossy(&line[start..q]).to_ascii_lowercase();
        if BLOCK_TAGS.contains(&name.as_str()) {
            match line.get(q) {
                None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') | Some(b'>') => return 6,
                Some(b'/') => {
                    if line.get(q + 1) == Some(&b'>') {
                        return 6;
                    }
                }
                _ => {}
            }
        }
    }
    0
}

/// HTML block start condition 7 (complete open or closing tag alone on line)
pub fn html_block_start_7(line: &[u8], pos: usize) -> u8 {
    if pos >= line.len() || line[pos] != b'<' {
        return 0;
    }
    let n = if line.get(pos + 1) == Some(&b'/') {
        scan_closing_tag(line, pos + 2)
    } else {
        scan_open_tag(line, pos + 1)
    };
    if n == 0 {
        return 0;
    }
    let mut i = n;
    while i < line.len() && (line[i] == b' ' || line[i] == b'\t') {
        i += 1;
    }
    if i >= line.len() || line[i] == b'\n' || line[i] == b'\r' {
        // check tag name not script/style/pre/textarea
        let mut s = pos + 1;
        if line.get(s) == Some(&b'/') {
            s += 1;
        }
        let mut e = s;
        while e < line.len() && (line[e].is_ascii_alphanumeric() || line[e] == b'-') {
            e += 1;
        }
        let name = String::from_utf8_lossy(&line[s..e]).to_ascii_lowercase();
        if ["script", "style", "pre", "textarea"].contains(&name.as_str()) {
            return 0;
        }
        return 7;
    }
    0
}

pub fn html_block_end(t: u8, line: &[u8], pos: usize) -> bool {
    let s = &line[pos.min(line.len())..];
    let lower: Vec<u8> = s.iter().map(|c| c.to_ascii_lowercase()).collect();
    let contains = |pat: &[u8]| lower.windows(pat.len()).any(|w| w == pat);
    match t {
        1 => contains(b"</script>") || contains(b"</pre>") || contains(b"</style>") || contains(b"</textarea>"),
        2 => contains(b"-->"),
        3 => contains(b"?>"),
        4 => contains(b">"),
        5 => contains(b"]]>"),
        _ => false,
    }
}

fn scan_tag_name(line: &[u8], pos: usize) -> usize {
    // returns end position or 0
    let mut i = pos;
    if i >= line.len() || !line[i].is_ascii_alphabetic() {
        return 0;
    }
    i += 1;
    while i < line.len() && (line[i].is_ascii_alphanumeric() || line[i] == b'-') {
        i += 1;
    }
    i
}

fn skip_ws(line: &[u8], mut i: usize) -> (usize, bool) {
    // returns (new pos, had whitespace); allows newlines (single)
    let start = i;
    while i < line.len() && (line[i] == b' ' || line[i] == b'\t' || line[i] == b'\n' || line[i] == b'\r') {
        i += 1;
    }
    (i, i > start)
}

/// scan an open tag starting after '<'; returns end position (after '>') or 0
pub fn scan_open_tag(line: &[u8], pos: usize) -> usize {
    let mut i = scan_tag_name(line, pos);
    if i == 0 {
        return 0;
    }
    loop {
        let (j, ws) = skip_ws(line, i);
        if j >= line.len() {
            return 0;
        }
        if line[j] == b'>' {
            return j + 1;
        }
        if line[j] == b'/' {
            if line.get(j + 1) == Some(&b'>') {
                return j + 2;
            }
            return 0;
        }
        if !ws {
            return 0;
        }
        // attribute name
        let c = line[j];
        if !(c.is_ascii_alphabetic() || c == b'_' || c == b':') {
            return 0;
        }
        let mut k = j + 1;
        while k < line.len()
            && (line[k].is_ascii_alphanumeric() || line[k] == b'_' || line[k] == b'.' || line[k] == b':' || line[k] == b'-')
        {
            k += 1;
        }
        // optional value
        let (k2, _) = skip_ws(line, k);
        if k2 < line.len() && line[k2] == b'=' {
            let (v, _) = skip_ws(line, k2 + 1);
            if v >= line.len() {
                return 0;
            }
            let q = line[v];
            if q == b'"' || q == b'\'' {
                let mut e = v + 1;
                while e < line.len() && line[e] != q {
                    e += 1;
                }
                if e >= line.len() {
                    return 0;
                }
                i = e + 1;
            } else {
                let mut e = v;
                while e < line.len() {
                    let d = line[e];
                    if d == b' ' || d == b'\t' || d == b'\n' || d == b'\r' || d == b'"' || d == b'\'' || d == b'=' || d == b'<' || d == b'>' || d == b'`' {
                        break;
                    }
                    e += 1;
                }
                if e == v {
                    return 0;
                }
                i = e;
            }
        } else {
            i = k;
        }
    }
}

/// scan closing tag starting after '</'
pub fn scan_closing_tag(line: &[u8], pos: usize) -> usize {
    let i = scan_tag_name(line, pos);
    if i == 0 {
        return 0;
    }
    let (j, _) = skip_ws(line, i);
    if j < line.len() && line[j] == b'>' {
        return j + 1;
    }
    0
}

/// Scan inline html at pos (pointing to '<'). Returns end position or 0.
pub fn scan_html_inline(s: &[u8], pos: usize) -> usize {
    let p = pos + 1;
    if p >= s.len() {
        return 0;
    }
    let c = s[p];
    if c == b'!' {
        if s[p..].starts_with(b"!-->") {
            return p + 4;
        }
        if s[p..].starts_with(b"!--->") {
            return p + 5;
        }
        if s[p..].starts_with(b"!--") {
            // comment
            let mut i = p + 3;
            while i + 2 < s.len() + 0 && i + 3 <= s.len() {
                if &s[i..i + 3] == b"-->" {
                    return i + 3;
                }
                i += 1;
            }
            return 0;
        }
        if s[p..].starts_with(b"![CDATA[") {
            let mut i = p + 8;
            while i + 3 <= s.len() {
                if &s[i..i + 3] == b"]]>" {
                    return i + 3;
                }
                i += 1;
            }
            return 0;
        }
        if p + 1 < s.len() && s[p + 1].is_ascii_alphabetic() {
            let mut i = p + 1;
            while i < s.len() {
                if s[i] == b'>' {
                    return i + 1;
                }
                i += 1;
            }
            return 0;
        }
        return 0;
    }
    if c == b'?' {
        let mut i = p + 1;
        while i + 2 <= s.len() {
            if &s[i..i + 2] == b"?>" {
                return i + 2;
            }
            i += 1;
        }
        return 0;
    }
    if c == b'/' {
        return scan_closing_tag(s, p + 1);
    }
    scan_open_tag(s, p)
}

pub fn scan_autolink_uri(s: &[u8], pos: usize) -> usize {
    // pos points after '<'; returns end position after '>' or 0
    let mut i = pos;
    if i >= s.len() || !s[i].is_ascii_alphabetic() {
        return 0;
    }
