// Block-level markdown parser, following the cmark/comrak algorithm
use crate::md_ast::*;
use crate::md_inline;
use crate::md_scan::*;
use std::collections::HashMap;

const TAB_STOP: usize = 4;
const CODE_INDENT: usize = 4;

#[derive(Clone)]
pub struct ParseOptions {
    pub superscript: bool,
}

#[derive(Clone, Debug)]
pub struct Reference {
    pub url: String,
    pub title: String,
}

pub struct Parser {
    pub arena: Arena,
    pub root: usize,
    current: usize,
    line_number: usize,
    offset: usize,
    column: usize,
    first_nonspace: usize,
    first_nonspace_column: usize,
    indent: usize,
    blank: bool,
    partially_consumed_tab: bool,
    thematic_break_kill_pos: usize,
    pub refmap: HashMap<String, Reference>,
    pub options: ParseOptions,
}

fn accepts_lines(v: &NodeValue) -> bool {
    matches!(v, NodeValue::Paragraph | NodeValue::Heading { .. } | NodeValue::CodeBlock { .. })
}

fn can_contain(parent: &NodeValue, child: &NodeValue) -> bool {
    match parent {
        NodeValue::Document
        | NodeValue::BlockQuote
        | NodeValue::FootnoteDefinition(_)
        | NodeValue::DescriptionTerm
        | NodeValue::DescriptionDetails
        | NodeValue::Item(_)
        | NodeValue::TaskItem(_) => !matches!(child, NodeValue::Item(_) | NodeValue::TaskItem(_) | NodeValue::TableRow(_) | NodeValue::TableCell),
        NodeValue::List(_) => matches!(child, NodeValue::Item(_) | NodeValue::TaskItem(_)),
        NodeValue::DescriptionList => matches!(child, NodeValue::DescriptionItem(..)),
        NodeValue::DescriptionItem(..) => matches!(child, NodeValue::DescriptionTerm | NodeValue::DescriptionDetails),
        NodeValue::Table(_) => matches!(child, NodeValue::TableRow(_)),
        NodeValue::TableRow(_) => matches!(child, NodeValue::TableCell),
        _ => false,
    }
}

pub fn normalize_label(s: &str) -> String {
    let trimmed = s.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r');
    let mut out = String::new();
    let mut last_ws = false;
    for c in trimmed.chars() {
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            if !last_ws {
                out.push(' ');
            }
            last_ws = true;
        } else {
            last_ws = false;
            // unicode case fold approximation
            for l in c.to_lowercase() {
                out.push(l);
            }
        }
    }
    // special: ẞ / ß fold to "ss"
    out.replace('ß', "ss")
}

impl Parser {
    pub fn new(options: ParseOptions) -> Parser {
        let mut arena = Arena::new();
        let root = arena.alloc(NodeValue::Document);
        arena.nodes[root].start_line = 1;
        Parser {
            arena,
            root,
            current: root,
            line_number: 0,
            offset: 0,
            column: 0,
            first_nonspace: 0,
            first_nonspace_column: 0,
            indent: 0,
            blank: false,
            partially_consumed_tab: false,
            thematic_break_kill_pos: 0,
            refmap: HashMap::new(),
            options,
        }
    }

    pub fn feed(&mut self, text: &str) {
        let bytes = text.as_bytes();
        let mut start = 0;
        let mut lines: Vec<Vec<u8>> = Vec::new();
        let mut i = 0;
        while i < bytes.len() {
            let c = bytes[i];
            if c == b'\n' || c == b'\r' {
                let mut line = bytes[start..i].to_vec();
                line.push(b'\n');
                if c == b'\r' && i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                    i += 1;
                }
                lines.push(line);
                start = i + 1;
            } else if c == 0 {
                // replace NUL by U+FFFD later
            }
            i += 1;
        }
        if start < bytes.len() {
            let mut line = bytes[start..].to_vec();
            line.push(b'\n');
            lines.push(line);
        }
        for line in lines {
            // replace NUL
            let line: Vec<u8> = if line.contains(&0) {
                let mut v = Vec::new();
                for &b in &line {
                    if b == 0 {
                        v.extend_from_slice("\u{FFFD}".as_bytes());
                    } else {
                        v.push(b);
                    }
                }
                v
            } else {
                line
            };
            self.process_line(&line);
        }
    }

    pub fn finish(mut self) -> (Arena, usize, HashMap<String, Reference>) {
        while self.current != self.root {
            let p = self.finalize(self.current);
            self.current = p;
        }
        self.finalize(self.root);
        // inline parsing
        let root = self.root;
        self.process_inlines(root);
        // footnotes
        self.process_footnotes();
        let refmap = std::mem::take(&mut self.refmap);
        (self.arena, self.root, refmap)
    }

    fn val(&self, n: usize) -> &NodeValue {
        &self.arena.nodes[n].value
    }

    fn last_child_is_open(&self, n: usize) -> bool {
        match self.arena.last_child(n) {
            Some(c) => self.arena.nodes[c].open,
            None => false,
        }
    }

    fn find_first_nonspace(&mut self, line: &[u8]) {
        let mut chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
        if self.first_nonspace <= self.offset {
            self.first_nonspace = self.offset;
            self.first_nonspace_column = self.column;
            loop {
                match line.get(self.first_nonspace) {
                    Some(b' ') => {
                        self.first_nonspace += 1;
                        self.first_nonspace_column += 1;
                        chars_to_tab -= 1;
                        if chars_to_tab == 0 {
                            chars_to_tab = TAB_STOP;
                        }
                    }
                    Some(b'\t') => {
                        self.first_nonspace += 1;
                        self.first_nonspace_column += chars_to_tab;
                        chars_to_tab = TAB_STOP;
                    }
                    _ => break,
                }
            }
        }
        self.indent = self.first_nonspace_column - self.column;
        self.blank = is_line_end(line.get(self.first_nonspace));
    }

    fn advance_offset(&mut self, line: &[u8], mut count: usize, columns: bool) {
        while count > 0 {
            match line.get(self.offset) {
                None => break,
                Some(b'\t') => {
                    let chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
                    if columns {
                        self.partially_consumed_tab = chars_to_tab > count;
                        let chars_to_advance = count.min(chars_to_tab);
                        self.column += chars_to_advance;
                        if !self.partially_consumed_tab {
                            self.offset += 1;
                        }
                        count -= chars_to_advance;
                    } else {
                        self.partially_consumed_tab = false;
                        self.column += chars_to_tab;
                        self.offset += 1;
                        count -= 1;
                    }
                }
                Some(_) => {
                    self.partially_consumed_tab = false;
                    self.offset += 1;
                    self.column += 1;
                    count -= 1;
                }
            }
        }
    }

    fn add_line(&mut self, node: usize, line: &[u8]) {
        let mut s = String::new();
        if self.partially_consumed_tab {
            self.offset += 1;
            let chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
            for _ in 0..chars_to_tab {
                s.push(' ');
            }
        }
        if self.offset < line.len() {
            s.push_str(&String::from_utf8_lossy(&line[self.offset..]));
        }
        self.arena.nodes[node].content.push_str(&s);
    }

    fn add_child(&mut self, mut parent: usize, value: NodeValue) -> usize {
        while !can_contain(&self.arena.nodes[parent].value, &value) {
            parent = self.finalize(parent);
        }
        let n = self.arena.alloc(value);
        self.arena.nodes[n].start_line = self.line_number;
        self.arena.append(parent, n);
        n
    }

    fn process_line(&mut self, line: &[u8]) {
        self.offset = 0;
        self.column = 0;
        self.first_nonspace = 0;
        self.first_nonspace_column = 0;
        self.indent = 0;
        self.blank = false;
        self.partially_consumed_tab = false;
        self.thematic_break_kill_pos = 0;
        self.line_number += 1;

        let (all_matched, last_matched) = match self.check_open_blocks(line) {
            Some(x) => x,
            None => return,
        };
        let mut container = last_matched;
        let current = self.current;
        self.open_new_blocks(&mut container, line, all_matched);
        if current == self.current {
            self.add_text_to_container(container, last_matched, line);
        }
    }

    fn check_open_blocks(&mut self, line: &[u8]) -> Option<(bool, usize)> {
        let mut container = self.root;
        let mut all_matched = false;
        let mut should_continue = true;
        'outer: loop {
            if !self.last_child_is_open(container) {
                all_matched = true;
                break;
            }
            container = self.arena.last_child(container).unwrap();
            self.find_first_nonspace(line);
            let v = self.arena.nodes[container].value.clone();
            match v {
                NodeValue::BlockQuote => {
                    if !self.parse_block_quote_prefix(line) {
                        break 'outer;
                    }
                }
                NodeValue::Item(ref ld) => {
                    let need = ld.marker_offset + ld.padding;
                    if self.indent >= need {
                        self.advance_offset(line, need, true);
                    } else if self.blank && !self.arena.nodes[container].children.is_empty() {
                        let n = self.first_nonspace - self.offset;
                        self.advance_offset(line, n, false);
                    } else {
                        break 'outer;
                    }
                }
                NodeValue::DescriptionItem(marker_offset, padding) => {
                    let need = marker_offset + padding;
                    if self.indent >= need {
                        self.advance_offset(line, need, true);
                    } else if self.blank && !self.arena.nodes[container].children.is_empty() {
                        let n = self.first_nonspace - self.offset;
                        self.advance_offset(line, n, false);
                    } else {
                        break 'outer;
                    }
                }
                NodeValue::CodeBlock { fenced, fence_char, fence_length, fence_offset, .. } => {
                    if !fenced {
                        if self.indent >= CODE_INDENT {
                            self.advance_offset(line, CODE_INDENT, true);
                        } else if self.blank {
                            let n = self.first_nonspace - self.offset;
                            self.advance_offset(line, n, false);
                        } else {
                            break 'outer;
                        }
                    } else {
                        let mut matched = 0;
                        if self.indent <= 3 && line.get(self.first_nonspace) == Some(&fence_char) {
                            matched = close_code_fence(line, self.first_nonspace);
                        }
                        if matched >= fence_length && matched > 0 {
                            should_continue = false;
                            let n = self.first_nonspace + matched - self.offset;
                            self.advance_offset(line, n, false);
                            let p = self.finalize(container);
                            self.current = p;
                            break 'outer;
                        } else {
                            let mut i = fence_offset;
                            while i > 0 {
                                match line.get(self.offset) {
                                    Some(&c) if is_space_or_tab(c) => {
                                        self.advance_offset(line, 1, true);
                                        i -= 1;
                                    }
                                    _ => break,
                                }
                            }
                        }
                    }
                }
                NodeValue::Heading { .. } => {
                    break 'outer;
                }
                NodeValue::HtmlBlock { block_type, .. } => match block_type {
                    1..=5 => {}
                    _ => {
                        if self.blank {
                            break 'outer;
                        }
                    }
                },
                NodeValue::Paragraph => {
                    if self.blank {
                        break 'outer;
                    }
                }
                NodeValue::Table(_) => {
                    // continue if line is a row
                    if self.blank {
                        break 'outer;
                    }
                    let rest = &line[self.first_nonspace..];
                    if md_inline::table_row_cells(rest).is_none() {
                        break 'outer;
                    }
                }
                NodeValue::FootnoteDefinition(_) => {
                    if self.indent >= 4 {
                        self.advance_offset(line, 4, true);
                    } else if line == b"\n" || line == b"\r\n" {
                    } else {
                        break 'outer;
                    }
                }
                _ => {}
            }
        }
        if !should_continue {
            return None;
        }
        if !all_matched {
            container = self.arena.nodes[container].parent.unwrap();
        }
        Some((all_matched, container))
    }

    fn parse_block_quote_prefix(&mut self, line: &[u8]) -> bool {
        if self.indent <= 3 && line.get(self.first_nonspace) == Some(&b'>') {
            let n = self.indent + 1;
            self.advance_offset(line, n, true);
            if let Some(&c) = line.get(self.offset) {
                if is_space_or_tab(c) {
                    self.advance_offset(line, 1, true);
                }
            }
            return true;
        }
        false
    }

    fn open_new_blocks(&mut self, container: &mut usize, line: &[u8], all_matched: bool) {
        let mut maybe_lazy = matches!(self.val(self.current), NodeValue::Paragraph);
        loop {
            let cont_val = self.arena.nodes[*container].value.clone();
            if matches!(cont_val, NodeValue::CodeBlock { .. } | NodeValue::HtmlBlock { .. }) {
                break;
            }
            self.find_first_nonspace(line);
            let indented = self.indent >= CODE_INDENT;
            let fns = self.first_nonspace;
            let c = line.get(fns).cloned().unwrap_or(b'\n');
            let is_para = matches!(cont_val, NodeValue::Paragraph);

            if !indented && c == b'>' {
                let n = fns + 1 - self.offset;
                self.advance_offset(line, n, false);
                if let Some(&d) = line.get(self.offset) {
                    if is_space_or_tab(d) {
                        self.advance_offset(line, 1, true);
                    }
                }
                *container = self.add_child(*container, NodeValue::BlockQuote);
            } else if !indented && { let m = atx_heading_start(line, fns); m > 0 } {
                let matched = atx_heading_start(line, fns);
                let n = fns + matched - self.offset;
                self.advance_offset(line, n, false);
                let mut level = 0u8;
                let mut p = fns;
                while line.get(p) == Some(&b'#') {
                    level += 1;
                    p += 1;
                }
                *container = self.add_child(*container, NodeValue::Heading { level, setext: false });
            } else if !indented && open_code_fence(line, fns) > 0 {
                let matched = open_code_fence(line, fns);
                let fence_offset = fns - self.offset;
                *container = self.add_child(
                    *container,
                    NodeValue::CodeBlock {
                        fenced: true,
                        fence_char: c,
                        fence_length: matched,
                        fence_offset,
                        info: String::new(),
                        literal: String::new(),
                    },
                );
                let n = fns + matched - self.offset;
                self.advance_offset(line, n, false);
            } else if !indented
                && ({
                    let t = html_block_start(line, fns);
                    t > 0 || (!is_para && html_block_start_7(line, fns) > 0)
                })
            {
                let mut t = html_block_start(line, fns);
                if t == 0 {
                    t = 7;
                }
                *container = self.add_child(*container, NodeValue::HtmlBlock { block_type: t, literal: String::new() });
            } else if !indented && is_para && setext_heading_line(line, fns) > 0 {
                let lev = setext_heading_line(line, fns);
                let has_content = self.resolve_reference_link_definitions(*container);
                if has_content {
                    self.arena.nodes[*container].value = NodeValue::Heading { level: lev, setext: true };
                    let n = line.len() - 1 - self.offset;
                    self.advance_offset(line, n, false);
                }
            } else if !indented
                && !(is_para && !all_matched)
                && self.thematic_break_kill_pos <= fns
                && thematic_break(line, fns)
            {
                *container = self.add_child(*container, NodeValue::ThematicBreak);
                let n = line.len() - 1 - self.offset;
                self.advance_offset(line, n, false);
            } else if !indented && c == b'[' && line.get(fns + 1) == Some(&b'^') && scan_footnote_def(line, fns).is_some() {
                let (matched, name) = scan_footnote_def(line, fns).unwrap();
                let n = fns + matched - self.offset;
                self.advance_offset(line, n, false);
                *container = self.add_child(*container, NodeValue::FootnoteDefinition(name));
            } else if !indented && c == b':' && self.parse_desc_list_details(container) {
                let n = fns + 1 - self.offset;
                self.advance_offset(line, n, false);
                if let Some(&d) = line.get(self.offset) {
                    if is_space_or_tab(d) {
                        self.advance_offset(line, 1, true);
                    }
                }
            } else if (!indented || matches!(cont_val, NodeValue::List(_)))
                && self.indent < 4
                && parse_list_marker(line, fns, is_para).is_some()
            {
                let (matched, mut data) = parse_list_marker(line, fns, is_para).unwrap();
                let n = fns + matched - self.offset;
                self.advance_offset(line, n, false);
                let save_ptab = self.partially_consumed_tab;
                let save_offset = self.offset;
                let save_column = self.column;
                while self.column - save_column <= 5 {
                    match line.get(self.offset) {
                        Some(&d) if is_space_or_tab(d) => self.advance_offset(line, 1, true),
                        _ => break,
                    }
                }
                let i = self.column - save_column;
                if i >= 5 || i < 1 || is_line_end(line.get(self.offset)) {
                    data.padding = matched + 1;
                    self.offset = save_offset;
                    self.column = save_column;
                    self.partially_consumed_tab = save_ptab;
                    if i > 0 {
                        self.advance_offset(line, 1, true);
                    }
                } else {
                    data.padding = matched + i;
                }
                data.marker_offset = self.indent;
                let matches_list = match &self.arena.nodes[*container].value {
                    NodeValue::List(ld) => ld.list_type == data.list_type && ld.delimiter == data.delimiter && ld.bullet_char == data.bullet_char,
                    _ => false,
                };
                if !matches_list {
                    *container = self.add_child(*container, NodeValue::List(data.clone()));
                }
                *container = self.add_child(*container, NodeValue::Item(data));
            } else if indented && !maybe_lazy && !self.blank {
                self.advance_offset(line, CODE_INDENT, true);
                *container = self.add_child(
                    *container,
                    NodeValue::CodeBlock {
                        fenced: false,
                        fence_char: 0,
                        fence_length: 0,
                        fence_offset: 0,
                        info: String::new(),
                        literal: String::new(),
                    },
                );
            } else if !indented && is_para && !self.arena.nodes[*container].table_visited && self.try_open_table(*container, line) {
                // table created; container updated
                let t = self.arena.nodes[*container].parent.unwrap();
                let _ = t;
                // the table node is now the last child of the parent
                let parent = self.arena.nodes[*container].parent;
                let _ = parent;
                *container = self.last_table.unwrap();
                let n = line.len() - 1 - self.offset;
                self.advance_offset(line, n, false);
                break;
            } else if matches!(cont_val, NodeValue::Table(_)) && !self.blank {
                // table row
                let rest = line[fns..].to_vec();
                if let Some(cells) = md_inline::table_row_cells(&rest) {
                    let ncols = match &cont_val {
                        NodeValue::Table(a) => a.len(),
                        _ => 0,
                    };
                    let row = self.arena.alloc(NodeValue::TableRow(false));
                    self.arena.nodes[row].open = false;
                    self.arena.append(*container, row);
                    for k in 0..ncols {
                        let cell = self.arena.alloc(NodeValue::TableCell);
                        self.arena.nodes[cell].open = false;
                        if k < cells.len() {
                            self.arena.nodes[cell].content = cells[k].clone();
                        }
                        self.arena.append(row, cell);
                    }
                    let n = line.len() - 1 - self.offset;
                    self.advance_offset(line, n, false);
                    // signal: row consumed
                    self.row_added = true;
                }
                break;
            } else {
                break;
            }

            if accepts_lines(&self.arena.nodes[*container].value) {
                break;
            }
            maybe_lazy = false;
        }
    }

    fn parse_desc_list_details(&mut self, container: &mut usize) -> bool {
        let (parent, last_child) = match self.arena.last_child(*container) {
            Some(lc) => (*container, lc),
            None => {
                if matches!(self.val(*container), NodeValue::Paragraph) {
                    match self.arena.nodes[*container].parent {
                        Some(p) => (p, *container),
                        None => return false,
                    }
                } else {
                    return false;
                }
            }
        };
        if matches!(self.val(last_child), NodeValue::Paragraph) {
            // close paragraph
            if self.arena.nodes[last_child].open {
                self.finalize(last_child);
                if self.arena.nodes[last_child].parent.is_none() {
                    // paragraph vanished (only references)
                    return false;
                }
            }
            self.arena.detach(last_child);
            let list = match self.arena.last_child(parent) {
                Some(lc) if matches!(self.val(lc), NodeValue::DescriptionList) => {
                    self.arena.nodes[lc].open = true;
                    lc
                }
                _ => self.add_child(parent, NodeValue::DescriptionList),
            };
            let indent = self.indent;
            let item = self.add_child(list, NodeValue::DescriptionItem(indent, 2));
            let term = self.add_child(item, NodeValue::DescriptionTerm);
            self.arena.append(term, last_child);
            self.arena.nodes[term].open = false;
            let details = self.add_child(item, NodeValue::DescriptionDetails);
            *container = details;
            self.current = details;
            true
        } else if matches!(self.val(last_child), NodeValue::DescriptionItem(..)) {
            self.arena.nodes[last_child].open = true;
            if let Some(p) = self.arena.nodes[last_child].parent {
                self.arena.nodes[p].open = true;
            }
            let details = self.add_child(last_child, NodeValue::DescriptionDetails);
            *container = details;
            self.current = details;
            true
        } else {
            false
        }
    }

    fn try_open_table(&mut self, para: usize, line: &[u8]) -> bool {
        let fns = self.first_nonspace;
        let rest = &line[fns..];
        let aligns = match md_inline::table_delimiter_row(rest) {
            Some(a) => a,
            None => return false,
        };
        let content = self.arena.nodes[para].content.clone();
        // header row is the last line of paragraph content
        let trimmed = content.strip_suffix('\n').unwrap_or(&content);
        let (before, last_line) = match trimmed.rfind('\n') {
            Some(p) => (&trimmed[..p + 1], &trimmed[p + 1..]),
            None => ("", trimmed),
        };
        let header_cells = match md_inline::table_row_cells(last_line.as_bytes()) {
            Some(c) => c,
            None => {
                self.arena.nodes[para].table_visited = true;
                return false;
            }
        };
        if header_cells.len() != aligns.len() {
            self.arena.nodes[para].table_visited = true;
            return false;
        }
        let parent = self.arena.nodes[para].parent.unwrap();
        let table = self.arena.alloc(NodeValue::Table(aligns.clone()));
        self.arena.nodes[table].start_line = self.line_number;
        if before.is_empty() {
            // replace paragraph by table
            let idx = self.arena.nodes[parent].children.iter().position(|&c| c == para).unwrap();
            self.arena.nodes[parent].children[idx] = table;
            self.arena.nodes[table].parent = Some(parent);
            self.arena.nodes[para].parent = None;
        } else {
            self.arena.nodes[para].content = before.to_string();
            self.finalize(para);
            self.arena.append(parent, table);
        }
        let row = self.arena.alloc(NodeValue::TableRow(true));
        self.arena.nodes[row].open = false;
        self.arena.append(table, row);
        for k in 0..aligns.len() {
            let cell = self.arena.alloc(NodeValue::TableCell);
            self.arena.nodes[cell].open = false;
            self.arena.nodes[cell].content = header_cells[k].clone();
            self.arena.append(row, cell);
        }
        self.current = table;
        self.last_table = Some(table);
        true
    }

    fn add_text_to_container(&mut self, container: usize, last_matched: usize, line: &[u8]) {
        self.find_first_nonspace(line);
        if self.row_added {
            self.row_added = false;
            self.current = container;
            return;
        }
        if self.blank {
            if let Some(lc) = self.arena.last_child(container) {
                self.arena.nodes[lc].last_line_blank = true;
            }
        }
        let cval = &self.arena.nodes[container].value;
        let last_line_blank = self.blank
            && !matches!(cval, NodeValue::BlockQuote | NodeValue::Heading { .. } | NodeValue::ThematicBreak)
            && !matches!(cval, NodeValue::CodeBlock { fenced: true, .. })
            && !(matches!(cval, NodeValue::Item(_)) && self.arena.nodes[container].children.is_empty() && self.arena.nodes[container].start_line == self.line_number);
        self.arena.nodes[container].last_line_blank = last_line_blank;
        let mut tmp = container;
        while let Some(p) = self.arena.nodes[tmp].parent {
            self.arena.nodes[p].last_line_blank = false;
            tmp = p;
        }

        if self.current != last_matched && container == last_matched && !self.blank && matches!(self.val(self.current), NodeValue::Paragraph) {
            let cur = self.current;
            self.add_line(cur, line);
            return;
        }
        while self.current != last_matched {
            let p = self.finalize(self.current);
            self.current = p;
        }
        let mut container = container;
        let cval = self.arena.nodes[container].value.clone();
        match cval {
            NodeValue::CodeBlock { .. } => {
                self.add_line(container, line);
            }
            NodeValue::HtmlBlock { block_type, .. } => {
                self.add_line(container, line);
                if html_block_end(block_type, line, self.first_nonspace) {
                    let p = self.finalize(container);
                    container = p;
                }
            }
            _ => {
                if self.blank {
                } else if accepts_lines(&cval) {
                    let n = self.first_nonspace - self.offset;
                    self.advance_offset(line, n, false);
                    if let NodeValue::Heading { setext: false, .. } = cval {
                        let chopped = chop_trailing_hashes(&line[..]);
                        self.add_line(container, &chopped);
                    } else {
                        self.add_line(container, line);
                    }
                } else if matches!(cval, NodeValue::Table(_)) {
                    // shouldn't happen
                } else {
                    container = self.add_child(container, NodeValue::Paragraph);
                    let n = self.first_nonspace - self.offset;
                    self.advance_offset(line, n, false);
                    self.add_line(container, line);
                }
            }
        }
        self.current = container;
    }

    fn finalize(&mut self, node: usize) -> usize {
        let parent = self.arena.nodes[node].parent;
        if !self.arena.nodes[node].open {
            return parent.unwrap_or(self.root);
        }
        self.arena.nodes[node].open = false;
        let v = self.arena.nodes[node].value.clone();
        match v {
            NodeValue::Paragraph => {
                let has_content = self.resolve_reference_link_definitions(node);
                if !has_content {
                    self.arena.detach(node);
                }
            }
            NodeValue::CodeBlock { fenced, fence_char, fence_length, fence_offset, .. } => {
                let content = std::mem::take(&mut self.arena.nodes[node].content);
                if !fenced {
                    // remove trailing blank lines
                    let mut lines: Vec<&str> = content.split_inclusive('\n').collect();
                    while let Some(l) = lines.last() {
                        if l.trim_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r').is_empty() {
                            lines.pop();
                        } else {
                            break;
                        }
                    }
                    let mut lit: String = lines.concat();
                    if !lit.is_empty() && !lit.ends_with('\n') {
                        lit.push('\n');
                    }
                    self.arena.nodes[node].value = NodeValue::CodeBlock {
                        fenced,
                        fence_char,
                        fence_length,
                        fence_offset,
                        info: String::new(),
                        literal: lit,
                    };
                } else {
                    let (first, rest) = match content.find('\n') {
                        Some(p) => (&content[..p], &content[p + 1..]),
                        None => (&content[..], ""),
                    };
                    let info = md_inline::unescape_string(first.trim_matches(|c| c == ' ' || c == '\t'));
                    self.arena.nodes[node].value = NodeValue::CodeBlock {
                        fenced,
                        fence_char,
                        fence_length,
                        fence_offset,
                        info,
                        literal: rest.to_string(),
                    };
                }
            }
            NodeValue::HtmlBlock { block_type, .. } => {
                let content = std::mem::take(&mut self.arena.nodes[node].content);
                self.arena.nodes[node].value = NodeValue::HtmlBlock { block_type, literal: content };
            }
            NodeValue::List(mut ld) => {
                // determine tightness
                let mut tight = true;
                let items = self.arena.nodes[node].children.clone();
                'outer: for (ii, &item) in items.iter().enumerate() {
                    if self.ends_with_blank_line(item) && ii + 1 < items.len() {
                        tight = false;
                        break;
                    }
                    let subs = self.arena.nodes[item].children.clone();
                    for (si, &sub) in subs.iter().enumerate() {
                        if self.ends_with_blank_line(sub) && (ii + 1 < items.len() || si + 1 < subs.len()) {
                            tight = false;
                            break 'outer;
                        }
                    }
                }
                ld.tight = tight;
                self.arena.nodes[node].value = NodeValue::List(ld);
            }
            _ => {}
        }
        parent.unwrap_or(self.root)
    }

    fn ends_with_blank_line(&self, node: usize) -> bool {
        let mut n = node;
        loop {
            if self.arena.nodes[n].last_line_blank {
                return true;
            }
            match &self.arena.nodes[n].value {
                NodeValue::List(_) | NodeValue::Item(_) => match self.arena.last_child(n) {
                    Some(c) => n = c,
                    None => return false,
                },
                _ => return false,
            }
        }
    }

    /// Parse reference definitions at start of paragraph; returns true if content remains
    fn resolve_reference_link_definitions(&mut self, node: usize) -> bool {
        let content = self.arena.nodes[node].content.clone();
        let bytes = content.as_bytes();
        let mut pos = 0;
        while pos < bytes.len() && bytes[pos] == b'[' {
            match md_inline::parse_reference(&bytes[pos..]) {
                Some((consumed, label, url, title)) => {
                    let key = normalize_label(&label);
                    if !key.is_empty() && !self.refmap.contains_key(&key) {
                        self.refmap.insert(key, Reference { url, title });
                    }
                    pos += consumed;
                }
                None => break,
            }
        }
        let rest = content[pos..].to_string();
        self.arena.nodes[node].content = rest.clone();
        !rest.trim_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r').is_empty()
    }

    fn process_inlines(&mut self, node: usize) {
        let children = self.arena.nodes[node].children.clone();
        let v = self.arena.nodes[node].value.clone();
        match v {
            NodeValue::Paragraph | NodeValue::Heading { .. } | NodeValue::TableCell => {
                let content = std::mem::take(&mut self.arena.nodes[node].content);
                let content = match v {
                    NodeValue::Heading { .. } => content.trim_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r').to_string(),
                    _ => content,
                };
                md_inline::parse_inlines(self, node, &content);
            }
            _ => {
                for c in children {
                    self.process_inlines(c);
                }
            }
        }
    }

    fn process_footnotes(&mut self) {
        // collect definitions
        let mut defs: HashMap<String, usize> = HashMap::new();
        let mut def_list = Vec::new();
        self.collect_footnote_defs(self.root, &mut defs, &mut def_list);
        // walk references in document order
        let mut order: Vec<String> = Vec::new();
        let mut refs = Vec::new();
        self.collect_footnote_refs(self.root, &mut refs);
        for r in refs {
            let name = match &self.arena.nodes[r].value {
                NodeValue::FootnoteReference(n) => n.clone(),
                _ => continue,
            };
            let key = normalize_label(&name);
            if defs.contains_key(&key) {
                if !order.contains(&key) {
                    order.push(key);
                }
            } else {
                // convert back to text
                self.arena.nodes[r].value = NodeValue::Text(format!("[^{}]", name));
            }
        }
        // remove all definitions, then append referenced ones in order
        for &d in &def_list {
            self.arena.detach(d);
        }
        for key in order {
            let d = defs[&key];
            self.arena.append(self.root, d);
        }
        // merge adjacent text nodes created by conversion
        md_inline::merge_text_nodes(&mut self.arena, self.root);
    }

    fn collect_footnote_defs(&self, node: usize, defs: &mut HashMap<String, usize>, list: &mut Vec<usize>) {
        for &c in &self.arena.nodes[node].children {
            if let NodeValue::FootnoteDefinition(name) = &self.arena.nodes[c].value {
                let key = normalize_label(name);
                if !defs.contains_key(&key) {
                    defs.insert(key, c);
                }
                list.push(c);
            }
            self.collect_footnote_defs(c, defs, list);
        }
    }

    fn collect_footnote_refs(&self, node: usize, refs: &mut Vec<usize>) {
        for &c in &self.arena.nodes[node].children {
            if let NodeValue::FootnoteReference(_) = &self.arena.nodes[c].value {
                refs.push(c);
            }
            self.collect_footnote_refs(c, refs);
        }
    }
}

fn chop_trailing_hashes(line: &[u8]) -> Vec<u8> {
    // line includes trailing newline
    let mut v: Vec<u8> = line.to_vec();
    let had_nl = v.last() == Some(&b'\n');
    if had_nl {
        v.pop();
    }
    // rtrim spaces
    while let Some(&c) = v.last() {
        if c == b' ' || c == b'\t' {
            v.pop();
        } else {
            break;
        }
    }
    let orig_len = v.len();
    let mut n = orig_len;
    while n > 0 && v[n - 1] == b'#' {
        n -= 1;
    }
    if n != orig_len {
        // hashes must be preceded by space or be the whole content
        if n == 0 {
            v.truncate(0);
        } else if v[n - 1] == b' ' || v[n - 1] == b'\t' {
            v.truncate(n);
            while let Some(&c) = v.last() {
                if c == b' ' || c == b'\t' {
                    v.pop();
                } else {
                    break;
                }
            }
        }
    }
    v.push(b'\n');
    v
}

fn scan_footnote_def(line: &[u8], pos: usize) -> Option<(usize, String)> {
    // [^label]: 
    let mut i = pos + 2;
    let start = i;
    while i < line.len() {
        let c = line[i];
        if c == b']' {
            break;
        }
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
            return None;
        }
        if c == b'\\' && i + 1 < line.len() {
            i += 2;
            continue;
        }
        i += 1;
    }
    if i >= line.len() || i == start {
        return None;
    }
    let name = String::from_utf8_lossy(&line[start..i]).to_string();
    i += 1;
    if line.get(i) != Some(&b':') {
        return None;
    }
    i += 1;
    while i < line.len() && (line[i] == b' ' || line[i] == b'\t') {
        i += 1;
    }
    Some((i - pos, name))
}

fn parse_list_marker(line: &[u8], pos: usize, interrupts_paragraph: bool) -> Option<(usize, ListData)> {
    let c = *line.get(pos)?;
    if c == b'*' || c == b'-' || c == b'+' {
        if thematic_break(line, pos) {
            return None;
        }
        let next = line.get(pos + 1).cloned().unwrap_or(b'\n');
        if !(next == b' ' || next == b'\t' || next == b'\n' || next == b'\r') {
            return None;
        }
        if interrupts_paragraph {
            // must not be blank after marker
            let mut i = pos + 1;
            while i < line.len() && (line[i] == b' ' || line[i] == b'\t') {
                i += 1;
            }
            if is_line_end(line.get(i)) {
                return None;
            }
        }
        return Some((
            1,
            ListData {
                list_type: ListType::Bullet,
                marker_offset: 0,
                padding: 0,
                start: 0,
                delimiter: 0,
                bullet_char: c,
                tight: false,
            },
        ));
    }
    if c.is_ascii_digit() {
        let mut i = pos;
        let mut start: usize = 0;
        let mut digits = 0;
        while i < line.len() && line[i].is_ascii_digit() && digits < 9 {
            start = start * 10 + (line[i] - b'0') as usize;
            i += 1;
            digits += 1;
        }
        if i < line.len() && line[i].is_ascii_digit() {
            return None;
        }
        if interrupts_paragraph && start != 1 {
            return None;
        }
        let d = *line.get(i)?;
        if d != b'.' && d != b')' {
            return None;
        }
        i += 1;
        let next = line.get(i).cloned().unwrap_or(b'\n');
        if !(next == b' ' || next == b'\t' || next == b'\n' || next == b'\r') {
            return None;
        }
        if interrupts_paragraph {
            let mut j = i;
            while j < line.len() && (line[j] == b' ' || line[j] == b'\t') {
                j += 1;
            }
            if is_line_end(line.get(j)) {
                return None;
            }
        }
        return Some((
            i - pos,
            ListData {
                list_type: ListType::Ordered,
                marker_offset: 0,
                padding: 0,
                start,
                delimiter: d,
                bullet_char: 0,
                tight: false,
            },
        ));
    }
    None
}
