// Inline markdown parser (port of cmark/comrak inline algorithm)
use crate::entities::ENTITIES;
use crate::md_ast::*;
use crate::md_block::{normalize_label, Parser, Reference};
use crate::md_scan::*;
use std::collections::HashMap;

#[derive(Clone, Debug)]
struct Delim {
    inl: usize,
    delim_char: u8,
    can_open: bool,
    can_close: bool,
    length: usize,
    prev: Option<usize>,
    next: Option<usize>,
}

#[derive(Clone, Debug)]
struct Bracket {
    inl_text: usize,
    position: usize,
    image: bool,
    active: bool,
    bracket_after: bool,
    previous_delimiter: Option<usize>,
}

struct Subject<'a> {
    input: Vec<u8>,
    pos: usize,
    delims: Vec<Delim>,
    last_delim: Option<usize>,
    brackets: Vec<Bracket>,
    arena: &'a mut Arena,
    refmap: &'a HashMap<String, Reference>,
    superscript: bool,
    parent: usize,
}

pub fn entity_lookup(name: &str) -> Option<&'static str> {
    match ENTITIES.binary_search_by(|(n, _)| (*n).cmp(name)) {
        Ok(i) => Some(ENTITIES[i].1),
        Err(_) => None,
    }
}

/// Try to unescape an entity at s (after '&'); returns (decoded, length consumed incl ';')
pub fn unescape_entity(s: &[u8]) -> Option<(String, usize)> {
    if s.is_empty() {
        return None;
    }
    if s[0] == b'#' {
        let mut i = 1;
        let mut cp: u32 = 0;
        let mut digits = 0;
        if i < s.len() && (s[i] == b'x' || s[i] == b'X') {
            i += 1;
            while i < s.len() && s[i].is_ascii_hexdigit() && digits < 7 {
                cp = cp * 16 + (s[i] as char).to_digit(16).unwrap();
                i += 1;
                digits += 1;
            }
            if digits == 0 || digits > 6 {
                return None;
            }
        } else {
            while i < s.len() && s[i].is_ascii_digit() && digits < 8 {
                cp = cp * 10 + (s[i] - b'0') as u32;
                i += 1;
                digits += 1;
            }
            if digits == 0 || digits > 7 {
                return None;
            }
        }
        if i < s.len() && s[i] == b';' {
            let c = if cp == 0 || cp > 0x10FFFF || (0xD800..=0xDFFF).contains(&cp) {
                '\u{FFFD}'
            } else {
                char::from_u32(cp).unwrap_or('\u{FFFD}')
            };
            return Some((c.to_string(), i + 1));
        }
        return None;
    }
    let mut i = 0;
    while i < s.len() && s[i].is_ascii_alphanumeric() && i < 40 {
        i += 1;
    }
    if i > 0 && i < s.len() && s[i] == b';' {
        let name = std::str::from_utf8(&s[..i]).ok()?;
        if let Some(v) = entity_lookup(name) {
            return Some((v.to_string(), i + 1));
        }
    }
    None
}

/// unescape backslash escapes and entities
pub fn unescape_string(s: &str) -> String {
    let b = s.as_bytes();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == b'\\' && i + 1 < b.len() && is_ascii_punct(b[i + 1]) {
            out.push(b[i + 1]);
            i += 2;
        } else if c == b'&' {
            if let Some((dec, n)) = unescape_entity(&b[i + 1..]) {
                out.extend_from_slice(dec.as_bytes());
                i += 1 + n;
            } else {
                out.push(c);
                i += 1;
            }
        } else {
            out.push(c);
            i += 1;
        }
    }
    String::from_utf8_lossy(&out).to_string()
}

fn clean_url(url: &[u8]) -> String {
    let s = String::from_utf8_lossy(url).to_string();
    let t = s.trim_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r');
    unescape_string(t)
}

fn clean_title(title: &[u8]) -> String {
    if title.len() < 2 {
        return String::new();
    }
    let first = title[0];
    let last = title[title.len() - 1];
    let inner = if (first == b'\'' && last == b'\'') || (first == b'(' && last == b')') || (first == b'"' && last == b'"') {
        &title[1..title.len() - 1]
    } else {
        title
    };
    unescape_string(&String::from_utf8_lossy(inner))
}

fn is_space_byte(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == 0x0b || c == 0x0c
}

/// Scan spaces and at most one newline
fn scan_spacechars(s: &[u8], mut i: usize) -> usize {
    let start = i;
    while i < s.len() && is_space_byte(s[i]) {
        i += 1;
    }
    i - start
}

fn manual_scan_link_url(s: &[u8], offset: usize) -> Option<(usize, usize, usize)> {
    // returns (consumed, url_start, url_end)
    let mut i = offset;
    if i < s.len() && s[i] == b'<' {
        i += 1;
        loop {
            if i >= s.len() {
                return None;
            }
            let c = s[i];
            if c == b'>' {
                i += 1;
                break;
            } else if c == b'\\' {
                i += 2;
            } else if c == b'\n' || c == b'<' {
                return None;
            } else {
                i += 1;
            }
        }
        if i > s.len() {
            return None;
        }
        return Some((i - offset, offset + 1, i - 1));
    }
    let mut nb_p = 0;
    while i < s.len() {
        let c = s[i];
        if c == b'\\' && i + 1 < s.len() && is_ascii_punct(s[i + 1]) {
            i += 2;
        } else if c == b'(' {
            nb_p += 1;
            i += 1;
            if nb_p > 32 {
                return None;
            }
        } else if c == b')' {
            if nb_p == 0 {
                break;
            }
            nb_p -= 1;
            i += 1;
        } else if is_space_byte(c) || c < 0x20 || c == 0x7f {
            if i == offset {
                return None;
            }
            break;
        } else {
            i += 1;
        }
    }
    if i >= s.len() || nb_p != 0 {
        // allow end of input for reference definitions
        if nb_p == 0 && i >= s.len() && i > offset {
            return Some((i - offset, offset, i));
        }
        return None;
    }
    Some((i - offset, offset, i))
}

fn scan_link_title(s: &[u8], i: usize) -> usize {
    if i >= s.len() {
        return 0;
    }
    let open = s[i];
    let close = match open {
        b'"' => b'"',
        b'\'' => b'\'',
        b'(' => b')',
        _ => return 0,
    };
    let mut j = i + 1;
    while j < s.len() {
        let c = s[j];
        if c == b'\\' && j + 1 < s.len() {
            j += 2;
            continue;
        }
        if c == close {
            return j + 1 - i;
        }
        if open == b'(' && c == b'(' {
            return 0;
        }
        j += 1;
    }
    0
}

/// parse a link label at s[i] == '['; returns (end pos after ']', label content)
fn link_label(s: &[u8], i: usize) -> Option<(usize, String)> {
    if i >= s.len() || s[i] != b'[' {
        return None;
    }
    let mut j = i + 1;
    let mut length = 0;
    while j < s.len() {
        let c = s[j];
        if c == b'[' {
            return None;
        }
        if c == b']' {
            let label = String::from_utf8_lossy(&s[i + 1..j]).to_string();
            if length > 999 {
                return None;
            }
            return Some((j + 1, label));
        }
        if c == b'\\' {
            j += 1;
            length += 1;
            if j < s.len() && is_ascii_punct(s[j]) {
                j += 1;
                length += 1;
            }
            continue;
        }
        j += 1;
        length += 1;
        if length > 999 {
            return None;
        }
    }
    None
}

/// Parse a reference definition at the start of s. Returns (consumed, label, url, title)
pub fn parse_reference(s: &[u8]) -> Option<(usize, String, String, String)> {
    let (mut pos, label) = link_label(s, 0)?;
    if label.trim().is_empty() {
        return None;
    }
    if s.get(pos) != Some(&b':') {
        return None;
    }
    pos += 1;
    // spnl
    pos = spnl(s, pos);
    let (n, us, ue) = manual_scan_link_url(s, pos)?;
    if n == 0 && !(pos < s.len() && s[pos] == b'<') {
        return None;
    }
    let url = clean_url(&s[us..ue]);
    pos += n;
    let beforetitle = pos;
    pos = spnl(s, pos);
    let matchlen = if pos == beforetitle { 0 } else { scan_link_title(s, pos) };
    let title;
    if matchlen > 0 {
        title = clean_title(&s[pos..pos + matchlen]);
        pos += matchlen;
    } else {
        pos = beforetitle;
        title = String::new();
    }
    // final spaces and newline
    let mut p2 = pos;
    while p2 < s.len() && (s[p2] == b' ' || s[p2] == b'\t') {
        p2 += 1;
    }
    let at_end = |p: usize| p >= s.len() || s[p] == b'\n' || s[p] == b'\r';
    if !at_end(p2) {
        if matchlen > 0 {
            let mut p3 = beforetitle;
            while p3 < s.len() && (s[p3] == b' ' || s[p3] == b'\t') {
                p3 += 1;
            }
            if !at_end(p3) {
                return None;
            }
            return Some((skip_line_end(s, p3), label, url, String::new()));
        }
        return None;
    }
    Some((skip_line_end(s, p2), label, url, title))
}

fn skip_line_end(s: &[u8], mut p: usize) -> usize {
    if p < s.len() && s[p] == b'\r' {
        p += 1;
    }
    if p < s.len() && s[p] == b'\n' {
        p += 1;
    }
    p
}

fn spnl(s: &[u8], mut pos: usize) -> usize {
    while pos < s.len() && (s[pos] == b' ' || s[pos] == b'\t') {
        pos += 1;
    }
    if pos < s.len() && (s[pos] == b'\n' || s[pos] == b'\r') {
        pos = skip_line_end(s, pos);
        while pos < s.len() && (s[pos] == b' ' || s[pos] == b'\t') {
            pos += 1;
        }
    }
    pos
}

// ---------------- tables -----------------

/// Parse a table row; returns cells (unescaped pipes, trimmed) or None
pub fn table_row_cells(line: &[u8]) -> Option<Vec<String>> {
    let mut s: Vec<u8> = line.to_vec();
    while let Some(&c) = s.last() {
        if c == b'\n' || c == b'\r' {
            s.pop();
        } else {
            break;
        }
    }
    let len = s.len();
    let mut offset = 0;
    // optional leading pipe
    offset += scan_cell_end(&s, 0);
    let mut cells = Vec::new();
    let mut expect_more = true;
    while offset < len && expect_more {
        let cell_matched = scan_cell(&s, offset);
        let pipe_matched = scan_cell_end(&s, offset + cell_matched);
        if cell_matched > 0 || pipe_matched > 0 {
            let raw = &s[offset..offset + cell_matched];
            // unescape pipes
            let mut buf: Vec<u8> = Vec::new();
            let mut k = 0;
            while k < raw.len() {
                if raw[k] == b'\\' && k + 1 < raw.len() && raw[k + 1] == b'|' {
                    buf.push(b'|');
                    k += 2;
                } else {
                    buf.push(raw[k]);
                    k += 1;
                }
            }
            let cell = String::from_utf8_lossy(&buf).trim_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0b' || c == '\x0c').to_string();
            cells.push(cell);
        }
        offset += cell_matched + pipe_matched;
        if pipe_matched > 0 {
            expect_more = true;
        } else {
            // end of row: trailing spaces
            let mut e = offset;
            while e < len && (s[e] == b' ' || s[e] == b'\t') {
                e += 1;
            }
            if e == len {
                offset = len;
            }
            expect_more = false;
        }
    }
    if offset != len || cells.is_empty() {
        return None;
    }
    Some(cells)
}

fn scan_cell(s: &[u8], mut i: usize) -> usize {
    let start = i;
    while i < s.len() {
        let c = s[i];
        if c == b'\\' && i + 1 < s.len() {
            i += 2;
            continue;
        }
        if c == b'|' || c == b'\n' || c == b'\r' {
            break;
        }
        i += 1;
    }
    i.min(s.len()) - start
}

fn scan_cell_end(s: &[u8], i: usize) -> usize {
    if i < s.len() && s[i] == b'|' {
        let mut j = i + 1;
        while j < s.len() && (s[j] == b' ' || s[j] == b'\t') {
            j += 1;
        }
        j - i
    } else {
        0
    }
}

/// Parse a delimiter row; returns alignments
pub fn table_delimiter_row(line: &[u8]) -> Option<Vec<Align>> {
    let mut s: Vec<u8> = line.to_vec();
    while let Some(&c) = s.last() {
        if c == b'\n' || c == b'\r' || c == b' ' || c == b'\t' {
            s.pop();
        } else {
            break;
        }
    }
    let text = String::from_utf8_lossy(&s).to_string();
    let mut t = text.as_str();
    let has_leading = t.starts_with('|');
    if has_leading {
        t = &t[1..];
    }
    if t.ends_with('|') && !t.ends_with("\\|") {
        t = &t[..t.len() - 1];
    }
    let parts: Vec<&str> = t.split('|').collect();
    if parts.len() == 1 && !has_leading && !text.contains('|') {
        // single column without pipes is not a delimiter row... unless it's ":--" etc
        let p = parts[0].trim();
        if !(p.starts_with(':') || p.ends_with(':')) || true {
            // cmark-gfm requires at least a pipe or colon? Accept only with pipe
            return None;
        }
    }
    let mut aligns = Vec::new();
    for p in parts {
        let p = p.trim_matches(|c| c == ' ' || c == '\t');
        if p.is_empty() {
            return None;
        }
        let left = p.starts_with(':');
        let right = p.ends_with(':') && p.len() > 1 || (p == ":" && false);
        let inner = p.trim_start_matches(':').trim_end_matches(':');
        if inner.is_empty() || !inner.chars().all(|c| c == '-') {
            return None;
        }
        // ensure at most one colon each side
        let lc = p.len() - p.trim_start_matches(':').len();
        let rc = p.len() - p.trim_end_matches(':').len();
        if lc > 1 || rc > 1 {
            return None;
        }
        aligns.push(match (left, right) {
            (true, true) => Align::Center,
            (true, false) => Align::Left,
            (false, true) => Align::Right,
            _ => Align::None,
        });
    }
    Some(aligns)
}

// ---------------- tree helpers -----------------

fn next_sibling(arena: &Arena, n: usize) -> Option<usize> {
    let p = arena.nodes[n].parent?;
    let ch = &arena.nodes[p].children;
    let idx = ch.iter().position(|&c| c == n)?;
    ch.get(idx + 1).cloned()
}

fn insert_after(arena: &mut Arena, n: usize, new: usize) {
    let p = arena.nodes[n].parent.unwrap();
    let idx = arena.nodes[p].children.iter().position(|&c| c == n).unwrap();
    arena.nodes[p].children.insert(idx + 1, new);
    arena.nodes[new].parent = Some(p);
}

fn insert_before(arena: &mut Arena, n: usize, new: usize) {
    let p = arena.nodes[n].parent.unwrap();
    let idx = arena.nodes[p].children.iter().position(|&c| c == n).unwrap();
    arena.nodes[p].children.insert(idx, new);
    arena.nodes[new].parent = Some(p);
}

fn text_of(arena: &Arena, n: usize) -> String {
    match &arena.nodes[n].value {
        NodeValue::Text(t) => t.clone(),
        _ => String::new(),
    }
}

impl<'a> Subject<'a> {
    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).cloned()
    }
    fn peek_at(&self, p: usize) -> Option<u8> {
        self.input.get(p).cloned()
    }
    fn eof(&self) -> bool {
        self.pos >= self.input.len()
    }
    fn make_text(&mut self, s: &str) -> usize {
        let n = self.arena.alloc(NodeValue::Text(s.to_string()));
        self.arena.nodes[n].open = false;
        n
    }
    fn make(&mut self, v: NodeValue) -> usize {
        let n = self.arena.alloc(v);
        self.arena.nodes[n].open = false;
        n
    }
    fn append(&mut self, n: usize) {
        let p = self.parent;
        self.arena.append(p, n);
    }

    fn is_special(&self, c: u8) -> bool {
        matches!(c, b'\n' | b'\r' | b'`' | b'\\' | b'&' | b'<' | b'*' | b'_' | b'[' | b']' | b'!' | b'~')
            || (self.superscript && c == b'^')
    }

    fn find_special_char(&self) -> usize {
        let mut n = self.pos + 1;
        while n < self.input.len() {
            if self.is_special(self.input[n]) {
                return n;
            }
            n += 1;
        }
        self.input.len()
    }

    fn parse_inline(&mut self) -> bool {
        let c = match self.peek() {
            Some(c) => c,
            None => return false,
        };
        let new_inl: Option<usize> = match c {
            b'\r' | b'\n' => Some(self.handle_newline()),
            b'`' => Some(self.handle_backticks()),
            b'\\' => Some(self.handle_backslash()),
            b'&' => Some(self.handle_entity()),
            b'<' => Some(self.handle_pointy_brace()),
            b'*' | b'_' | b'~' => Some(self.handle_delim(c)),
            b'^' if self.superscript => Some(self.handle_delim(c)),
            b'[' => {
                self.pos += 1;
                let t = self.make_text("[");
                self.append(t);
                self.push_bracket(false, t);
                None
            }
            b']' => self.handle_close_bracket(),
            b'!' => {
                self.pos += 1;
                if self.peek() == Some(b'[') {
                    self.pos += 1;
                    let t = self.make_text("![");
                    self.append(t);
                    self.push_bracket(true, t);
                    None
                } else {
                    Some(self.make_text("!"))
                }
            }
            _ => {
                let endpos = self.find_special_char();
                let mut contents = self.input[self.pos..endpos].to_vec();
                self.pos = endpos;
                if matches!(self.peek(), Some(b'\n') | Some(b'\r')) {
                    while let Some(&l) = contents.last() {
                        if l == b' ' || l == b'\t' {
                            contents.pop();
                        } else {
                            break;
                        }
                    }
                }
                let s = String::from_utf8_lossy(&contents).to_string();
                Some(self.make_text(&s))
            }
        };
        if let Some(n) = new_inl {
            if self.arena.nodes[n].parent.is_none() {
                self.append(n);
            }
        }
        true
    }

    fn handle_newline(&mut self) -> usize {
        let nlpos = self.pos;
        if self.peek() == Some(b'\r') {
            self.pos += 1;
        }
        if self.peek() == Some(b'\n') {
            self.pos += 1;
        }
        // skip spaces at beginning of line
        while matches!(self.peek(), Some(b' ') | Some(b'\t')) {
            self.pos += 1;
        }
        if nlpos > 1 && self.peek_at(nlpos - 1) == Some(b' ') && self.peek_at(nlpos - 2) == Some(b' ') {
            self.make(NodeValue::LineBreak)
        } else {
            self.make(NodeValue::SoftBreak)
        }
    }

    fn handle_backticks(&mut self) -> usize {
        let start = self.pos;
        while self.peek() == Some(b'`') {
            self.pos += 1;
        }
        let openlen = self.pos - start;
        let after_open = self.pos;
        // scan for matching closer
        let mut i = self.pos;
        loop {
            // find next backtick run
            while i < self.input.len() && self.input[i] != b'`' {
                i += 1;
            }
            if i >= self.input.len() {
                // no match
                self.pos = after_open;
                let s = "`".repeat(openlen);
                return self.make_text(&s);
            }
            let rs = i;
            while i < self.input.len() && self.input[i] == b'`' {
                i += 1;
            }
            if i - rs == openlen {
                let raw = &self.input[after_open..rs];
                // normalize: line endings -> spaces
                let mut buf: Vec<u8> = Vec::new();
                let mut k = 0;
                while k < raw.len() {
                    if raw[k] == b'\r' {
                        buf.push(b' ');
                        if k + 1 < raw.len() && raw[k + 1] == b'\n' {
                            k += 1;
                        }
                    } else if raw[k] == b'\n' {
                        buf.push(b' ');
                    } else {
                        buf.push(raw[k]);
                    }
                    k += 1;
                }
                if buf.len() >= 2 && buf[0] == b' ' && buf[buf.len() - 1] == b' ' && buf.iter().any(|&c| c != b' ') {
                    buf = buf[1..buf.len() - 1].to_vec();
                }
                self.pos = i;
                let s = String::from_utf8_lossy(&buf).to_string();
                return self.make(NodeValue::Code(s));
            }
        }
    }

    fn handle_backslash(&mut self) -> usize {
        self.pos += 1;
        match self.peek() {
            Some(c) if is_ascii_punct(c) => {
                self.pos += 1;
                let s = (c as char).to_string();
                self.make_text(&s)
            }
            Some(b'\n') | Some(b'\r') => {
                if self.peek() == Some(b'\r') {
                    self.pos += 1;
                }
                if self.peek() == Some(b'\n') {
                    self.pos += 1;
                }
                while matches!(self.peek(), Some(b' ') | Some(b'\t')) {
                    self.pos += 1;
                }
                self.make(NodeValue::LineBreak)
            }
            _ => self.make_text("\\"),
        }
    }

    fn handle_entity(&mut self) -> usize {
        self.pos += 1;
        match unescape_entity(&self.input[self.pos..]) {
            Some((s, n)) => {
                self.pos += n;
                self.make_text(&s)
            }
            None => self.make_text("&"),
        }
    }

    fn handle_pointy_brace(&mut self) -> usize {
        self.pos += 1;
        let n = scan_autolink_uri(&self.input, self.pos);
        if n > 0 {
            let url = String::from_utf8_lossy(&self.input[self.pos..n - 1]).to_string();
            self.pos = n;
            let link = self.make(NodeValue::Link { url: clean_autolink(&url, false), title: String::new() });
            let t = self.make_text(&unescape_string(&url));
            self.arena.append(link, t);
            return link;
        }
        let n = scan_autolink_email(&self.input, self.pos);
        if n > 0 {
            let url = String::from_utf8_lossy(&self.input[self.pos..n - 1]).to_string();
            self.pos = n;
            let link = self.make(NodeValue::Link { url: clean_autolink(&url, true), title: String::new() });
            let t = self.make_text(&unescape_string(&url));
            self.arena.append(link, t);
            return link;
        }
        let n = scan_html_inline(&self.input, self.pos - 1);
        if n > 0 {
            let s = String::from_utf8_lossy(&self.input[self.pos - 1..n]).to_string();
            self.pos = n;
            return self.make(NodeValue::HtmlInline(s));
        }
        self.make_text("<")
    }

    fn scan_delims(&mut self, c: u8) -> (usize, bool, bool) {
        let before_char: char = if self.pos == 0 {
            '\n'
        } else {
            let mut bp = self.pos - 1;
            while bp > 0 && (self.input[bp] >> 6) == 2 {
                bp -= 1;
            }
            std::str::from_utf8(&self.input[bp..self.pos]).ok().and_then(|s| s.chars().next()).unwrap_or('\n')
        };
        let mut numdelims = 0;
        while self.peek() == Some(c) {
            numdelims += 1;
            self.pos += 1;
        }
        let after_char: char = if self.pos >= self.input.len() {
            '\n'
        } else {
            let mut ep = self.pos + 1;
            while ep < self.input.len() && (self.input[ep] >> 6) == 2 {
                ep += 1;
            }
            std::str::from_utf8(&self.input[self.pos..ep]).ok().and_then(|s| s.chars().next()).unwrap_or('\n')
        };
        let left_flanking = numdelims > 0
            && !is_unicode_space(after_char)
            && (!is_punctuation(after_char) || is_unicode_space(before_char) || is_punctuation(before_char));
        let right_flanking = numdelims > 0
            && !is_unicode_space(before_char)
            && (!is_punctuation(before_char) || is_unicode_space(after_char) || is_punctuation(after_char));
        if c == b'_' {
            let can_open = left_flanking && (!right_flanking || is_punctuation(before_char));
            let can_close = right_flanking && (!left_flanking || is_punctuation(after_char));
            (numdelims, can_open, can_close)
        } else {
            (numdelims, left_flanking, right_flanking)
        }
    }

    fn handle_delim(&mut self, c: u8) -> usize {
        let (numdelims, can_open, can_close) = self.scan_delims(c);
        let s = String::from_utf8_lossy(&self.input[self.pos - numdelims..self.pos]).to_string();
        let t = self.make_text(&s);
        self.append(t);
        let valid = if c == b'~' { numdelims <= 2 } else { true };
        if (can_open || can_close) && valid {
            self.push_delimiter(c, can_open, can_close, t, numdelims);
        }
        t
    }

    fn push_delimiter(&mut self, c: u8, can_open: bool, can_close: bool, inl: usize, length: usize) {
        let idx = self.delims.len();
        self.delims.push(Delim {
            inl,
            delim_char: c,
            can_open,
            can_close,
            length,
            prev: self.last_delim,
            next: None,
        });
        if let Some(l) = self.last_delim {
            self.delims[l].next = Some(idx);
        }
        self.last_delim = Some(idx);
    }

    fn remove_delimiter(&mut self, d: usize) {
        let prev = self.delims[d].prev;
        let next = self.delims[d].next;
        if let Some(n) = next {
            self.delims[n].prev = prev;
        } else {
            self.last_delim = prev;
        }
        if let Some(p) = prev {
            self.delims[p].next = next;
        }
        self.delims[d].prev = None;
        self.delims[d].next = None;
    }

    fn push_bracket(&mut self, image: bool, inl_text: usize) {
        if let Some(b) = self.brackets.last_mut() {
            b.bracket_after = true;
        }
        self.brackets.push(Bracket {
            inl_text,
            position: self.pos,
            image,
            active: true,
            bracket_after: false,
            previous_delimiter: self.last_delim,
        });
    }

    fn handle_close_bracket(&mut self) -> Option<usize> {
        self.pos += 1;
        let initial_pos = self.pos;
        let opener = match self.brackets.last() {
            Some(b) => b.clone(),
            None => return Some(self.make_text("]")),
        };
        if !opener.active {
            self.brackets.pop();
            return Some(self.make_text("]"));
        }
        let is_image = opener.image;
        let after_link_text_pos = self.pos;

        let mut found: Option<(String, String)> = None;
        // inline link
        if self.peek() == Some(b'(') {
            let sps = scan_spacechars(&self.input, self.pos + 1);
            if let Some((n, us, ue)) = manual_scan_link_url(&self.input, self.pos + 1 + sps) {
                let endurl = self.pos + 1 + sps + n;
                let starttitle = endurl + scan_spacechars(&self.input, endurl);
                let endtitle = if starttitle == endurl { starttitle } else { starttitle + scan_link_title(&self.input, starttitle) };
                let endall = endtitle + scan_spacechars(&self.input, endtitle);
                if self.peek_at(endall) == Some(b')') {
                    self.pos = endall + 1;
                    let url = clean_url(&self.input[us..ue].to_vec());
                    let title = clean_title(&self.input[starttitle..endtitle].to_vec());
                    found = Some((url, title));
                } else {
                    self.pos = after_link_text_pos;
                }
            }
        }
        let mut raw_label_text: Option<String> = None;
        if found.is_none() {
            let mut lab: Option<String> = None;
            match link_label(&self.input, self.pos) {
                Some((end, l)) => {
                    self.pos = end;
                    lab = Some(l);
                }
                None => {
                    self.pos = initial_pos;
                }
            }
            let mut found_label = lab.is_some();
            if (lab.is_none() || lab.as_ref().map(|l| l.is_empty()).unwrap_or(false)) && !opener.bracket_after {
                lab = Some(String::from_utf8_lossy(&self.input[opener.position..initial_pos - 1]).to_string());
                found_label = true;
            }
            if found_label {
                let l = lab.clone().unwrap();
                raw_label_text = Some(l.clone());
                let key = normalize_label(&l);
                if let Some(r) = self.refmap.get(&key) {
                    found = Some((r.url.clone(), r.title.clone()));
                }
            }
        }
        match found {
            Some((url, title)) => {
                let inl = self.make(if is_image { NodeValue::Image { url, title } } else { NodeValue::Link { url, title } });
                insert_before(self.arena, opener.inl_text, inl);
                // move following siblings into link
                loop {
                    match next_sibling(self.arena, opener.inl_text) {
                        Some(t) => {
                            self.arena.detach(t);
                            self.arena.append(inl, t);
                        }
                        None => break,
                    }
                }
                self.arena.detach(opener.inl_text);
                self.process_emphasis(opener.previous_delimiter);
                self.brackets.pop();
                if !is_image {
                    for b in self.brackets.iter_mut().rev() {
                        if !b.image {
                            if !b.active {
                                break;
                            }
                            b.active = false;
                        }
                    }
                }
                None
            }
            None => {
                // footnote reference?
                let text = String::from_utf8_lossy(&self.input[opener.position..initial_pos - 1]).to_string();
                let _ = raw_label_text;
                if !is_image && text.len() > 1 && text.starts_with('^') && !text.contains(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                    self.pos = initial_pos;
                    let name = text[1..].to_string();
                    let inl = self.make(NodeValue::FootnoteReference(name));
                    insert_before(self.arena, opener.inl_text, inl);
                    loop {
                        match next_sibling(self.arena, opener.inl_text) {
                            Some(t) => self.arena.detach(t),
                            None => break,
                        }
                    }
                    self.arena.detach(opener.inl_text);
                    // remove delimiters after the opener
                    self.process_emphasis(opener.previous_delimiter);
                    self.brackets.pop();
                    return None;
                }
                self.brackets.pop();
                self.pos = initial_pos;
                Some(self.make_text("]"))
            }
        }
    }

    fn process_emphasis(&mut self, stack_bottom: Option<usize>) {
        let mut openers_bottom: [Option<usize>; 15] = [stack_bottom; 15];
        // find first delimiter above stack bottom
        let mut candidate = self.last_delim;
        let mut closer: Option<usize> = None;
        while let Some(c) = candidate {
            if Some(c) == stack_bottom {
                break;
            }
            closer = Some(c);
            candidate = self.delims[c].prev;
        }
        while let Some(c) = closer {
            let cd = self.delims[c].clone();
            if cd.can_close {
                let ix = match cd.delim_char {
                    b'|' => 0,
                    b'~' => 1,
                    b'^' => 2,
                    b'"' => 3,
                    b'\'' => 4,
                    b'_' => 5,
                    b'*' => 6 + (if cd.can_open { 3 } else { 0 }) + (cd.length % 3),
                    _ => 14,
                };
                let mut opener = cd.prev;
                let mut opener_found = false;
                let mut mod_three_rule_invoked = false;
                while let Some(o) = opener {
                    if Some(o) == stack_bottom || Some(o) == openers_bottom[ix] {
                        break;
                    }
                    let od = &self.delims[o];
                    if od.can_open && od.delim_char == cd.delim_char {
                        let odd_match = (cd.can_open || od.can_close)
                            && ((od.length + cd.length) % 3 == 0)
                            && !(od.length % 3 == 0 && cd.length % 3 == 0);
                        let tilde_mismatch = cd.delim_char == b'~' && od.length != cd.length;
                        if !odd_match && !tilde_mismatch {
                            opener_found = true;
                            break;
                        } else if odd_match {
                            mod_three_rule_invoked = true;
                        }
                    }
                    opener = od.prev;
                }
                let old_c = c;
                if opener_found {
                    closer = self.insert_emph(opener.unwrap(), c);
                } else {
                    closer = cd.next;
                }
                if !opener_found {
                    if !mod_three_rule_invoked {
                        openers_bottom[ix] = self.delims[old_c].prev;
                    }
                    if !self.delims[old_c].can_open {
                        self.remove_delimiter(old_c);
                    }
                }
            } else {
                closer = cd.next;
            }
        }
        // remove all delimiters above stack_bottom
        while let Some(l) = self.last_delim {
            if Some(l) == stack_bottom {
                break;
            }
            self.remove_delimiter(l);
        }
    }

    fn insert_emph(&mut self, opener: usize, closer: usize) -> Option<usize> {
        let od = self.delims[opener].clone();
        let cd = self.delims[closer].clone();
        let opener_char = od.delim_char;
        let mut opener_num_chars = text_of(self.arena, od.inl).len();
        let mut closer_num_chars = text_of(self.arena, cd.inl).len();
        let use_delims = if closer_num_chars >= 2 && opener_num_chars >= 2 { 2 } else { 1 };
        if opener_char == b'~' && opener_num_chars != closer_num_chars {
            return cd.next;
        }
        if opener_char == b'^' {
            // superscript uses single delimiters
        }
        let use_delims = if opener_char == b'^' { 1 } else { use_delims };
        opener_num_chars -= use_delims;
        closer_num_chars -= use_delims;
        if opener_char == b'~' && opener_num_chars > 0 {
            return cd.next;
        }
        // truncate texts
        {
            let t = text_of(self.arena, od.inl);
            self.arena.nodes[od.inl].value = NodeValue::Text(t[..opener_num_chars].to_string());
            let t = text_of(self.arena, cd.inl);
            self.arena.nodes[cd.inl].value = NodeValue::Text(t[..closer_num_chars].to_string());
        }
        // remove delimiters between opener and closer
        let mut d = cd.prev;
        while let Some(x) = d {
            if x == opener {
                break;
            }
            let p = self.delims[x].prev;
            self.remove_delimiter(x);
            d = p;
        }
        let value = if opener_char == b'~' {
            NodeValue::Strikethrough
        } else if opener_char == b'^' {
            NodeValue::Superscript
        } else if use_delims == 1 {
            NodeValue::Emph
        } else {
            NodeValue::Strong
        };
        let emph = self.make(value);
        // move nodes between opener.inl and closer.inl into emph
        loop {
            match next_sibling(self.arena, od.inl) {
                Some(t) if t != cd.inl => {
                    self.arena.detach(t);
                    self.arena.append(emph, t);
                }
                _ => break,
            }
        }
        insert_after(self.arena, od.inl, emph);
        if opener_num_chars == 0 {
            self.arena.detach(od.inl);
            self.remove_delimiter(opener);
        }
        if closer_num_chars == 0 {
            self.arena.detach(cd.inl);
            let next = self.delims[closer].next;
            self.remove_delimiter(closer);
            next
        } else {
            Some(closer)
        }
    }
}

fn clean_autolink(url: &str, email: bool) -> String {
    let u = unescape_string(url.trim());
    if email {
        format!("mailto:{}", u)
    } else {
        u
    }
}

pub fn parse_inlines(p: &mut Parser, parent: usize, content: &str) {
    let mut input = content.as_bytes().to_vec();
    while let Some(&c) = input.last() {
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
            input.pop();
        } else {
            break;
        }
    }
    let superscript = p.options.superscript;
    let refmap = p.refmap.clone();
    let mut subj = Subject {
        input,
        pos: 0,
        delims: Vec::new(),
        last_delim: None,
        brackets: Vec::new(),
        arena: &mut p.arena,
        refmap: &refmap,
        superscript,
        parent,
    };
    while !subj.eof() && subj.parse_inline() {}
    subj.process_emphasis(None);
    // merge adjacent text nodes and process autolinks
    merge_text_nodes(&mut p.arena, parent);
    autolink(&mut p.arena, parent, false);
}

pub fn merge_text_nodes(arena: &mut Arena, node: usize) {
    let children = arena.nodes[node].children.clone();
    let mut new_children: Vec<usize> = Vec::new();
    for c in children {
        if let NodeValue::Text(t) = &arena.nodes[c].value {
            let t = t.clone();
            if let Some(&last) = new_children.last() {
                if let NodeValue::Text(lt) = &arena.nodes[last].value {
                    let merged = format!("{}{}", lt, t);
                    arena.nodes[last].value = NodeValue::Text(merged);
                    arena.nodes[c].parent = None;
                    continue;
                }
            }
            if t.is_empty() {
                arena.nodes[c].parent = None;
                continue;
            }
        }
        new_children.push(c);
    }
    arena.nodes[node].children = new_children.clone();
    for c in new_children {
        merge_text_nodes(arena, c);
    }
}

// ---------------- GFM autolinks -----------------

fn is_valid_hostchar(c: char) -> bool {
    !is_unicode_space(c) && !is_punctuation(c)
}

fn check_domain(data: &[u8], allow_short: bool) -> usize {
    let size = data.len();
    let mut np = 0;
    let mut uscore1 = 0;
    let mut uscore2 = 0;
    let mut i = 1;
    while i + 1 < size {
        if data[i] == b'\\' && i + 2 < size {
            i += 1;
        }
        if data[i] == b'_' {
            uscore2 += 1;
        } else if data[i] == b'.' {
            uscore1 = uscore2;
            uscore2 = 0;
            np += 1;
        } else {
            let ch = std::str::from_utf8(&data[i..]).ok().and_then(|s| s.chars().next());
            let ch = match ch {
                Some(c) => c,
                None => {
                    // decode leniently
                    let mut e = i + 1;
                    while e < size && (data[e] >> 6) == 2 {
                        e += 1;
                    }
                    std::str::from_utf8(&data[i..e]).ok().and_then(|s| s.chars().next()).unwrap_or(' ')
                }
            };
            if !is_valid_hostchar(ch) && data[i] != b'-' {
                break;
            }
            // skip continuation bytes
            let l = ch.len_utf8();
            i += l;
            continue;
        }
        i += 1;
    }
    if (uscore1 > 0 || uscore2 > 0) && np <= 10 {
        return 0;
    }
    if allow_short {
        i
    } else if np > 0 {
        i
    } else {
        0
    }
}

fn autolink_delim(data: &[u8], mut link_end: usize) -> usize {
    for i in 0..link_end {
        if data[i] == b'<' {
            link_end = i;
            break;
        }
    }
    while link_end > 0 {
        let cclose = data[link_end - 1];
        let copen = if cclose == b')' { b'(' } else { 0 };
        if b"?!.,:*_~'\"".contains(&cclose) {
            link_end -= 1;
        } else if cclose == b';' {
            let mut new_end = link_end as isize - 2;
            while new_end > 0 && (data[new_end as usize]).is_ascii_alphabetic() {
                new_end -= 1;
            }
            if new_end >= 0 && (new_end as usize) < link_end - 2 && data[new_end as usize] == b'&' {
                link_end = new_end as usize;
            } else {
                link_end -= 1;
            }
        } else if copen != 0 {
            let mut opening = 0;
            let mut closing = 0;
            for &c in &data[..link_end] {
                if c == copen {
                    opening += 1;
                } else if c == cclose {
                    closing += 1;
                }
            }
            if closing <= opening {
                break;
            }
            link_end -= 1;
        } else {
            break;
        }
    }
    link_end
}

fn is_cspace(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == 0x0b || c == 0x0c
}

/// Returns (start_rewind, end, url) for a match at position i in data
fn www_match(data: &[u8], i: usize) -> Option<(usize, usize, String)> {
    if i > 0 && !b"*_~(".contains(&data[i - 1]) && !is_cspace(data[i - 1]) {
        return None;
    }
    let d = &data[i..];
    if d.len() < 4 || &d[..4] != b"www." {
        return None;
    }
    let mut link_end = check_domain(d, false);
    if link_end == 0 {
        return None;
    }
    while link_end < d.len() && !is_cspace(d[link_end]) && d[link_end] != b'<' {
        link_end += 1;
    }
    link_end = autolink_delim(d, link_end);
    if link_end == 0 {
        return None;
    }
    let text = String::from_utf8_lossy(&d[..link_end]).to_string();
    Some((i, i + link_end, format!("http://{}", text)))
}

fn url_match(data: &[u8], i: usize) -> Option<(usize, usize, String)> {
    // data[i] == ':'
    let d = &data[i..];
    if d.len() < 4 || d[1] != b'/' || d[2] != b'/' {
        return None;
    }
    let mut rewind = 0;
    while rewind < i && data[i - rewind - 1].is_ascii_alphabetic() {
        rewind += 1;
    }
    let start = i - rewind;
    let scheme = String::from_utf8_lossy(&data[start..i]).to_ascii_lowercase();
    let ok = ["http", "https", "ftp"].contains(&scheme.as_str());
    if !ok {
        return None;
    }
    let mut link_end = 3;
    let domain_len = check_domain(&d[link_end..], true);
    if domain_len == 0 {
        return None;
    }
    link_end += domain_len;
    while link_end < d.len() && !is_cspace(d[link_end]) && d[link_end] != b'<' {
        link_end += 1;
    }
    link_end = autolink_delim(d, link_end);
    if link_end == 0 {
        return None;
    }
    let url = String::from_utf8_lossy(&data[start..i + link_end]).to_string();
    Some((start, i + link_end, url))
}

fn email_match(data: &[u8], at: usize) -> Option<(usize, usize, String)> {
    let mut rewind = 0;
    let mut auto_mailto = true;
    while rewind < at {
        let c = data[at - rewind - 1];
        if c.is_ascii_alphanumeric() || b".+-_".contains(&c) {
            rewind += 1;
            continue;
        }
        if c == b':' {
            let proto = b"mailto:";
            let r = rewind + 1;
            if at >= r + proto.len() - 1 {
                let s = at - rewind - proto.len();
                if at >= rewind + proto.len() && &data[s..at - rewind] == proto {
                    auto_mailto = false;
                    rewind += proto.len();
                    break;
                }
            }
        }
        break;
    }
    if rewind == 0 {
        return None;
    }
    let d = &data[at..];
    let size = d.len();
    let mut link_end = 0;
    let mut nb = 0;
    let mut np = 0;
    while link_end < size {
        let c = d[link_end];
        if c.is_ascii_alphanumeric() {
        } else if c == b'@' {
            nb += 1;
        } else if c == b'.' && link_end + 1 < size && d[link_end + 1].is_ascii_alphanumeric() {
            np += 1;
        } else if c != b'-' && c != b'_' {
            break;
        }
        link_end += 1;
    }
    if link_end < 2 || nb != 1 || np == 0 || (!d[link_end - 1].is_ascii_alphabetic() && d[link_end - 1] != b'.') {
        return None;
    }
    let link_end = autolink_delim(d, link_end);
    if link_end == 0 {
        return None;
    }
    let text = String::from_utf8_lossy(&data[at - rewind..at + link_end]).to_string();
    let url = if auto_mailto { format!("mailto:{}", text) } else { text };
    Some((at - rewind, at + link_end, url))
}

fn autolink(arena: &mut Arena, node: usize, in_link: bool) {
    let children = arena.nodes[node].children.clone();
    let mut new_children: Vec<usize> = Vec::new();
    for c in children {
        match arena.nodes[c].value.clone() {
            NodeValue::Text(t) if !in_link => {
                let pieces = autolink_text(&t);
                if pieces.len() == 1 {
                    if let AutoPiece::Text(_) = &pieces[0] {
                        new_children.push(c);
                        continue;
                    }
                }
                arena.nodes[c].parent = None;
                for p in pieces {
                    match p {
                        AutoPiece::Text(s) => {
                            if s.is_empty() {
                                continue;
                            }
                            let n = arena.alloc(NodeValue::Text(s));
                            arena.nodes[n].open = false;
                            arena.nodes[n].parent = Some(node);
                            new_children.push(n);
                        }
                        AutoPiece::Link(url, text) => {
                            let l = arena.alloc(NodeValue::Link { url, title: String::new() });
                            arena.nodes[l].open = false;
                            let tn = arena.alloc(NodeValue::Text(text));
                            arena.nodes[tn].open = false;
                            arena.append(l, tn);
                            arena.nodes[l].parent = Some(node);
                            new_children.push(l);
                        }
                    }
                }
            }
            NodeValue::Link { .. } | NodeValue::Image { .. } => {
                new_children.push(c);
                autolink(arena, c, true);
            }
            NodeValue::Code(_) | NodeValue::HtmlInline(_) => new_children.push(c),
            _ => {
                new_children.push(c);
                autolink(arena, c, in_link);
            }
        }
    }
    arena.nodes[node].children = new_children;
}

enum AutoPiece {
    Text(String),
    Link(String, String),
}

fn autolink_text(t: &str) -> Vec<AutoPiece> {
    let data = t.as_bytes();
    let mut out = Vec::new();
    let mut last = 0;
    let mut i = 0;
    while i < data.len() {
        let c = data[i];
        let m = if c == b'w' {
            www_match(data, i)
        } else if c == b':' {
            url_match(data, i)
        } else if c == b'@' {
            email_match(data, i)
        } else {
            None
        };
        if let Some((start, end, url)) = m {
            if start >= last {
                out.push(AutoPiece::Text(String::from_utf8_lossy(&data[last..start]).to_string()));
                out.push(AutoPiece::Link(url, String::from_utf8_lossy(&data[start..end]).to_string()));
                last = end;
                i = end;
                continue;
            }
        }
        i += 1;
    }
    out.push(AutoPiece::Text(String::from_utf8_lossy(&data[last..]).to_string()));
    out
}
