// Typographic cleaning of text, according to language
#[derive(Clone, Debug)]
pub struct Cleaner {
    pub enabled: bool,
    pub french: bool,
    pub smart_quotes: bool,
    pub ligature_dashes: bool,
    pub ligature_guillemets: bool,
}

pub const NB_CHAR: char = '\u{a0}';
pub const NB_CHAR_NARROW: char = '\u{202f}';
pub const NB_CHAR_EM: char = '\u{2002}';

fn is_ws(c: char) -> bool {
    c.is_whitespace()
}

fn collapse_spaces(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut prev_space = false;
    for c in s.chars() {
        if c == ' ' {
            if !prev_space {
                out.push(c);
            }
            prev_space = true;
        } else {
            prev_space = false;
            out.push(c);
        }
    }
    out
}

fn ctx(c: Option<char>) -> u8 {
    // 0 = whitespace/none, 1 = alnum, 2 = punct
    match c {
        None => 0,
        Some(c) if is_ws(c) => 0,
        Some(c) if c.is_alphanumeric() => 1,
        _ => 2,
    }
}

fn opening_ctx(p: u8, n: u8) -> bool {
    (p == 0 && n != 0) || (p == 2 && n == 1)
}

fn real_closer(p: u8, n: u8) -> bool {
    p != 0 && n != 1
}

fn closing_ctx(p: u8, n: u8) -> bool {
    p == 1 || (p == 2 && n == 0)
}

pub fn replace_quotes(s: &str) -> String {
    let mut chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    let mut double_open = 0usize;
    let mut single_open = false;
    for i in 0..len {
        let c = chars[i];
        if c != '"' && c != '\'' {
            continue;
        }
        let p = ctx(if i > 0 { Some(chars[i - 1]) } else { None });
        let n = ctx(chars.get(i + 1).cloned());
        if c == '"' {
            if opening_ctx(p, n) {
                chars[i] = '“';
                double_open += 1;
            } else if double_open > 0 {
                chars[i] = '”';
                double_open -= 1;
            }
        } else {
            if opening_ctx(p, n) {
                let mut has_closer = false;
                if !single_open {
                    for j in (i + 1)..len {
                        if chars[j] == '\'' {
                            let pj = ctx(Some(chars[j - 1]));
                            let nj = ctx(chars.get(j + 1).cloned());
                            if real_closer(pj, nj) {
                                has_closer = true;
                                break;
                            }
                        }
                    }
                }
                if !single_open && has_closer {
                    chars[i] = '‘';
                    single_open = true;
                } else {
                    chars[i] = '’';
                }
            } else if closing_ctx(p, n) {
                chars[i] = '’';
                if single_open && real_closer(p, n) {
                    single_open = false;
                }
            } else if single_open {
                chars[i] = '’';
                single_open = false;
            }
        }
    }
    chars.into_iter().collect()
}

fn letterish(c: char) -> bool {
    c.is_alphabetic() || c == '°'
}

fn digit_rule(chars: &[char], i: usize) -> bool {
    let c1 = chars[i + 1];
    if c1.is_ascii_digit() {
        return true;
    }
    let mut j = i + 1;
    while j < chars.len() && !is_ws(chars[j]) {
        j += 1;
    }
    let word = &chars[i + 1..j];
    let is_end = j >= chars.len();
    let e = word.len() + if is_end { 1 } else { 0 };
    let c2 = word.get(1).cloned();
    let c2_letter = c2.map(letterish).unwrap_or(false);
    if !letterish(c1) {
        return !c2_letter;
    }
    if !c1.is_lowercase() {
        if !c2_letter {
            return true;
        }
        let k = word.iter().take_while(|c| letterish(**c) && !c.is_lowercase()).count();
        let t = 1 + k.min(3);
        e <= t
    } else {
        if !c2_letter {
            return false;
        }
        e <= 3
    }
}

fn is_dash(c: char) -> bool {
    c == '—' || c == '–'
}

pub fn french_clean(s: &str) -> String {
    let s = s.replace("...", "…");
    let mut chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    if len == 0 {
        return String::new();
    }
    let mut dash_open = false;
    for i in 0..len {
        let current = chars[i];
        if !is_ws(current) {
            continue;
        }
        if i + 1 >= len {
            continue;
        }
        let next = chars[i + 1];
        match next {
            '?' | '!' | ';' => {
                chars[i] = NB_CHAR_NARROW;
                continue;
            }
            ':' => {
                chars[i] = NB_CHAR;
                continue;
            }
            '»' => {
                if current == ' ' {
                    chars[i] = NB_CHAR;
                }
                continue;
            }
            _ => {}
        }
        if i == 0 {
            continue;
        }
        let prev = chars[i - 1];
        if prev == '«' {
            if i <= 2 {
                chars[i] = NB_CHAR;
            } else {
                let mut found = None;
                let end = (i + 20).min(len);
                for j in (i + 1)..end {
                    if chars[j] == '»' {
                        found = Some(j);
                        break;
                    }
                }
                match found {
                    Some(j) if is_ws(chars[j - 1]) => {
                        chars[i] = NB_CHAR_NARROW;
                        chars[j - 1] = NB_CHAR_NARROW;
                    }
                    _ => {
                        chars[i] = NB_CHAR;
                    }
                }
            }
        } else if is_dash(prev) || (prev == '-' && dash_open) {
            if is_dash(prev) && i <= 2 {
                chars[i] = NB_CHAR_EM;
            } else if dash_open && i >= 2 && is_ws(chars[i - 2]) {
                chars[i - 2] = NB_CHAR;
                dash_open = false;
            } else if is_dash(prev) {
                chars[i] = NB_CHAR;
                dash_open = true;
            }
        } else if prev.is_ascii_digit() {
            if digit_rule(&chars, i) {
                chars[i] = NB_CHAR_NARROW;
            }
        }
    }
    chars.into_iter().collect()
}

impl Cleaner {
    pub fn clean(&self, s: &str) -> String {
        if !self.enabled {
            return s.to_string();
        }
        let mut out = collapse_spaces(s);
        if self.smart_quotes {
            out = replace_quotes(&out);
        }
        if self.ligature_dashes {
            out = out.replace("---", "—").replace("--", "–");
        }
        if self.ligature_guillemets {
            out = out.replace("<<", "«").replace(">>", "»");
        }
        if self.french {
            out = french_clean(&out);
        }
        out
    }
}
