    loop {
        let e = rest.find(syn.expr_open);
        let b = rest.find(syn.block_open);
        let c = rest.find("{#").filter(|_| syn.expr_open == "{{");
        let next = [e.map(|x| (x, 0)), b.map(|x| (x, 1)), c.map(|x| (x, 2))]
            .iter()
            .flatten()
            .cloned()
            .min_by_key(|(x, _)| *x);
        match next {
            None => {
                if !rest.is_empty() {
                    toks.push(Tok::Text(rest.to_string()));
                }
                break;
            }
            Some((pos, kind)) => {
                let mut text = rest[..pos].to_string();
                let open_len = 2;
                let after = &rest[pos + open_len..];
