                    0 => syn.expr_close,
                    1 => syn.block_close,
                    _ => "#}",
                };
                let end = match after.find(close) {
                    Some(x) => x,
                    None => {
                        return Err(TemplateError { msg: "syntax error".into(), detail: "unclosed tag".into() });
                    }
                };
                let mut inner = &after[..end];
                let mut trim_left = false;
                let mut trim_right = false;
                if inner.starts_with('-') {
                    trim_left = true;
                    inner = &inner[1..];
                }
                if inner.ends_with('-') {
                    trim_right = true;
                    inner = &inner[..inner.len() - 1];
                }
                if trim_left {
                    text = text.trim_end().to_string();
                }
                if !text.is_empty() {
                    toks.push(Tok::Text(text));
                }
