                match kind {
                    0 => toks.push(Tok::Expr(inner.trim().to_string(), loc + 2)),
                    1 => toks.push(Tok::Block(inner.trim().to_string(), loc)),
                    _ => {}
                }
                let consumed = pos + open_len + end + close.len();
                rest = &rest[consumed..];
                offset += consumed;
                if trim_right {
                    let t = rest.trim_start();
                    offset += rest.len() - t.len();
                    rest = t;
                }
            }
        }
    }
    Ok(toks)
}

fn parse_expr(s: &str) -> Expr {
    let s = s.trim();
    // filters
    let parts = split_top(s, '|');
    let mut base = parse_atom(parts[0].trim());
    for f in &parts[1..] {
        let f = f.trim();
        let (name, args) = match f.find(':') {
            Some(p) => (f[..p].trim().to_string(), f[p + 1..].split(',').map(|a| parse_atom(a.trim())).collect()),
            None => (f.to_string(), vec![]),
        };
        base = Expr::Filter(Box::new(base), name, args);
    }
    base
}

fn split_top(s: &str, sep: char) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut in_str = false;
    for c in s.chars() {
        if c == '"' {
            in_str = !in_str;
        }
        if c == sep && !in_str {
            out.push(cur.clone());
            cur.clear();
        } else {
            cur.push(c);
        }
    }
    out.push(cur);
    out
}

fn parse_atom(s: &str) -> Expr {
    let s = s.trim();
    if let Some(rest) = s.strip_prefix("not ") {
        return Expr::Not(Box::new(parse_expr(rest)));
    }
    if s.starts_with('"') && s.ends_with('"') && s.len() >= 2 {
        return Expr::Lit(Value::Str(s[1..s.len() - 1].replace("\\\"", "\"").replace("\\n", "\n")));
    }
    if s == "true" {
        return Expr::Lit(Value::Bool(true));
    }
    if s == "false" {
        return Expr::Lit(Value::Bool(false));
    }
    if let Ok(i) = s.parse::<i64>() {
        return Expr::Lit(Value::Int(i));
    }
    Expr::Path(s.split('.').map(|x| x.trim().to_string()).collect())
}

fn parse_nodes(toks: &[Tok], i: &mut usize, terminators: &[&str]) -> Result<(Vec<Node>, String), TemplateError> {
    let mut nodes = Vec::new();
    while *i < toks.len() {
        match &toks[*i] {
            Tok::Text(t) => {
                nodes.push(Node::Text(t.clone()));
                *i += 1;
            }
            Tok::Expr(e, loc) => {
                nodes.push(Node::Expr(parse_expr(e), *loc, e.len()));
                *i += 1;
            }
            Tok::Block(b, _) => {
                let b = b.trim();
                let word = b.split_whitespace().next().unwrap_or("");
                if terminators.contains(&word) || (word == "else" && terminators.contains(&"else")) {
                    return Ok((nodes, b.to_string()));
                }
                if word == "if" {
                    *i += 1;
                    let mut branches = Vec::new();
                    let mut cond = parse_expr(&b[2..]);
                    let mut else_nodes = Vec::new();
                    loop {
                        let (body, term) = parse_nodes(toks, i, &["else", "endif"])?;
                        *i += 1;
                        branches.push((cond.clone(), body));
                        if term.starts_with("endif") {
                            break;
                        }
                        // else or else if
                        let rest = term[4..].trim();
                        if let Some(c) = rest.strip_prefix("if") {
                            cond = parse_expr(c);
                            continue;
                        } else {
                            let (body, _term) = parse_nodes(toks, i, &["endif"])?;
                            *i += 1;
                            else_nodes = body;
                            break;
                        }
                    }
                    nodes.push(Node::If(branches, else_nodes));
                } else if word == "for" {
                    *i += 1;
                    let rest = b[3..].trim();
                    let (vars, expr) = match rest.find(" in ") {
                        Some(p) => (rest[..p].split(',').map(|x| x.trim().to_string()).collect::<Vec<_>>(), parse_expr(&rest[p + 4..])),
                        None => return Err(TemplateError { msg: "syntax error".into(), detail: "bad for".into() }),
                    };
                    let (body, _) = parse_nodes(toks, i, &["endfor"])?;
                    *i += 1;
                    nodes.push(Node::For(vars, expr, body));
                } else {
                    return Err(TemplateError { msg: "syntax error".into(), detail: format!("unexpected block {}", b) });
                }
            }
        }
    }
    Ok((nodes, String::new()))
}

pub struct Template {
    nodes: Vec<Node>,
    src: String,
}

impl Template {
    pub fn compile(src: &str, syn: &Syntax) -> Result<Template, TemplateError> {
        let toks = tokenize(src, syn)?;
        let mut i = 0;
        let (nodes, _) = parse_nodes(&toks, &mut i, &[])?;
        Ok(Template { nodes, src: src.to_string() })
    }

    pub fn render(&self, ctx: &Context) -> Result<String, TemplateError> {
        let mut out = String::new();
        let mut scopes: Vec<Context> = vec![];
        render_nodes(&self.nodes, ctx, &mut scopes, &mut out, &self.src)?;
        Ok(out)
    }
}

fn lookup(path: &[String], ctx: &Context, scopes: &[Context]) -> Option<Value> {
    let first = &path[0];
    let mut v = None;
    for s in scopes.iter().rev() {
        if let Some(x) = s.get(first) {
            v = Some(x.clone());
            break;
        }
    }
    if v.is_none() {
        v = ctx.get(first).cloned();
    }
    let mut v = v?;
    for p in &path[1..] {
        v = match v {
            Value::Map(m) => m.get(p).cloned()?,
            Value::List(l) => l.get(p.parse::<usize>().ok()?).cloned()?,
            _ => return None,
        };
    }
    Some(v)
}

fn render_error(src: &str, loc: usize, len: usize) -> TemplateError {
    // compute line/col
    let before = &src[..loc.min(src.len())];
    let line = before.matches('\n').count() + 1;
    let line_start = before.rfind('\n').map(|x| x + 1).unwrap_or(0);
    let col = src[line_start..loc.min(src.len())].chars().count() + 1;
    let line_text = src[line_start..].lines().next().unwrap_or("");
    let ln = line.to_string();
    let pad = " ".repeat(ln.len());
    let mut lead = 0;
    let s = &src[loc.min(src.len())..];
    let trimmed = s.trim_start();
    lead += s.len() - trimmed.len();
    let name_len = trimmed.chars().take_while(|c| !c.is_whitespace() && *c != '}' && *c != '|').count();
    let _ = len;
    let detail = format!(
        "\n\n{pad}--> <anonymous>:{line}:{col}\n{pad} |\n{ln} | {line_text}\n{pad} | {sp}{carets}\n{pad} |\n{pad} = reason: not found in this scope\n",
        pad = pad,
        line = line,
        col = col + lead,
        ln = ln,
        line_text = line_text,
        sp = " ".repeat(col - 1 + lead),
        carets = "^".repeat(name_len.max(1))
    );
    TemplateError { msg: "render error".into(), detail }
}

fn eval(e: &Expr, ctx: &Context, scopes: &[Context]) -> Result<Value, ()> {
    match e {
        Expr::Lit(v) => Ok(v.clone()),
        Expr::Path(p) => lookup(p, ctx, scopes).ok_or(()),
        Expr::Not(inner) => Ok(Value::Bool(!eval(inner, ctx, scopes)?.truthy())),
        Expr::Filter(base, name, args) => {
            let v = eval(base, ctx, scopes)?;
            let args: Vec<Value> = args.iter().map(|a| eval(a, ctx, scopes)).collect::<Result<_, _>>()?;
            match name.as_str() {
                "eq" => Ok(Value::Bool(match (&v, args.get(0)) {
                    (Value::Str(a), Some(Value::Str(b))) => a == b,
                    (Value::Int(a), Some(Value::Int(b))) => a == b,
                    (Value::Bool(a), Some(Value::Bool(b))) => a == b,
                    _ => false,
                })),
                _ => Ok(v),
            }
        }
    }
}

fn render_nodes(nodes: &[Node], ctx: &Context, scopes: &mut Vec<Context>, out: &mut String, src: &str) -> Result<(), TemplateError> {
    for n in nodes {
        match n {
            Node::Text(t) => out.push_str(t),
            Node::Expr(e, loc, len) => match eval(e, ctx, scopes) {
                Ok(v) => out.push_str(&v.render()),
                Err(()) => return Err(render_error(src, *loc, *len)),
            },
            Node::If(branches, else_nodes) => {
                let mut done = false;
                for (cond, body) in branches {
                    let v = match eval(cond, ctx, scopes) {
                        Ok(v) => v,
                        Err(()) => return Err(TemplateError { msg: "render error".into(), detail: String::new() }),
                    };
                    if v.truthy() {
                        render_nodes(body, ctx, scopes, out, src)?;
                        done = true;
                        break;
                    }
                }
                if !done {
                    render_nodes(else_nodes, ctx, scopes, out, src)?;
                }
            }
            Node::For(vars, e, body) => {
                let v = eval(e, ctx, scopes).map_err(|_| TemplateError { msg: "render error".into(), detail: String::new() })?;
                match v {
                    Value::List(l) => {
                        for item in l {
                            let mut sc = Context::new();
                            sc.insert(vars[0].clone(), item);
                            scopes.push(sc);
                            render_nodes(body, ctx, scopes, out, src)?;
                            scopes.pop();
                        }
                    }
                    Value::Map(m) => {
                        for (k, item) in m {
                            let mut sc = Context::new();
                            if vars.len() >= 2 {
                                sc.insert(vars[0].clone(), Value::Str(k));
                                sc.insert(vars[1].clone(), item);
                            } else {
                                sc.insert(vars[0].clone(), item);
                            }
                            scopes.push(sc);
                            render_nodes(body, ctx, scopes, out, src)?;
                            scopes.pop();
                        }
                    }
                    _ => {}
                }
            }
        }
    }
    Ok(())
}
