// A small YAML parser mimicking yaml-rust behaviour for common documents
use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq)]
pub enum Yaml {
    Real(String),
    Integer(i64),
    String(String),
    Boolean(bool),
    Array(Vec<Yaml>),
    Hash(Vec<(Yaml, Yaml)>),
    Null,
    BadValue,
}

#[derive(Debug, Clone)]
pub struct YamlError {
    pub info: String,
    pub line: usize, // 0-based
    pub col: usize,  // 0-based
}

impl std::fmt::Display for YamlError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{} at line {} column {}", self.info, self.line + 1, self.col + 1)
    }
}

pub fn debug_str(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\0' => out.push_str("\\0"),
            c if (c as u32) < 0x20 || (c as u32) == 0x7f || ((c as u32) >= 0x80 && (c as u32) < 0xa0) => {
                out.push_str(&format!("\\u{{{:x}}}", c as u32))
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

impl Yaml {
    pub fn debug(&self) -> String {
        match self {
            Yaml::Real(s) => format!("Real({})", debug_str(s)),
            Yaml::Integer(i) => format!("Integer({})", i),
            Yaml::String(s) => format!("String({})", debug_str(s)),
            Yaml::Boolean(b) => format!("Boolean({})", b),
            Yaml::Array(v) => format!("Array([{}])", v.iter().map(|x| x.debug()).collect::<Vec<_>>().join(", ")),
            Yaml::Hash(v) => format!("Hash({{{}}})", v.iter().map(|(k, x)| format!("{}: {}", k.debug(), x.debug())).collect::<Vec<_>>().join(", ")),
            Yaml::Null => "Null".to_string(),
            Yaml::BadValue => "BadValue".to_string(),
        }
    }
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Yaml::String(s) => Some(s),
            _ => None,
        }
    }
}

fn resolve_plain(s: &str) -> Yaml {
    match s {
        "~" | "null" => return Yaml::Null,
        "true" => return Yaml::Boolean(true),
        "false" => return Yaml::Boolean(false),
        _ => {}
    }
    if let Some(h) = s.strip_prefix("0x") {
        if let Ok(i) = i64::from_str_radix(h, 16) {
            return Yaml::Integer(i);
        }
    }
    if let Some(o) = s.strip_prefix("0o") {
        if let Ok(i) = i64::from_str_radix(o, 8) {
            return Yaml::Integer(i);
        }
    }
    if let Ok(i) = s.parse::<i64>() {
        return Yaml::Integer(i);
    }
    // float
    let is_float = match s {
        ".inf" | ".Inf" | ".INF" | "+.inf" | "+.Inf" | "+.INF" | "-.inf" | "-.Inf" | "-.INF" | ".nan" | ".NaN" | ".NAN" => true,
        _ => {
            !s.is_empty()
                && s.chars().all(|c| c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-')
                && s.parse::<f64>().is_ok()
                && !s.eq_ignore_ascii_case("inf")
                && !s.eq_ignore_ascii_case("nan")
        }
    };
    if is_float {
        return Yaml::Real(s.to_string());
    }
    Yaml::String(s.to_string())
}

struct P<'a> {
    chars: Vec<char>,
    pos: usize,
    line: usize,
    col: usize,
    anchors: HashMap<String, Yaml>,
    _src: &'a str,
}

type R<T> = Result<T, YamlError>;

impl<'a> P<'a> {
    fn err(&self, info: &str) -> YamlError {
        YamlError { info: info.to_string(), line: self.line, col: self.col }
    }
    fn err_at(&self, info: &str, line: usize, col: usize) -> YamlError {
        YamlError { info: info.to_string(), line, col }
    }
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).cloned()
    }
    fn peek_at(&self, k: usize) -> Option<char> {
        self.chars.get(self.pos + k).cloned()
    }
    fn advance(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).cloned()?;
        self.pos += 1;
        if c == '\n' {
            self.line += 1;
            self.col = 0;
        } else {
            self.col += 1;
        }
        Some(c)
    }
    fn eof(&self) -> bool {
        self.pos >= self.chars.len()
    }
    fn is_blank_or_end(c: Option<char>) -> bool {
        matches!(c, None | Some(' ') | Some('\t') | Some('\n') | Some('\r'))
    }
    fn skip_spaces(&mut self) {
        while matches!(self.peek(), Some(' ') | Some('\t')) {
            self.advance();
        }
    }
    /// skip whitespace, comments and newlines; returns true if any newline crossed
    fn skip_ws_comments(&mut self) -> bool {
        let mut nl = false;
        loop {
            match self.peek() {
                Some(' ') | Some('\t') | Some('\r') => {
                    self.advance();
                }
                Some('\n') => {
                    nl = true;
                    self.advance();
                }
                Some('#') => {
                    if self.col == 0 || matches!(self.chars.get(self.pos.wrapping_sub(1)), Some(' ') | Some('\t') | Some('\n')) {
                        while !matches!(self.peek(), None | Some('\n')) {
                            self.advance();
                        }
                    } else {
                        break;
                    }
                }
                _ => break,
            }
        }
        nl
    }

    fn parse_document(&mut self) -> R<Option<Yaml>> {
        self.skip_ws_comments();
        if self.col == 0 && self.starts_with("---") && Self::is_blank_or_end(self.peek_at(3)) {
            for _ in 0..3 {
                self.advance();
            }
            self.skip_ws_comments();
        }
        if self.eof() {
            return Ok(None);
        }
        let v = self.parse_block_node(-1, false)?;
        self.skip_ws_comments();
        if !self.eof() {
            if self.col == 0 && (self.starts_with("---") || self.starts_with("...")) {
                // ignore rest (multi docs not supported)
                return Ok(Some(v));
            }
            let c = self.peek().unwrap();
            if c == '-' && Self::is_blank_or_end(self.peek_at(1)) {
                return Err(self.err("did not find expected <document start>"));
            }
            return Err(self.err("did not find expected <document start>"));
        }
        Ok(Some(v))
    }

    fn starts_with(&self, s: &str) -> bool {
        let sc: Vec<char> = s.chars().collect();
        self.chars.len() >= self.pos + sc.len() && self.chars[self.pos..self.pos + sc.len()] == sc[..]
    }

    /// Parse a block node whose content must be indented more than `parent_indent`.
    fn parse_block_node(&mut self, parent_indent: i64, in_seq_entry: bool) -> R<Yaml> {
        let _ = in_seq_entry;
        self.skip_ws_comments();
        if self.eof() {
            return Ok(Yaml::Null);
        }
        let col = self.col as i64;
        if col <= parent_indent {
            return Ok(Yaml::Null);
        }
        // anchors / tags
        let (anchor, tag) = self.parse_props()?;
        if anchor.is_some() || tag.is_some() {
            self.skip_spaces();
            if matches!(self.peek(), Some('\n') | None) || self.peek() == Some('#') {
                // node on next lines
                let v = self.parse_block_node(parent_indent, false)?;
                let v = apply_tag(v, &tag);
                if let Some(a) = anchor {
                    self.anchors.insert(a, v.clone());
                }
                return Ok(v);
            }
        }
        let c = self.peek().unwrap();
        let v = if c == '-' && Self::is_blank_or_end(self.peek_at(1)) {
            self.parse_block_seq(self.col as i64)?
        } else if self.line_has_mapping_key() {
            self.parse_block_map(self.col as i64)?
        } else {
            self.parse_flow_or_scalar(parent_indent, true)?
        };
        let v = apply_tag(v, &tag);
        if let Some(a) = anchor {
            self.anchors.insert(a, v.clone());
        }
        Ok(v)
    }

    fn parse_props(&mut self) -> R<(Option<String>, Option<String>)> {
        let mut anchor = None;
        let mut tag = None;
        loop {
            match self.peek() {
                Some('&') => {
                    self.advance();
                    let mut name = String::new();
                    while let Some(c) = self.peek() {
                        if c == ' ' || c == '\t' || c == '\n' || c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
                            break;
                        }
                        name.push(c);
                        self.advance();
                    }
                    anchor = Some(name);
                    self.skip_spaces();
                }
                Some('!') => {
                    let mut name = String::new();
                    while let Some(c) = self.peek() {
                        if c == ' ' || c == '\t' || c == '\n' {
                            break;
                        }
                        name.push(c);
                        self.advance();
                    }
                    tag = Some(name);
                    self.skip_spaces();
                }
                _ => break,
            }
        }
        Ok((anchor, tag))
    }

    /// Does the current line (from pos) contain an implicit mapping key?
    fn line_has_mapping_key(&self) -> bool {
        let mut i = self.pos;
        let c = match self.chars.get(i) {
            Some(c) => *c,
            None => return false,
        };
        if c == '"' || c == '\'' {
            // quoted key
            let q = c;
            i += 1;
            while i < self.chars.len() && self.chars[i] != '\n' {
                if q == '"' && self.chars[i] == '\\' {
                    i += 2;
                    continue;
                }
                if self.chars[i] == q {
                    if q == '\'' && self.chars.get(i + 1) == Some(&'\'') {
                        i += 2;
                        continue;
                    }
                    break;
                }
                i += 1;
            }
            i += 1;
            while i < self.chars.len() && (self.chars[i] == ' ' || self.chars[i] == '\t') {
                i += 1;
            }
            return self.chars.get(i) == Some(&':') && matches!(self.chars.get(i + 1), None | Some(' ') | Some('\t') | Some('\n') | Some('\r'));
        }
        if c == '[' || c == '{' {
            return false;
        }
        if c == '?' && matches!(self.chars.get(i + 1), Some(' ')) {
            return true;
        }
        while i < self.chars.len() && self.chars[i] != '\n' {
            let ch = self.chars[i];
            if ch == ':' && matches!(self.chars.get(i + 1), None | Some(' ') | Some('\t') | Some('\n') | Some('\r')) {
                return true;
            }
            if ch == '#' && i > 0 && (self.chars[i - 1] == ' ' || self.chars[i - 1] == '\t') {
                return false;
            }
            i += 1;
        }
        false
    }

    fn parse_block_seq(&mut self, indent: i64) -> R<Yaml> {
        let mut items = Vec::new();
        loop {
            // at '-'
            self.advance();
            self.skip_spaces();
            let item = if matches!(self.peek(), Some('\n') | None) || (self.peek() == Some('#')) {
                self.parse_block_node(indent, true)?
            } else {
                // inline content: could be nested seq/map at this column
                let c = self.peek().unwrap();
                if c == '-' && Self::is_blank_or_end(self.peek_at(1)) {
                    self.parse_block_seq(self.col as i64)?
                } else if self.line_has_mapping_key() {
                    self.parse_block_map(self.col as i64)?
                } else {
                    let (anchor, tag) = self.parse_props()?;
                    let v = if matches!(self.peek(), Some('\n') | None) {
                        self.parse_block_node(indent, true)?
                    } else {
                        self.parse_flow_or_scalar(indent, true)?
                    };
                    let v = apply_tag(v, &tag);
                    if let Some(a) = anchor {
                        self.anchors.insert(a, v.clone());
                    }
                    v
                }
            };
            items.push(item);
            self.skip_ws_comments();
            if self.eof() {
                break;
            }
            if (self.col as i64) == indent && self.peek() == Some('-') && Self::is_blank_or_end(self.peek_at(1)) {
                continue;
            }
            if (self.col as i64) > indent {
                return Err(self.err("did not find expected '-' indicator"));
            }
            break;
        }
        Ok(Yaml::Array(items))
    }

    fn parse_key(&mut self) -> R<Yaml> {
        let c = self.peek().unwrap();
        if c == '"' || c == '\'' {
            let s = self.parse_quoted()?;
            return Ok(Yaml::String(s));
        }
        let mut s = String::new();
        while let Some(ch) = self.peek() {
            if ch == ':' && Self::is_blank_or_end(self.peek_at(1)) {
                break;
            }
            if ch == '\n' {
                break;
            }
            s.push(ch);
            self.advance();
        }
        Ok(resolve_plain(s.trim_end()))
    }

    fn parse_block_map(&mut self, indent: i64) -> R<Yaml> {
        let mut entries: Vec<(Yaml, Yaml)> = Vec::new();
        loop {
            let c = self.peek().unwrap();
            if c == '@' || c == '`' || c == '%' {
                return Err(self.err(&format!("unexpected character: `{}'", c)));
            }
            let key = self.parse_key()?;
            self.skip_spaces();
            // ':'
            if self.peek() != Some(':') {
                return Err(self.err("could not find expected ':'"));
            }
            self.advance();
            self.skip_spaces();
            let value = if matches!(self.peek(), Some('\n') | None | Some('\r')) || self.peek() == Some('#') {
                // value on next lines
                self.skip_ws_comments();
                if self.eof() {
                    Yaml::Null
                } else if (self.col as i64) == indent && self.peek() == Some('-') && Self::is_blank_or_end(self.peek_at(1)) {
                    self.parse_block_seq(indent)?
                } else if (self.col as i64) > indent {
                    self.parse_block_node(indent, false)?
                } else {
                    Yaml::Null
                }
            } else {
                let c = self.peek().unwrap();
                if c == '-' && Self::is_blank_or_end(self.peek_at(1)) {
                    return Err(self.err("block sequence entries are not allowed in this context"));
                }
                let (anchor, tag) = self.parse_props()?;
                let v = if matches!(self.peek(), Some('\n') | None) {
                    self.parse_block_node(indent, false)?
                } else {
                    self.parse_flow_or_scalar(indent, true)?
                };
                let v = apply_tag(v, &tag);
                if let Some(a) = anchor {
                    self.anchors.insert(a, v.clone());
                }
                v
            };
            // replace duplicate keys
            if let Some(e) = entries.iter_mut().find(|(k, _)| *k == key) {
                e.1 = value;
            } else {
                entries.push((key, value));
            }
            self.skip_ws_comments();
            if self.eof() {
                break;
            }
            let col = self.col as i64;
            if col == indent {
                if self.peek() == Some('-') && Self::is_blank_or_end(self.peek_at(1)) {
                    return Err(self.err("did not find expected key"));
                }
                if self.col == 0 && (self.starts_with("---") || self.starts_with("...")) {
                    break;
                }
                if !self.line_has_mapping_key() {
                    // plain text at mapping level
                    let c = self.peek().unwrap();
                    if c == '@' || c == '`' || c == '%' {
                        return Err(self.err(&format!("unexpected character: `{}'", c)));
                    }
                    return Err(self.err("could not find expected ':'"));
                }
                continue;
            }
            if col > indent {
                if self.line_has_mapping_key() {
                    return Err(self.err("mapping values are not allowed in this context"));
                }
                return Err(self.err("did not find expected key"));
            }
            break;
        }
        Ok(Yaml::Hash(entries))
    }

    fn parse_quoted(&mut self) -> R<String> {
        let start_line = self.line;
        let start_col = self.col;
        let q = self.advance().unwrap();
        let mut s = String::new();
        loop {
            let c = match self.peek() {
                None => return Err(self.err_at("while scanning a quoted scalar, found unexpected end of stream", start_line, start_col)),
                Some(c) => c,
            };
            if c == q {
                if q == '\'' && self.peek_at(1) == Some('\'') {
                    s.push('\'');
                    self.advance();
                    self.advance();
                    continue;
                }
                self.advance();
                break;
            }
            if q == '"' && c == '\\' {
                self.advance();
                let e = match self.advance() {
                    Some(e) => e,
                    None => return Err(self.err_at("while scanning a quoted scalar, found unexpected end of stream", start_line, start_col)),
                };
                match e {
                    '0' => s.push('\0'),
                    'a' => s.push('\x07'),
                    'b' => s.push('\x08'),
                    't' | '\t' => s.push('\t'),
                    'n' => s.push('\n'),
                    'v' => s.push('\x0b'),
                    'f' => s.push('\x0c'),
                    'r' => s.push('\r'),
                    'e' => s.push('\x1b'),
                    ' ' => s.push(' '),
                    '"' => s.push('"'),
                    '/' => s.push('/'),
                    '\\' => s.push('\\'),
                    'N' => s.push('\u{85}'),
                    '_' => s.push('\u{a0}'),
                    'L' => s.push('\u{2028}'),
                    'P' => s.push('\u{2029}'),
                    'x' | 'u' | 'U' => {
                        let n = match e {
                            'x' => 2,
                            'u' => 4,
                            _ => 8,
                        };
                        let mut h = String::new();
                        for _ in 0..n {
                            if let Some(d) = self.advance() {
                                h.push(d);
                            }
                        }
                        let cp = u32::from_str_radix(&h, 16).map_err(|_| self.err("while parsing a quoted scalar, did not find expected hexdecimal number"))?;
                        s.push(char::from_u32(cp).unwrap_or('\u{fffd}'));
                    }
                    '\n' => {
                        // escaped line break
                        self.skip_spaces();
                    }
                    _ => return Err(self.err("while parsing a quoted scalar, found unknown escape character")),
                }
                continue;
            }
            if c == '\n' {
                // line folding
                // trim trailing spaces in s
                while s.ends_with(' ') || s.ends_with('\t') {
                    s.pop();
                }
                let mut newlines = 0;
                while matches!(self.peek(), Some('\n') | Some(' ') | Some('\t') | Some('\r')) {
                    if self.peek() == Some('\n') {
                        newlines += 1;
                    }
                    self.advance();
                }
                if newlines == 1 {
                    s.push(' ');
                } else {
                    for _ in 1..newlines {
                        s.push('\n');
                    }
                }
                continue;
            }
            s.push(c);
            self.advance();
        }
        Ok(s)
    }

    fn parse_flow_or_scalar(&mut self, parent_indent: i64, block_ctx: bool) -> R<Yaml> {
        let c = match self.peek() {
            Some(c) => c,
            None => return Ok(Yaml::Null),
        };
        match c {
            '[' => return self.parse_flow_seq(),
            '{' => return self.parse_flow_map(),
            '"' | '\'' => {
                let s = self.parse_quoted()?;
                self.check_after_scalar()?;
                return Ok(Yaml::String(s));
            }
            '|' | '>' if block_ctx => return self.parse_block_scalar(parent_indent),
            '*' => {
                let line = self.line;
                let col = self.col;
                self.advance();
                let mut name = String::new();
                while let Some(ch) = self.peek() {
                    if ch == ' ' || ch == '\t' || ch == '\n' || ch == ',' || ch == ']' || ch == '}' {
                        break;
                    }
                    name.push(ch);
                    self.advance();
                }
                return match self.anchors.get(&name) {
                    Some(v) => Ok(v.clone()),
                    None => Err(self.err_at("while parsing node, found unknown anchor", line, col)),
                };
            }
            '@' | '`' | '%' => return Err(self.err(&format!("unexpected character: `{}'", c))),
            _ => {}
        }
        // plain scalar, possibly multi-line
        let mut s = String::new();
        let mut pending_newlines = 0;
        loop {
            // read rest of line
            let mut line = String::new();
            while let Some(ch) = self.peek() {
                if ch == '\n' {
                    break;
                }
                if ch == ':' && Self::is_blank_or_end(self.peek_at(1)) {
                    return Err(self.err("mapping values are not allowed in this context"));
                }
                if ch == '#' && (line.ends_with(' ') || line.ends_with('\t')) {
                    // comment
                    while !matches!(self.peek(), None | Some('\n')) {
                        self.advance();
                    }
                    break;
                }
                line.push(ch);
                self.advance();
            }
            let line = line.trim_end().to_string();
            if !line.is_empty() {
                if !s.is_empty() {
                    if pending_newlines <= 1 {
                        s.push(' ');
                    } else {
                        for _ in 1..pending_newlines {
                            s.push('\n');
                        }
                    }
                }
                s.push_str(&line);
            }
            // check continuation
            let save = (self.pos, self.line, self.col);
            pending_newlines = 0;
            let mut cont = false;
            loop {
                match self.peek() {
                    Some('\n') => {
                        pending_newlines += 1;
                        self.advance();
                        while matches!(self.peek(), Some(' ') | Some('\t')) {
                            self.advance();
                        }
                    }
                    Some('#') => break,
                    None => break,
                    _ => {
                        if (self.col as i64) > parent_indent && pending_newlines > 0 {
                            if self.col == 0 && (self.starts_with("---") || self.starts_with("...")) {
                                break;
                            }
                            cont = true;
                        }
                        break;
                    }
                }
            }
            if !cont {
                self.pos = save.0;
                self.line = save.1;
                self.col = save.2;
                break;
            }
            // continuation line: a mapping key here is an error
            let c = self.peek().unwrap();
            if c == '-' && Self::is_blank_or_end(self.peek_at(1)) && false {
                break;
            }
        }
        Ok(resolve_plain(&s))
    }

    fn check_after_scalar(&mut self) -> R<()> {
        self.skip_spaces();
        match self.peek() {
            None | Some('\n') | Some('#') | Some('\r') => Ok(()),
            Some(':') => Err(self.err("mapping values are not allowed in this context")),
            Some(_) => Err(self.err("did not find expected key")),
        }
    }

    fn parse_block_scalar(&mut self, parent_indent: i64) -> R<Yaml> {
        let literal = self.advance() == Some('|');
        let mut chomp = 0; // 0 clip, 1 keep, -1 strip
        let mut explicit_indent: Option<usize> = None;
        while let Some(c) = self.peek() {
            match c {
                '+' => {
                    chomp = 1;
                    self.advance();
                }
                '-' => {
                    chomp = -1;
                    self.advance();
                }
                '1'..='9' => {
                    explicit_indent = Some(c.to_digit(10).unwrap() as usize);
                    self.advance();
                }
                _ => break,
            }
        }
        // rest of line (comment)
        while !matches!(self.peek(), None | Some('\n')) {
            self.advance();
        }
        if self.peek() == Some('\n') {
            self.advance();
        }
        // collect lines
        let mut lines: Vec<String> = Vec::new();
        let mut indent: Option<usize> = explicit_indent.map(|e| (parent_indent.max(-1) + 1) as usize + e - 1 + 0);
        loop {
            if self.eof() {
                break;
            }
            // measure indentation
            let mut k = 0;
            while self.peek_at(k) == Some(' ') {
                k += 1;
            }
            let after = self.peek_at(k);
            if matches!(after, Some('\n') | None) {
                // blank line
                for _ in 0..k {
                    self.advance();
                }
                lines.push(String::new());
                if self.peek() == Some('\n') {
                    self.advance();
                    continue;
                } else {
                    break;
                }
            }
            let ind = match indent {
                Some(i) => i,
                None => {
                    if (k as i64) <= parent_indent {
                        break;
                    }
                    indent = Some(k);
                    k
                }
            };
            if k < ind {
                break;
            }
            for _ in 0..ind {
                self.advance();
            }
            let mut l = String::new();
            while let Some(c) = self.peek() {
                if c == '\n' {
                    break;
                }
                l.push(c);
                self.advance();
            }
            lines.push(l);
            if self.peek() == Some('\n') {
                self.advance();
            } else {
                break;
            }
        }
        // remove trailing empty lines for chomping
        let mut trailing = 0;
        while lines.last().map(|l| l.is_empty()).unwrap_or(false) {
            lines.pop();
            trailing += 1;
        }
        let mut s = String::new();
        if literal {
            for l in &lines {
                s.push_str(l);
                s.push('\n');
            }
        } else {
            let mut prev_more_indented = false;
            for (i, l) in lines.iter().enumerate() {
                let more = l.starts_with(' ') || l.starts_with('\t');
                if i > 0 {
                    if l.is_empty() {
                        s.push('\n');
                    } else if lines[i - 1].is_empty() {
                        // already newline added
                    } else if more || prev_more_indented {
                        s.push('\n');
                    } else {
                        s.push(' ');
                    }
                }
                s.push_str(l);
                prev_more_indented = more;
            }
            if !lines.is_empty() {
                s.push('\n');
            }
        }
        if lines.is_empty() {
            s.clear();
        }
        match chomp {
            -1 => {
                while s.ends_with('\n') {
                    s.pop();
                }
            }
            1 => {
                for _ in 0..trailing {
                    s.push('\n');
                }
            }
            _ => {}
        }
        // move back before the newline that ended the scalar so parent sees line start
        Ok(Yaml::String(s))
    }

    fn skip_flow_ws(&mut self) {
        loop {
            match self.peek() {
                Some(' ') | Some('\t') | Some('\n') | Some('\r') => {
                    self.advance();
                }
                Some('#') => {
                    while !matches!(self.peek(), None | Some('\n')) {
                        self.advance();
                    }
                }
                _ => break,
            }
        }
    }

    fn parse_flow_scalar(&mut self) -> R<Yaml> {
        let c = self.peek();
        match c {
            Some('"') | Some('\'') => return Ok(Yaml::String(self.parse_quoted()?)),
            Some('[') => return self.parse_flow_seq(),
            Some('{') => return self.parse_flow_map(),
            Some('*') => return self.parse_flow_or_scalar(-1, false),
            Some('@') | Some('`') | Some('%') => return Err(self.err(&format!("unexpected character: `{}'", c.unwrap()))),
            _ => {}
        }
        let mut s = String::new();
        while let Some(ch) = self.peek() {
            if ch == ',' || ch == ']' || ch == '}' || ch == '[' || ch == '{' {
                break;
            }
            if ch == ':' && (Self::is_blank_or_end(self.peek_at(1)) || matches!(self.peek_at(1), Some(',') | Some(']') | Some('}'))) {
                break;
            }
            if ch == '#' && (s.ends_with(' ') || s.ends_with('\n')) {
                break;
            }
            if ch == '\n' {
                s.push(' ');
                self.advance();
                continue;
            }
            s.push(ch);
            self.advance();
        }
        let t: String = s.split_whitespace().collect::<Vec<_>>().join(" ");
        if t.is_empty() {
            return Ok(Yaml::Null);
        }
        Ok(resolve_plain(&t))
    }

    fn parse_flow_seq(&mut self) -> R<Yaml> {
        let start = (self.line, self.col);
        self.advance();
        let mut items = Vec::new();
        loop {
            self.skip_flow_ws();
            match self.peek() {
                None => return Err(self.err_at("while parsing a flow sequence, expected ',' or ']'", start.0, start.1)),
                Some(']') => {
                    self.advance();
                    break;
                }
                _ => {}
            }
            let (anchor, tag) = self.parse_props()?;
            let mut v = self.parse_flow_scalar()?;
            self.skip_flow_ws();
            if self.peek() == Some(':') {
                // single pair mapping
                self.advance();
                self.skip_flow_ws();
                let val = if matches!(self.peek(), Some(',') | Some(']')) { Yaml::Null } else { self.parse_flow_scalar()? };
                v = Yaml::Hash(vec![(v, val)]);
                self.skip_flow_ws();
            }
            let v = apply_tag(v, &tag);
            if let Some(a) = anchor {
                self.anchors.insert(a, v.clone());
            }
            items.push(v);
            match self.peek() {
                Some(',') => {
                    self.advance();
                }
                Some(']') => {
                    self.advance();
                    break;
                }
                None => return Err(self.err_at("while parsing a flow sequence, expected ',' or ']'", start.0, start.1)),
                _ => return Err(self.err("while parsing a flow sequence, expected ',' or ']'")),
            }
        }
        self.check_after_flow()?;
        Ok(Yaml::Array(items))
    }

    fn parse_flow_map(&mut self) -> R<Yaml> {
        let start = (self.line, self.col);
        self.advance();
        let mut entries = Vec::new();
        loop {
            self.skip_flow_ws();
            match self.peek() {
                None => return Err(self.err_at("while parsing a flow mapping, did not find expected ',' or '}'", start.0, start.1)),
                Some('}') => {
                    self.advance();
                    break;
                }
                _ => {}
            }
            let k = self.parse_flow_scalar()?;
            self.skip_flow_ws();
            let v = if self.peek() == Some(':') {
                self.advance();
                self.skip_flow_ws();
                if matches!(self.peek(), Some(',') | Some('}')) {
                    Yaml::Null
                } else {
                    let (anchor, tag) = self.parse_props()?;
                    let v = apply_tag(self.parse_flow_scalar()?, &tag);
                    if let Some(a) = anchor {
                        self.anchors.insert(a, v.clone());
                    }
                    v
                }
            } else {
                Yaml::Null
            };
            entries.push((k, v));
            self.skip_flow_ws();
            match self.peek() {
                Some(',') => {
                    self.advance();
                }
                Some('}') => {
                    self.advance();
                    break;
                }
                None => return Err(self.err_at("while parsing a flow mapping, did not find expected ',' or '}'", start.0, start.1)),
                _ => return Err(self.err("while parsing a flow mapping, did not find expected ',' or '}'")),
            }
        }
        self.check_after_flow()?;
        Ok(Yaml::Hash(entries))
    }

    fn check_after_flow(&mut self) -> R<()> {
        let save = (self.pos, self.line, self.col);
        self.skip_spaces();
        let r = match self.peek() {
            None | Some('\n') | Some('#') | Some('\r') | Some(',') | Some(']') | Some('}') | Some(':') => Ok(()),
            Some(_) => Err(self.err("did not find expected key")),
        };
        self.pos = save.0;
        self.line = save.1;
        self.col = save.2;
        r
    }
}

fn apply_tag(v: Yaml, tag: &Option<String>) -> Yaml {
    match tag.as_deref() {
        Some("!!str") => match v {
            Yaml::Integer(i) => Yaml::String(i.to_string()),
            Yaml::Real(r) => Yaml::String(r),
            Yaml::Boolean(b) => Yaml::String(b.to_string()),
            Yaml::Null => Yaml::String(String::new()),
            x => x,
        },
        Some("!!int") => match &v {
            Yaml::String(s) => s.parse::<i64>().map(Yaml::Integer).unwrap_or(Yaml::BadValue),
            _ => v,
        },
        _ => v,
    }
}

pub fn load(src: &str) -> Result<Vec<Yaml>, YamlError> {
    let mut p = P { chars: src.chars().collect(), pos: 0, line: 0, col: 0, anchors: HashMap::new(), _src: src };
    match p.parse_document()? {
        Some(d) => Ok(vec![d]),
        None => Ok(vec![]),
    }
}
