                Yaml::Array(arr) => {
                    let mut v = Vec::new();
                    for a in arr {
                        match a {
                            Yaml::String(s) => v.push(s.clone()),
                            _ => return Err(format!("Expected only string in the list for key {}, found {}", key, a.debug())),
                        }
                    }
                    if key == "output" {
                        for f in &v {
                            if !VALID_FORMATS.contains(&f.as_str()) {
                                return Err(format!("The output format {} for key output is not recognized", f));
                            }
                        }
                    }
                    OptValue::StrVec(v)
                }
                _ => return Err(format!("Expected a list as value for key {}, found {}", key, value.debug())),
            },
        };
        if key == "output" {
            if let OptValue::StrVec(ref formats) = v {
                for f in formats {
                    let stem = self.book_stem.clone();
                    let ext = match f.as_str() {
                        "epub" => format!("{}.epub", stem),
                        "pdf" => format!("{}.pdf", stem),
                        "html" => format!("{}.html", stem),
                        "tex" => format!("{}.tex", stem),
                        "odt" => format!("{}.odt", stem),
                        "html.dir" => stem.clone(),
                        "proofread.html" => format!("{}.proof.html", stem),
                        "proofread.html.dir" => format!("{}_proof", stem),
                        "proofread.pdf" => format!("{}.proof.pdf", stem),
                        _ => continue,
                    };
                    self.values.insert(format!("output.{}", f), OptValue::Str(ext));
