    pub fn set_yaml(&mut self, key: &str, value: &Yaml, warnings: &mut Vec<String>) -> Result<(), String> {
        let mut key = key.to_string();
        loop {
            if let Some(dep) = self.deprecated.get(&key).cloned() {
                match dep {
                    Some(new) => {
                        warnings.push(format!("'{}' has been deprecated, you should now use '{}'", key, new));
                        key = new;
                        continue;
                    }
                    None => return Err(format!("key '{}' has been deprecated.", key)),
                }
            }
            break;
        }
        let def = match self.defs.get(&key) {
            Some(d) => d.clone(),
            None => return Err(format!("unrecognized key '{}'", key)),
        };
        let v = match def.ty {
            OptType::Meta | OptType::Str | OptType::Path | OptType::Tpl => match value {
                Yaml::String(s) => OptValue::Str(s.clone()),
                _ => return Err(format!("Expected a string as value for key {}, found {}", key, value.debug())),
            },
            OptType::Bool => match value {
                Yaml::Boolean(b) => OptValue::Bool(*b),
                _ => return Err(format!("expected a boolean as value for key '{}', found {}", key, value.debug())),
            },
            OptType::Int => match value {
                Yaml::Integer(i) => OptValue::Int(*i),
                _ => return Err(format!("expected an integer as value for key '{}', found {}", key, value.debug())),
            },
            OptType::Float => match value {
                Yaml::Real(r) => match r.parse::<f64>() {
                    Ok(f) => OptValue::Float(f),
                    Err(_) => return Err(format!("could not parse '{}' as a float for key '{}'", value.debug(), key)),
                },
                Yaml::Integer(i) => OptValue::Float(*i as f64),
                _ => return Err(format!("could not parse '{}' as a float for key '{}'", value.debug(), key)),
            },
            OptType::StrVec => match value {
                Yaml::Array(arr) => {
                    let mut v = Vec::new();
                    for a in arr {
                        match a {
                            Yaml::String(s) => v.push(s.clone()),
                            _ => return Err(format!("Expected only string in the list for key {}, found {}", key, a.debug())),
                        }
                    }
                    if key == "output" {
                        for f in &v {
                            if !VALID_FORMATS.contains(&f.as_str()) {
                                return Err(format!("The output format {} for key output is not recognized", f));
                            }
                        }
                    }
                    OptValue::StrVec(v)
                }
                _ => return Err(format!("Expected a list as value for key {}, found {}", key, value.debug())),
            },
        };
        if key == "output" {
            if let OptValue::StrVec(ref formats) = v {
                for f in formats {
                    let stem = self.book_stem.clone();
                    let ext = match f.as_str() {
                        "epub" => format!("{}.epub", stem),
                        "pdf" => format!("{}.pdf", stem),
                        "html" => format!("{}.html", stem),
                        "tex" => format!("{}.tex", stem),
                        "odt" => format!("{}.odt", stem),
                        "html.dir" => stem.clone(),
                        "proofread.html" => format!("{}.proof.html", stem),
                        "proofread.html.dir" => format!("{}_proof", stem),
                        "proofread.pdf" => format!("{}.proof.pdf", stem),
                        _ => continue,
                    };
                    self.values.insert(format!("output.{}", f), OptValue::Str(ext));
                }
            }
        }
        self.values.insert(key, v);
        Ok(())
    }

    pub fn get(&self, key: &str) -> Option<OptValue> {
        if let Some(v) = self.values.get(key) {
            return Some(v.clone());
        }
        self.defs.get(key).and_then(|d| d.default.clone())
    }
    pub fn is_set(&self, key: &str) -> bool {
        self.values.contains_key(key)
    }
    pub fn get_str(&self, key: &str) -> Option<String> {
        match self.get(key) {
            Some(OptValue::Str(s)) => Some(s),
            _ => None,
        }
    }
    pub fn str_or(&self, key: &str, d: &str) -> String {
        self.get_str(key).unwrap_or_else(|| d.to_string())
    }
    pub fn get_bool(&self, key: &str) -> bool {
        match self.get(key) {
            Some(OptValue::Bool(b)) => b,
            _ => false,
        }
    }
    pub fn get_bool_opt(&self, key: &str) -> Option<bool> {
        match self.get(key) {
            Some(OptValue::Bool(b)) => Some(b),
            _ => None,
        }
    }
    pub fn get_int(&self, key: &str) -> Option<i64> {
        match self.get(key) {
            Some(OptValue::Int(i)) => Some(i),
            _ => None,
        }
    }
    pub fn get_vec(&self, key: &str) -> Option<Vec<String>> {
        match self.get(key) {
            Some(OptValue::StrVec(v)) => Some(v),
            _ => None,
        }
    }
}
