// Logging, mimicking crowbook's different UI modes
use std::io::Write;
use std::sync::Mutex;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Mode {
    Fancy,
    Simple,
    Quiet,
    Verbose,
}

#[derive(Clone, Copy, PartialEq, PartialOrd, Debug)]
pub enum Level {
    Error,
    Warn,
    Info,
    Debug,
}

pub struct Logger {
    pub mode: Mode,
    pub collected: Vec<(Level, String)>,
}

pub static LOGGER: Mutex<Logger> = Mutex::new(Logger { mode: Mode::Fancy, collected: Vec::new() });

pub fn set_mode(m: Mode) {
    LOGGER.lock().unwrap().mode = m;
}

pub fn mode() -> Mode {
    LOGGER.lock().unwrap().mode
}

fn now_hms() -> String {
    let secs = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
    let s = secs % 86400;
    format!("{:02}:{:02}:{:02}", s / 3600, (s / 60) % 60, s % 60)
}

pub fn log(level: Level, target: &str, msg: &str) {
    let mut l = LOGGER.lock().unwrap();
    let stderr = std::io::stderr();
    let mut e = stderr.lock();
    match l.mode {
        Mode::Fancy => {
            if level <= Level::Warn {
                l.collected.push((level, msg.to_string()));
            }
        }
        Mode::Simple => {
            if level <= Level::Info {
                let lv = match level {
                    Level::Error => "ERROR",
                    Level::Warn => "WARN",
                    Level::Info => "INFO",
                    Level::Debug => "DEBUG",
                };
                let _ = writeln!(e, "[{}] {}", lv, msg);
            }
        }
        Mode::Quiet => {
            if level == Level::Error {
                let _ = writeln!(e, "[ERROR] {}", msg);
            }
        }
        Mode::Verbose => {
            let lv = match level {
                Level::Error => "ERROR",
                Level::Warn => "WARN",
                Level::Info => "INFO",
                Level::Debug => "DEBUG",
            };
            let _ = writeln!(e, "{} [{}] {}: {}", now_hms(), lv, target, msg);
        }
    }
}

pub fn error(msg: &str) {
    log(Level::Error, "crowbook::book", msg);
}
pub fn warn(msg: &str) {
    log(Level::Warn, "crowbook::book", msg);
}
pub fn info(msg: &str) {
    log(Level::Info, "crowbook::book", msg);
}
pub fn debug(msg: &str) {
    log(Level::Debug, "crowbook::book", msg);
}

/// print a fatal error
pub fn print_error(msg: &str) {
    let _ = writeln!(std::io::stderr(), "ERROR {}", msg);
}

/// At exit: print collected messages in fancy mode
pub fn finish() {
    let l = LOGGER.lock().unwrap();
    if l.mode == Mode::Fancy && !l.collected.is_empty() {
        let mut e = std::io::stderr();
        let _ = writeln!(e, "WARNING Crowbook exited successfully, but the following errors occurred:");
        for (lv, m) in &l.collected {
            let s = match lv {
                Level::Error => "ERROR",
                _ => "WARNING",
            };
            let _ = writeln!(e, "{} {}", s, m);
        }
    }
}
