// Convert the markdown AST to crowbook tokens
use crate::md_ast::*;
use crate::md_block::{ParseOptions, Parser};
use crate::token::Token;

pub struct MdOptions {
    pub html_as_text: bool,
    pub superscript: bool,
}

pub fn parse_markdown(text: &str, opts: &MdOptions) -> Vec<Token> {
    let mut p = Parser::new(ParseOptions { superscript: opts.superscript });
    p.feed(text);
    let (mut arena, root, _refmap) = p.finish();
    process_tasklists(&mut arena, root);
    let toks = convert_children(&arena, root, opts);
    merge_str(toks)
}

fn process_tasklists(arena: &mut Arena, node: usize) {
    let children = arena.nodes[node].children.clone();
    for &c in &children {
        process_tasklists(arena, c);
    }
    if let NodeValue::Item(_) = arena.nodes[node].value {
        // first child paragraph, first text
        let para = match arena.nodes[node].children.first() {
            Some(&p) => p,
            None => return,
        };
        if !matches!(arena.nodes[para].value, NodeValue::Paragraph) {
            return;
        }
        let text_node = match arena.nodes[para].children.first() {
            Some(&t) => t,
            None => return,
        };
        let text = match &arena.nodes[text_node].value {
            NodeValue::Text(t) => t.clone(),
            _ => return,
        };
        let chars: Vec<char> = text.chars().collect();
        if chars.len() >= 3 && chars[0] == '[' && chars[2] == ']' && (chars[1] == ' ' || chars[1] == 'x' || chars[1] == 'X') {
            let after = chars.get(3).cloned();
            let ok = match after {
                None => true,
                Some(c) => c == ' ' || c == '\t' || c == '\n',
            };
            if !ok {
                return;
            }
            let skip = if after.is_some() { 4 } else { 3 };
            let rest: String = chars[skip..].iter().collect();
            arena.nodes[text_node].value = NodeValue::Text(rest);
            arena.nodes[node].value = NodeValue::TaskItem(chars[1] != ' ');
        }
    }
}

fn convert_children(arena: &Arena, node: usize, opts: &MdOptions) -> Vec<Token> {
    let mut out = Vec::new();
    for &c in &arena.nodes[node].children {
        if let Some(t) = convert(arena, c, opts) {
            out.push(t);
        }
    }
    out
}

fn convert(arena: &Arena, n: usize, opts: &MdOptions) -> Option<Token> {
    let node = &arena.nodes[n];
    Some(match &node.value {
        NodeValue::Document => return None,
        NodeValue::BlockQuote => Token::BlockQuote(convert_children(arena, n, opts)),
        NodeValue::List(ld) => {
            let items = convert_children(arena, n, opts);
            match ld.list_type {
                ListType::Bullet => Token::List(items),
                ListType::Ordered => Token::OrderedList(ld.start, items),
            }
        }
        NodeValue::Item(_) => Token::Item(convert_children(arena, n, opts)),
        NodeValue::TaskItem(checked) => Token::TaskItem(*checked, convert_children(arena, n, opts)),
        NodeValue::DescriptionList => Token::DescriptionList(convert_children(arena, n, opts)),
        NodeValue::DescriptionItem(..) => Token::DescriptionItem(convert_children(arena, n, opts)),
        NodeValue::DescriptionTerm => {
            // flatten paragraphs
            let mut v = Vec::new();
            for &c in &node.children {
                if let NodeValue::Paragraph = arena.nodes[c].value {
                    v.extend(convert_children(arena, c, opts));
                } else if let Some(t) = convert(arena, c, opts) {
                    v.push(t);
                }
            }
            Token::DescriptionTerm(v)
        }
        NodeValue::DescriptionDetails => Token::DescriptionDetails(convert_children(arena, n, opts)),
        NodeValue::CodeBlock { info, literal, .. } => Token::CodeBlock(info.clone(), literal.clone()),
        NodeValue::HtmlBlock { literal, .. } => {
            if opts.html_as_text {
                Token::Str(literal.clone())
            } else {
                return None;
            }
        }
        NodeValue::Paragraph => {
            let inner = convert_children(arena, n, opts);
            let inner = merge_str(inner);
            if inner.len() == 1 {
                if let Token::Image(u, t, c) = &inner[0] {
                    return Some(Token::StandaloneImage(u.clone(), t.clone(), c.clone()));
                }
            }
            Token::Paragraph(inner)
        }
        NodeValue::Heading { level, .. } => Token::Header(*level as i32, convert_children(arena, n, opts)),
        NodeValue::ThematicBreak => Token::Rule,
        NodeValue::FootnoteDefinition(name) => Token::FootnoteDefinition(name.clone(), convert_children(arena, n, opts)),
        NodeValue::Table(aligns) => {
            let mut rows = Vec::new();
            for &r in &node.children {
                let cells: Vec<Token> = arena.nodes[r].children.iter().map(|&c| Token::TableCell(convert_children(arena, c, opts))).collect();
                match arena.nodes[r].value {
                    NodeValue::TableRow(true) => rows.push(Token::TableHead(cells)),
                    _ => rows.push(Token::TableRow(cells)),
                }
            }
            Token::Table(aligns.len(), rows)
        }
        NodeValue::TableRow(_) | NodeValue::TableCell => return None,
        NodeValue::Text(t) => Token::Str(t.clone()),
        NodeValue::SoftBreak => Token::Str(" ".to_string()),
        NodeValue::LineBreak => Token::HardBreak,
        NodeValue::Code(c) => Token::Code(c.clone()),
        NodeValue::HtmlInline(h) => {
            if opts.html_as_text {
                Token::Str(h.clone())
            } else {
                return None;
            }
        }
        NodeValue::Emph => Token::Emphasis(convert_children(arena, n, opts)),
        NodeValue::Strong => Token::Strong(convert_children(arena, n, opts)),
        NodeValue::Strikethrough => Token::Strikethrough(convert_children(arena, n, opts)),
        NodeValue::Superscript => Token::Superscript(convert_children(arena, n, opts)),
        NodeValue::Subscript => Token::Subscript(convert_children(arena, n, opts)),
        NodeValue::Link { url, title } => Token::Link(url.clone(), title.clone(), convert_children(arena, n, opts)),
        NodeValue::Image { url, title } => Token::Image(url.clone(), title.clone(), convert_children(arena, n, opts)),
        NodeValue::FootnoteReference(name) => Token::FootnoteReference(name.clone()),
    })
}

pub fn merge_str(tokens: Vec<Token>) -> Vec<Token> {
    let mut out: Vec<Token> = Vec::new();
    for t in tokens {
        let t = match t {
            Token::Str(s) => {
                if let Some(Token::Str(prev)) = out.last_mut() {
                    prev.push_str(&s);
                    continue;
                }
                Token::Str(s)
            }
            mut other => {
                if let Some(v) = other.inner_mut() {
                    let inner = std::mem::take(v);
                    *v = merge_str(inner);
                }
                other
            }
        };
        out.push(t);
    }
    out
}

/// Parse inline markdown (for metadata) and return the inline tokens
pub fn parse_inline(text: &str, opts: &MdOptions) -> Vec<Token> {
    let toks = parse_markdown(text, opts);
    if toks.len() == 1 {
        if let Token::Paragraph(v) = &toks[0] {
            return v.clone();
        }
    }
    toks
}
EOF
echo ok"}

