// Book loading
use crate::cleaner::Cleaner;
use crate::logger;
use crate::options::{OptValue, Options};
use crate::parser::{merge_str, parse_inline, parse_markdown, MdOptions};
use crate::token::Token;
use crate::yaml::{self, Yaml};
use std::path::{Path, PathBuf};

#[derive(Clone, Debug, PartialEq)]
pub enum Number {
    Default,
    Unnumbered,
    Specified(i64),
    Hidden,
    DefaultPart,
    UnnumberedPart,
    SpecifiedPart(i64),
}

impl Number {
    pub fn is_part(&self) -> bool {
        matches!(self, Number::DefaultPart | Number::UnnumberedPart | Number::SpecifiedPart(_))
    }
    pub fn is_numbered(&self) -> bool {
        matches!(self, Number::Default | Number::Specified(_) | Number::DefaultPart | Number::SpecifiedPart(_))
    }
}

#[derive(Clone, Debug)]
pub struct Chapter {
    pub number: Number,
    pub filename: String,
    pub content: Vec<Token>,
}

pub struct Book {
    pub options: Options,
    pub chapters: Vec<Chapter>,
    pub source_file: Option<String>,
    pub source_line: Option<usize>,
    pub root: PathBuf,
    pub book_path: Option<PathBuf>,
}

pub struct BookError {
    pub msg: String,
}

impl BookError {
    pub fn new(s: String) -> BookError {
        BookError { msg: s }
    }
}

pub fn source_prefix(file: &Option<String>, line: Option<usize>) -> String {
    match (file, line) {
        (Some(f), Some(l)) => format!("{}:{}: ", f, l),
        (Some(f), None) => format!("{}: ", f),
        _ => String::new(),
    }
}

impl Book {
    pub fn new() -> Book {
        Book { options: Options::new(), chapters: Vec::new(), source_file: None, source_line: None, root: PathBuf::from("."), book_path: None }
    }

    pub fn prefix(&self) -> String {
        source_prefix(&self.source_file, self.source_line)
    }

    pub fn lang(&self) -> String {
        self.options.str_or("lang", "en")
    }

    pub fn cleaner(&self) -> Cleaner {
        let lang = self.lang().to_lowercase();
        Cleaner {
            enabled: self.options.get_bool("input.clean"),
            french: lang.starts_with("fr"),
            smart_quotes: self.options.get_bool("input.clean.smart_quotes"),
            ligature_dashes: self.options.get_bool("input.clean.ligature.dashes"),
            ligature_guillemets: self.options.get_bool("input.clean.ligature.guillemets"),
        }
    }

    pub fn md_options(&self) -> MdOptions {
        MdOptions { html_as_text: self.options.get_bool("crowbook.html_as_text"), superscript: self.options.get_bool("crowbook.markdown.superscript") }
    }

    /// Set options from a YAML string; returns Err for YAML format errors
    pub fn set_options_from_yaml(&mut self, s: &str) -> Result<(), Result<String, String>> {
        let docs = match yaml::load(s) {
            Ok(d) => d,
            Err(e) => return Err(Err(format!("YAML block was not valid YAML: {}", e))),
        };
        if docs.is_empty() {
            logger::debug(&format!("Ignoring YAML block:\n{}", s));
            return Ok(());
        }
        match &docs[0] {
            Yaml::Hash(h) => {
                for (k, v) in h {
                    let key = match k {
                        Yaml::String(s) => s.clone(),
                        other => {
                            logger::error(&format!("{}Error converting BookOption: Expected a String as a key, found {}", self.prefix(), other.debug()));
                            continue;
                        }
                    };
                    self.set_yaml_option(&key, v);
                }
                Ok(())
            }
            _ => Err(Ok("\"could not parse %{file} as a book file.\"".to_string())),
        }
    }

    pub fn set_yaml_option(&mut self, key: &str, v: &Yaml) {
        if key == "import" {
            match v {
                Yaml::String(path) => {
                    let p = self.root.join(path);
                    if let Err(e) = self.import(&p, path) {
                        logger::error(&e.msg);
                    }
                }
                other => logger::error(&format!("{}Error converting BookOption: Expected a string as value for key import, found {}", self.prefix(), other.debug())),
            }
            return;
        }
        let mut warnings = Vec::new();
        let r = self.options.set_yaml(key, v, &mut warnings);
        for w in warnings {
            logger::warn(&w);
        }
        if let Err(e) = r {
            logger::error(&format!("{}Error converting BookOption: {}", self.prefix(), e));
        }
    }

    fn import(&mut self, path: &Path, display: &str) -> Result<(), BookError> {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => return Err(BookError::new(format!("Could not find file '{}' for book", display))),
        };
        let mut other = Book::new();
        other.root = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        other.source_file = Some(display.to_string());
        other.options.book_stem = self.options.book_stem.clone();
        other.read_config(&content, false)?;
        for (k, v) in other.options.values {
            if !self.options.values.contains_key(&k) {
                self.options.values.insert(k, v);
            }
        }
        Ok(())
    }

    pub fn load_file(&mut self, path: &str) -> Result<(), BookError> {
        let p = PathBuf::from(path);
        let content = match std::fs::read_to_string(&p) {
            Ok(c) => c,
            Err(_) => return Err(BookError::new(format!("Could not find file '{}' for book", path))),
        };
        self.source_file = Some(path.to_string());
        self.root = p.parent().map(|x| x.to_path_buf()).unwrap_or_default();
        if self.root.as_os_str().is_empty() {
            self.root = PathBuf::from(".");
        }
        self.book_path = Some(p.clone());
        self.options.book_stem = p.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
        self.options.root = self.root.clone();
        self.read_config(&content, true)
    }

    pub fn read_config(&mut self, s: &str, with_chapters: bool) -> Result<(), BookError> {
        let lines: Vec<&str> = s.lines().collect();
        let mut idx = 0;
        let mut yaml_block = String::new();
        let mut line_number = 0;
        let is_chapter_line = |l: &str| l.starts_with(|c: char| matches!(c, '-' | '+' | '!' | '@') || c.is_ascii_digit());
        loop {
            if idx >= lines.len() {
                break;
            }
            if is_chapter_line(lines[idx]) {
                break;
            }
            let line = lines[idx];
            idx += 1;
            line_number += 1;
            self.source_line = Some(line_number);
            yaml_block.push_str(line);
            yaml_block.push('\n');
            let t = line.trim();
            if t.ends_with('>') || t.ends_with('|') || t.ends_with(':') || t.ends_with('-') {
                continue;
            }
            let next_ok = if idx < lines.len() {
                match yaml::load(lines[idx]) {
                    Ok(d) => !d.is_empty() && matches!(d[0], Yaml::Hash(_)),
                    Err(_) => false,
                }
            } else {
                break;
            };
            if !next_ok {
                continue;
            }
            match self.set_options_from_yaml(&yaml_block) {
                Ok(()) => yaml_block.clear(),
                Err(Err(_)) => continue,
                Err(Ok(msg)) => return Err(BookError::new(format!("{}Error parsing configuration file: {}", self.prefix(), msg))),
            }
        }
        if !yaml_block.is_empty() {
            match self.set_options_from_yaml(&yaml_block) {
                Ok(()) => {}
                Err(Err(msg)) | Err(Ok(msg)) => return Err(BookError::new(format!("{}Error parsing configuration file: {}", self.prefix(), msg))),
            }
        }
        if !with_chapters {
            return Ok(());
        }
        // chapters
        let mut chapter_lines: Vec<(usize, Number, String)> = Vec::new();
        while idx < lines.len() {
            let line = lines[idx];
            idx += 1;
            line_number += 1;
            self.source_line = Some(line_number);
            let t = line.trim();
            if t.is_empty() || t.starts_with('#') {
                continue;
            }
            let (number, file) = self.parse_chapter_line(line)?;
            chapter_lines.push((line_number, number, file));
        }
        for (ln, number, file) in chapter_lines {
            self.source_line = Some(ln);
            self.add_chapter(number, &file)?;
        }
        Ok(())
    }

    fn parse_chapter_line(&self, line: &str) -> Result<(Number, String), BookError> {
        let err = |m: &str| BookError::new(format!("{}Error parsing configuration file: {}", self.prefix(), m));
        let line = line.trim_end();
        let get_filename = |s: &str| -> Result<String, BookError> {
            let f = s.trim();
            if f.is_empty() {
                return Err(err("no chapter name specified"));
            }
            if f.contains(char::is_whitespace) {
                return Err(err("error.chapter_whitespace"));
            }
            Ok(f.to_string())
        };
        if let Some(rest) = line.strip_prefix('-') {
            if rest.starts_with("--") {
                return Ok((Number::Unnumbered, String::new()));
            }
            return Ok((Number::Unnumbered, get_filename(rest)?));
        }
        if let Some(rest) = line.strip_prefix('+') {
            return Ok((Number::Default, get_filename(rest)?));
        }
        if let Some(rest) = line.strip_prefix('!') {
            return Ok((Number::Hidden, get_filename(rest)?));
        }
        if let Some(rest) = line.strip_prefix('@') {
            if let Some(r) = rest.strip_prefix('+') {
                return Ok((Number::DefaultPart, get_filename(r)?));
            }
            if let Some(r) = rest.strip_prefix('-') {
                return Ok((Number::UnnumberedPart, get_filename(r)?));
            }
            if rest.starts_with(|c: char| c.is_ascii_digit()) {
                let end = match rest.find('.') {
                    Some(e) => e,
                    None => return Err(err("found invalid part definition in the chapter list")),
                };
                let n: i64 = rest[..end].parse().map_err(|e: std::num::ParseIntError| err(&format!("error parsing part number: {}", e)))?;
                let f = rest.get(end + 2..).unwrap_or("");
                return Ok((Number::SpecifiedPart(n), get_filename(f)?));
            }
            let title = rest.trim();
            if title.is_empty() || !rest.starts_with(' ') {
                return Err(err("found invalid part definition in the chapter list"));
            }
            return Ok((Number::DefaultPart, format!("\u{0}{}", title)));
        }
        if line.starts_with(|c: char| c.is_ascii_digit()) {
            let end = match line.find('.') {
                Some(e) => e,
                None => return Err(err("found invalid chapter definition in the chapter list")),
            };
            let n: i64 = line[..end].parse().map_err(|e: std::num::ParseIntError| err(&format!("error parsing chapter number: {}", e)))?;
            let f = line.get(end + 2..).unwrap_or("");
            return Ok((Number::Specified(n), get_filename(f)?));
        }
        Err(err("found invalid chapter definition in the chapter list"))
    }

    pub fn add_chapter(&mut self, number: Number, file: &str) -> Result<(), BookError> {
        if file.is_empty() {
            return Ok(());
        }
        if let Some(title) = file.strip_prefix('\u{0}') {
            // part with a title only
            let mut content = vec![Token::Header(1, vec![Token::Str(title.to_string())])];
            self.clean_tokens(&mut content);
            self.chapters.push(Chapter { number, filename: String::new(), content });
            return Ok(());
        }
        let path = self.root.join(file);
        let text = match std::fs::read(&path) {
            Ok(b) => String::from_utf8_lossy(&b).to_string(),
            Err(_) => {
                return Err(BookError::new(format!("{}Could not find file '{}' for book chapter", self.prefix(), file)));
            }
        };
        self.add_chapter_from_source(number, file, &text)
    }

    pub fn add_chapter_from_source(&mut self, number: Number, file: &str, text: &str) -> Result<(), BookError> {
        let text = self.process_yaml_blocks(text);
        let mut content = parse_markdown(&text, &self.md_options());
        // files mean chapters
        let fmc = self.options.get_bool_opt("crowbook.files_mean_chapters");
        let numbered = matches!(number, Number::Default | Number::Specified(_));
        let insert = match fmc {
            Some(b) => b,
            None => numbered,
        };
        let starts_with_h1 = matches!(content.first(), Some(Token::Header(1, _)));
        if (insert || number.is_part()) && !starts_with_h1 {
            content.insert(0, Token::Header(1, vec![]));
        }
        self.clean_tokens(&mut content);
        self.chapters.push(Chapter { number, filename: file.to_string(), content });
        Ok(())
    }

    fn process_yaml_blocks(&mut self, text: &str) -> String {
        // YAML blocks: lines "---" ... "---" (only at start, or anywhere with input.yaml_blocks)
        if !self.options.get_bool("input.yaml_blocks") {
            return text.to_string();
        }
        let lines: Vec<&str> = text.lines().collect();
        let mut out: Vec<String> = Vec::new();
        let mut i = 0;
        while i < lines.len() {
            if lines[i].trim_end() == "---" && (i == 0 || lines[i - 1].trim().is_empty()) && i + 1 < lines.len() && !lines[i + 1].trim().is_empty() {
                // find end
                let mut j = i + 1;
                while j < lines.len() && lines[j].trim_end() != "---" && lines[j].trim_end() != "..." {
                    j += 1;
                }
                if j < lines.len() {
                    let block = lines[i + 1..j].join("\n");
                    if let Ok(docs) = yaml::load(&block) {
                        if let Some(Yaml::Hash(h)) = docs.first() {
                            for (k, v) in h.clone() {
                                if let Yaml::String(k) = k {
                                    self.set_yaml_option(&k, &v);
                                }
                            }
                            for _ in i..=j {
                                out.push(String::new());
                            }
                            i = j + 1;
                            continue;
                        }
                    }
                }
            }
            out.push(lines[i].to_string());
            i += 1;
        }
        out.join("\n")
    }

    pub fn clean_tokens(&self, tokens: &mut Vec<Token>) {
        let cleaner = self.cleaner();
        clean_rec(&cleaner, tokens);
    }

    /// Load a single markdown file (with optional YAML front matter)
    pub fn load_single(&mut self, path: &str) -> Result<(), BookError> {
        let p = PathBuf::from(path);
        let text = match std::fs::read(&p) {
            Ok(b) => String::from_utf8_lossy(&b).to_string(),
            Err(_) => return Err(BookError::new(format!("Could not find file '{}' for book", path))),
        };
        self.source_file = Some(path.to_string());
        self.root = p.parent().map(|x| x.to_path_buf()).unwrap_or_default();
        if self.root.as_os_str().is_empty() {
            self.root = PathBuf::from(".");
        }
        self.book_path = Some(p.clone());
        self.options.book_stem = p.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
        self.options.root = self.root.clone();
        // front matter
        let mut body = text.clone();
        let lines: Vec<&str> = text.lines().collect();
        if !lines.is_empty() && lines[0].trim_end() == "---" {
            let mut j = 1;
            while j < lines.len() && lines[j].trim_end() != "---" && lines[j].trim_end() != "..." {
                j += 1;
            }
            if j < lines.len() {
                let block = lines[1..j].join("\n");
                match yaml::load(&block) {
                    Ok(docs) => {
                        if let Some(Yaml::Hash(h)) = docs.first() {
                            for (k, v) in h.clone() {
                                if let Yaml::String(k) = k {
                                    self.set_yaml_option(&k, &v);
                                }
                            }
                        }
                    }
                    Err(e) => {
                        return Err(BookError::new(format!("{}Error parsing configuration file: YAML block was not valid YAML: {}", self.prefix(), e)));
                    }
                }
                let mut rest: Vec<String> = Vec::new();
                for _ in 0..=j {
                    rest.push(String::new());
                }
                for l in &lines[j + 1..] {
                    rest.push(l.to_string());
                }
                body = rest.join("\n");
            }
        }
        let fname = p.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
        self.add_chapter_from_source(Number::Default, &fname, &body)
    }

    pub fn metadata_tokens(&self, key: &str) -> Option<Vec<Token>> {
        let s = self.options.get_str(key)?;
        let mut toks = parse_inline(&s, &self.md_options());
        toks = merge_str(toks);
        self.clean_tokens(&mut toks);
        Some(toks)
    }

    pub fn get_opt_value(&self, key: &str) -> Option<OptValue> {
        self.options.get(key)
    }
}

fn clean_rec(cleaner: &Cleaner, tokens: &mut Vec<Token>) {
    for t in tokens.iter_mut() {
        match t {
            Token::Str(s) => {
                *s = cleaner.clean(s);
            }
            Token::Code(_) | Token::CodeBlock(..) => {}
            other => {
                if let Some(v) = other.inner_mut() {
                    clean_rec(cleaner, v);
                }
            }
        }
    }
}
