// Common HTML renderer
use crate::book::{Book, Number};
use crate::highlight;
use crate::lang;
use crate::template::{Context, Template, Value, HTML_SYNTAX};
use crate::token::Token;
use crate::toc::Toc;

pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
    out
}

pub fn escape_quotes_amp(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

/// Escape narrow non breaking spaces for HTML
pub fn escape_nb_spaces(s: &str) -> String {
    if !s.contains('\u{202f}') {
        return s.to_string();
    }
    let mut out = String::new();
    let mut word = String::new();
    let flush = |word: &mut String, out: &mut String| {
        if word.contains('\u{202f}') {
            out.push_str("<span class = \"nnbsp\">");
            out.push_str(&word.replace('\u{202f}', "&#160;"));
            out.push_str("</span>");
        } else {
            out.push_str(word);
        }
        word.clear();
    };
    for c in s.chars() {
        if c == ' ' || c == '\t' || c == '\n' {
            flush(&mut word, &mut out);
            out.push(c);
        } else {
            word.push(c);
        }
    }
    flush(&mut word, &mut out);
    out
}

pub fn to_roman(n: i64) -> String {
    if n <= 0 || n >= 4000 {
        return n.to_string();
    }
    let table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")];
    let mut n = n;
    let mut s = String::new();
    for (v, r) in table.iter() {
        while n >= *v {
            s.push_str(r);
            n -= v;
        }
    }
    s
}

#[derive(Clone, Copy, PartialEq)]
pub enum Flavor {
    Standalone,
    Epub,
    Dir,
}

pub struct HtmlRenderer<'a> {
    pub book: &'a Book,
    pub flavor: Flavor,
    pub current_chapter: [i64; 7],
    pub current_numbering: i64,
    pub current_part: bool,
    pub current_hide: bool,
    pub current_unnumbered_part: bool,
    pub part_number: i64,
    pub link_number: usize,
    pub para_number: usize,
    pub toc: Toc,
    pub footnotes: Vec<(String, String)>,
    pub chapter_index: usize,
    pub filenum: usize,
    pub escape_nb: bool,
    pub first_paragraph: bool,
    pub first_letter: bool,
    pub highlight: String,
    pub errors: Vec<String>,
    pub fatal: Option<String>,
    pub embed_images: bool,
    pub image_handler: Option<Box<dyn FnMut(&str) -> Result<String, String> + 'a>>,
    pub chapter_filenames: Vec<String>,
    pub link_target: Box<dyn Fn(usize) -> String + 'a>,
    pub in_toc_title: bool,
    pub side_notes: bool,
    pub num_depth: i64,
}

impl<'a> HtmlRenderer<'a> {
    pub fn new(book: &'a Book, flavor: Flavor) -> HtmlRenderer<'a> {
        let escape_nb = match flavor {
            Flavor::Epub => book.options.get_bool("epub.escape_nb_spaces"),
            _ => book.options.get_bool("html.escape_nb_spaces"),
        };
        let highlight = book.options.str_or("rendering.highlight", "syntect");
        HtmlRenderer {
            book,
            flavor,
            current_chapter: [0; 7],
            current_numbering: book.options.get_int("rendering.num_depth").unwrap_or(1),
            current_part: false,
            current_hide: false,
            current_unnumbered_part: false,
            part_number: 0,
            link_number: 0,
            para_number: 0,
            toc: Toc::new(),
            footnotes: Vec::new(),
            chapter_index: 0,
            filenum: 0,
            escape_nb,
            first_paragraph: true,
            first_letter: false,
            highlight,
            errors: Vec::new(),
            fatal: None,
            embed_images: false,
            image_handler: None,
            chapter_filenames: book.chapters.iter().map(|c| c.filename.clone()).collect(),
            link_target: Box::new(|i| format!("#chapter-{}", i)),
            in_toc_title: false,
            side_notes: book.options.get_bool("html.side_notes"),
            num_depth: book.options.get_int("rendering.num_depth").unwrap_or(1),
        }
    }

    pub fn lang(&self) -> String {
        self.book.lang()
    }

    /// Set state for a new chapter
    pub fn begin_chapter(&mut self, index: usize, number: &Number) {
        self.chapter_index = index;
        self.filenum = index;
        self.current_hide = false;
        self.current_part = false;
        self.current_unnumbered_part = false;
        let num_depth = self.num_depth;
        match number {
            Number::Unnumbered => self.current_numbering = 0,
            Number::Default => self.current_numbering = num_depth,
            Number::Specified(n) => {
                self.current_numbering = num_depth;
                self.current_chapter[1] = n - 1;
            }
            Number::Hidden => {
                self.current_numbering = 0;
                self.current_hide = true;
            }
            Number::DefaultPart | Number::UnnumberedPart | Number::SpecifiedPart(_) => {
                self.current_part = true;
                self.current_numbering = num_depth;
                if let Number::UnnumberedPart = number {
                    self.current_unnumbered_part = true;
                }
                if let Number::SpecifiedPart(n) = number {
                    self.part_number = n - 1;
                }
            }
        }
    }

    pub fn render_vec(&mut self, tokens: &[Token]) -> String {
        let mut s = String::new();
        for t in tokens {
            s.push_str(&self.render_token(t));
        }
        s
    }

    pub fn render_text(&self, s: &str) -> String {
        let e = escape_html(s);
        if self.escape_nb {
            escape_nb_spaces(&e)
        } else {
            e
        }
    }

    fn header_number_str(&self, level: usize) -> String {
        // e.g. "1.2." for level 2
        let mut parts = Vec::new();
        for i in 1..=level {
            parts.push(self.current_chapter[i].to_string());
        }
        format!("{}.", parts.join("."))
    }

    fn chapter_number_display(&self) -> String {
        let n = self.current_chapter[1];
        if self.book.options.get_bool("rendering.chapter.roman_numerals") {
            to_roman(n)
        } else {
            n.to_string()
        }
    }

    fn part_number_display(&self) -> String {
        let n = self.part_number;
        if self.book.options.get_bool("rendering.part.roman_numerals") {
            to_roman(n)
        } else {
            n.to_string()
        }
    }

    pub fn render_header(&mut self, level: i32, content: &[Token]) -> String {
        let level = level.max(1).min(6) as usize;
        self.link_number += 1;
        let link = self.link_number;
        let title = self.render_vec(content);
        if level == 1 && self.current_part {
            self.part_number += 1;
            if self.book.options.get_bool("rendering.part.reset_counter") {
                self.current_chapter[1] = 0;
            }
            for i in 2..7 {
                self.current_chapter[i] = 0;
            }
            let numbered = !self.current_unnumbered_part;
            let header = if numbered { self.book.options.get_str("rendering.part").unwrap_or_else(|| lang::get(&self.lang(), "part")) } else { String::new() };
            let number = if numbered { self.part_number_display() } else { String::new() };
            let mut ctx = Context::new();
            ctx.insert("header".into(), Value::Str(header));
            ctx.insert("number".into(), Value::Str(number.clone()));
            ctx.insert("link".into(), Value::Str(link.to_string()));
            ctx.insert("title".into(), Value::Str(title.clone()));
            ctx.insert("has_number".into(), Value::Bool(numbered));
            ctx.insert("has_title".into(), Value::Bool(!title.is_empty()));
            let tpl = self.book.options.str_or("html.part.template", "");
            let out = Template::compile(&tpl, &HTML_SYNTAX).and_then(|t| t.render(&ctx)).unwrap_or_default();
            // toc
            let toc_title = if numbered {
                let mut c2 = Context::new();
                c2.insert("number".into(), Value::Str(number));
                c2.insert("part_title".into(), Value::Str(title.clone()));
                let t = self.book.options.str_or("rendering.part.template", "");
                Template::compile(&t, &HTML_SYNTAX).and_then(|t| t.render(&c2)).unwrap_or_default()
            } else {
                format!(" {}", title)
            };
            let url = self.toc_link(link);
            self.toc.add(0, url, toc_title);
            // part is not a chapter for the purpose of numbering
            self.current_part = false;
            self.current_part_done = true;
            return out;
        }
        // update counters
        if self.current_numbering >= 1 || level > 1 {
            self.current_chapter[level] += 1;
            for i in (level + 1)..7 {
                self.current_chapter[i] = 0;
            }
        }
        if level == 1 {
            if self.current_hide {
                let url = self.toc_link(link);
                self.toc.add(1, url, title.clone());
                return format!("<h1 id = \"link-{}\"></h1>", link);
            }
            let has_number = self.current_numbering >= 1;
            let header = self.book.options.get_str("rendering.chapter").unwrap_or_else(|| lang::get(&self.lang(), "chapter"));
            let number = self.chapter_number_display();
            let mut ctx = Context::new();
            ctx.insert("header".into(), Value::Str(header));
            ctx.insert("number".into(), Value::Str(number.clone()));
            ctx.insert("link".into(), Value::Str(link.to_string()));
            ctx.insert("title".into(), Value::Str(title.clone()));
            ctx.insert("has_number".into(), Value::Bool(has_number));
            ctx.insert("has_title".into(), Value::Bool(!title.is_empty()));
            let tpl = self.book.options.str_or("html.chapter.template", "");
            let out = Template::compile(&tpl, &HTML_SYNTAX).and_then(|t| t.render(&ctx)).unwrap_or_default();
            let toc_title = if has_number {
                let mut c2 = Context::new();
                c2.insert("number".into(), Value::Str(number));
                c2.insert("chapter_title".into(), Value::Str(title.clone()));
                let t = self.book.options.str_or("rendering.chapter.template", "");
                Template::compile(&t, &HTML_SYNTAX).and_then(|t| t.render(&c2)).unwrap_or_default()
            } else {
                title.clone()
            };
            if self.num_depth >= 1 || true {
                let url = self.toc_link(link);
                if (level as i64) <= self.num_depth.max(1) {
                    self.toc.add(1, url, toc_title);
                }
            }
            out
        } else {
            let numbered = self.current_numbering >= level as i64;
            let full_title = if numbered { format!("{} {}", self.header_number_str(level), title) } else { title.clone() };
            if (level as i64) <= self.num_depth {
                let url = self.toc_link(link);
                self.toc.add(level as i32, url, full_title.clone());
            }
            format!("<h{} id = \"link-{}\">{}</h{}>\n", level, link, full_title, level)
        }
    }

    pub fn toc_link(&self, link: usize) -> String {
        match self.flavor {
            Flavor::Standalone => format!("#link-{}", link),
            Flavor::Epub => format!("chapter_{:03}.xhtml#link-{}", self.filenum, link),
            Flavor::Dir => format!("chapter_{:03}.html#link-{}", self.filenum, link),
        }
    }

    pub fn resolve_link(&mut self, url: &str) -> String {
        if url.contains("://") {
            return url.to_string();
        }
        let base = match url.find('#') {
            Some(p) => &url[..p],
            None => url,
        };
        let with_md = with_extension_md(url);
        for (i, f) in self.chapter_filenames.iter().enumerate() {
            if f.is_empty() {
                continue;
            }
            if f == url || f == &with_md || (!base.is_empty() && f == base) {
                return (self.link_target)(i);
            }
        }
        if !self.link_warned.contains(&url.to_string()) {
            crate::logger::warn(&format!("Resources: could not find an in-book match for link {} or {}", url, with_md));
        }
        url.to_string()
    }

    pub fn render_image_src(&mut self, url: &str) -> String {
        if url.contains("://") {
            return url.to_string();
        }
        if let Some(h) = self.image_handler.as_mut() {
            match h(url) {
                Ok(s) => return s,
                Err(e) => {
                    if self.fatal.is_none() {
                        self.fatal = Some(e);
                    }
                    return url.to_string();
                }
            }
        }
        url.to_string()
    }

    pub fn render_token(&mut self, token: &Token) -> String {
        match token {
            Token::Str(s) => self.render_text(s),
            Token::Paragraph(v) => {
                self.para_number += 1;
                let id = self.para_number;
                let mut class = String::new();
                let mut content;
                if self.first_paragraph {
                    self.first_paragraph = false;
                    if self.book.options.get_bool("rendering.initials") && !v.is_empty() {
                        if let Some((initial, rest)) = self.split_initial(v) {
                            content = format!("<span class = \"initial\">{}</span>{}", initial, rest);
                            class = " class = \"first-para\"".to_string();
                            return format!("<p id = \"para-{}\"{}>{}</p>\n", id, class, content);
                        }
                    }
                }
                content = self.render_vec(v);
                format!("<p id = \"para-{}\"{}>{}</p>\n", id, class, content)
            }
            Token::Header(level, v) => {
                if *level == 1 {
                    self.first_paragraph = true;
                }
                self.render_header(*level, v)
            }
            Token::Emphasis(v) => format!("<em>{}</em>", self.render_vec(v)),
            Token::Strong(v) => format!("<b>{}</b>", self.render_vec(v)),
            Token::Strikethrough(v) => format!("<del>{}</del>", self.render_vec(v)),
            Token::Superscript(v) => format!("<sup>{}</sup>", self.render_vec(v)),
            Token::Subscript(v) => format!("<sub>{}</sub>", self.render_vec(v)),
            Token::Code(s) => format!("<code>{}</code>", self.render_text(s)),
            Token::BlockQuote(v) => format!("<blockquote>{}</blockquote>\n", self.render_vec(v)),
            Token::CodeBlock(lang, code) => self.render_code_block(lang, code),
            Token::Rule => "<p class = \"rule\">***</p>\n".to_string(),
            Token::SoftBreak => " ".to_string(),
            Token::HardBreak => "<br />\n".to_string(),
            Token::List(v) => format!("<ul>\n{}</ul>\n", self.render_vec(v)),
            Token::OrderedList(n, v) => {
                let start = if *n != 1 { format!(" start = \"{}\"", n) } else { String::new() };
                format!("<ol{}>\n{}</ol>\n", start, self.render_vec(v))
            }
            Token::Item(v) => format!("<li>{}</li>\n", self.render_vec(v)),
            Token::TaskItem(checked, v) => {
                let c = if *checked { "checked = \"\"" } else { "" };
                format!("<input type = \"checkbox\" disabled = \"\" {}/>{}", c, self.render_vec(v))
            }
            Token::DescriptionList(v) => format!("<dl>\n{}\n</dl>", self.render_vec(v)),
            Token::DescriptionItem(v) => self.render_vec(v),
            Token::DescriptionTerm(v) => format!("<dt>{}</dt>\n", self.render_vec(v)),
            Token::DescriptionDetails(v) => format!("<dd>{}</dd>\n", self.render_vec(v)),
            Token::Table(_, v) => format!("<div class = \"table\">\n    <table>\n{}\n    </table>\n</div>\n", self.render_vec(v)),
            Token::TableHead(v) => {
                let mut s = String::from("<tr>\n");
                for c in v {
                    if let Token::TableCell(inner) = c {
                        s.push_str(&format!("<th>{}</th>", self.render_vec(inner)));
                    }
                }
                s.push_str("</tr>\n");
                s
            }
            Token::TableRow(v) => format!("<tr>\n{}</tr>\n", self.render_vec(v)),
            Token::TableCell(v) => format!("<td>{}</td>", self.render_vec(v)),
            Token::Link(url, title, v) => {
                let url = self.resolve_link(url);
                let t = if title.is_empty() { String::new() } else { format!(" title = \"{}\"", title) };
                format!("<a href = \"{}\"{}>{}</a>", escape_quotes_amp(&url), t, self.render_vec(v))
            }
            Token::Image(url, title, v) => {
                let src = self.render_image_src(url);
                format!("<img src = \"{}\" title = \"{}\" alt = \"{}\" />", src, title, self.render_vec(v))
            }
            Token::StandaloneImage(url, title, v) => {
                let src = self.render_image_src(url);
                format!("<div class = \"image\">\n  <img src = \"{}\" title = \"{}\" alt = \"{}\" />\n</div>", src, title, self.render_vec(v))
            }
            Token::FootnoteReference(name) => self.render_footnote_reference(name),
            Token::FootnoteDefinition(name, v) => {
                let content = self.render_vec(v);
                self.add_footnote(name, content);
                String::new()
            }
            Token::RawBlock(s) => self.render_text(s),
        }
    }

    fn split_initial(&mut self, v: &[Token]) -> Option<(String, String)> {
        if let Some(Token::Str(s)) = v.first() {
            let mut chars = s.chars();
            let first = chars.next()?;
            let rest: String = chars.collect();
            let initial = self.render_text(&first.to_string());
            let mut out = self.render_text(&rest);
            out.push_str(&self.render_vec(&v[1..]));
            return Some((initial, out));
        }
        None
    }

    pub fn note_id(&self, name: &str) -> String {
        match self.flavor {
            Flavor::Epub => name.to_string(),
            _ => format!("{}-{}", self.chapter_index + 1, name),
        }
    }

    pub fn render_footnote_reference(&mut self, name: &str) -> String {
        let id = self.note_id(name);
        match self.flavor {
            Flavor::Epub => format!("<a epub:type = \"noteref\" href = \"#note-dest-{}\"><sup id = \"note-source-{}\">[{}]</sup></a>", id, id, name),
            _ => format!("<a class = \"footnote_reference\" href = \"#note-dest-{}\" id = \"note-source-{}\"><sup>[{}]</sup></a>", id, id, name),
        }
    }

    pub fn add_footnote(&mut self, name: &str, content: String) {
        let id = self.note_id(name);
        let number = match self.flavor {
            Flavor::Epub => format!("<a href = \"#note-source-{}\">[{}]</a>", id, name),
            _ => format!("<a rel = \"footnote\" href = \"#note-source-{}\">[{}]</a>", id, name),
        };
        let note = match self.flavor {
            Flavor::Epub => format!("<aside epub:type = \"footnote\" id = \"note-dest-{}\">{}</aside>", id, content),
            _ => format!("<aside class = \"footnote\" id = \"note-dest-{}\">{}</aside>", id, content),
        };
        self.footnotes.push((number, note));
    }

    pub fn render_notes(&mut self) -> String {
        if self.footnotes.is_empty() {
            return String::new();
        }
        let notes = std::mem::take(&mut self.footnotes);
        let epub_attr = if self.flavor == Flavor::Epub { " epub:type=\"footnotes\"" } else { " " };
        let mut s = format!("<section class = \"notes\"{}>\n <h2 class = \"notes\">{}</h2>\n<table class = \"notes\">\n", epub_attr, lang::get(&self.lang(), "notes"));
        for (number, note) in notes {
            s.push_str(&format!(
                "<tr class = \"notes\">\n <td class = \"note-number\">\n  <p class = \"note-number\">\n  {}\n</p>\n\n </td>\n <td class = \"note\">\n  {}\n  </td>\n</tr>\n",
                number, note
            ));
        }
        s.push_str("</table>\n</section>\n");
        s
    }

    pub fn render_code_block(&mut self, lang: &str, code: &str) -> String {
        match self.highlight.as_str() {
            "syntect" => {
                let theme = self.theme_option();
                format!("<pre>{}</pre>", highlight::highlight_html(code, lang, &theme))
            }
            "highlight.js" => {
                let l = lang.split_whitespace().next().unwrap_or("");
                if l.is_empty() {
                    format!("<pre><code>{}</code></pre>\n", self.render_text(code))
                } else {
                    format!("<pre><code class = \"language-{}\">{}</code></pre>\n", l, self.render_text(code))
                }
            }
            _ => format!("<pre><code>{}</code></pre>\n", self.render_text(code)),
        }
    }

    fn theme_option(&self) -> String {
        let key = match self.flavor {
            Flavor::Epub => "epub.highlight.theme",
            _ => "html.highlight.theme",
        };
        self.book.options.get_str(key).unwrap_or_else(|| self.book.options.str_or("rendering.highlight.theme", "InspiredGitHub"))
    }
}

pub fn with_extension_md(url: &str) -> String {
    // emulate Path::with_extension("md")
    if url.is_empty() {
        return String::new();
    }
    let (dir, file) = match url.rfind('/') {
        Some(p) => (&url[..p + 1], &url[p + 1..]),
        None => ("", url),
    };
    if file.is_empty() || file == "." || file == ".." {
        return url.to_string();
    }
    let stem = match file.rfind('.') {
        Some(0) | None => file,
        Some(p) => &file[..p],
    };
    format!("{}{}.md", dir, stem)
}
