// Syntax highlighting (approximation of syntect with InspiredGitHub theme)
pub fn escape_syntect(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '\'' => out.push_str("&#39;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

pub const FG: (u8, u8, u8) = (0x32, 0x32, 0x32);

pub fn highlight_html(code: &str, _lang: &str, _theme: &str) -> String {
    let mut out = String::new();
    for line in code.split('\n') {
        if !line.is_empty() {
            out.push_str(&format!("<span style=\"color:#{:02x}{:02x}{:02x};\">{}</span>", FG.0, FG.1, FG.2, escape_syntect(line)));
        }
        out.push('\n');
    }
    out
}

pub fn rgb_f32(c: u8) -> String {
    let f = c as f32 / 255.0;
    format!("{}", f)
}

/// Returns list of lines; each line is a list of (r,g,b,bold,italic,text) regions
pub fn highlight_regions(code: &str, _lang: &str) -> Vec<Vec<((u8, u8, u8), bool, bool, String)>> {
    let mut out = Vec::new();
    for line in code.split('\n') {
        let mut regions = Vec::new();
        if !line.is_empty() {
            regions.push((FG, false, false, line.to_string()));
        }
        out.push(regions);
    }
    out
}
