// Standalone HTML renderer
use crate::book::{source_prefix, Book};
use crate::html::{Flavor, HtmlRenderer};
use crate::lang;
use crate::resources::*;
use crate::template::{Context, Template, Value, HTML_SYNTAX};

pub fn get_template(book: &Book, key: &str, default: &str) -> Result<String, String> {
    match book.options.get_str(key) {
        Some(p) => {
            let base = book.options.str_or("resources.base_path.templates", ".");
            let rbase = book.options.get_str("resources.base_path");
            let path = match rbase {
                Some(b) => book.root.join(&b).join(&p),
                None => book.root.join(&base).join(&p),
            };
            let display = std::path::Path::new(&base).join(&p).to_string_lossy().to_string();
            match std::fs::read_to_string(&path) {
                Ok(s) => Ok(s),
                Err(_) => Err(format!("{}Could not find file '{}' for template '{}'", source_prefix(&book.source_file, None), display, key)),
            }
        }
        None => Ok(default.to_string()),
    }
}

pub fn render_tpl(src: &str, ctx: &Context) -> Result<String, String> {
    let t = Template::compile(src, &HTML_SYNTAX).map_err(|e| format!("Error compiling template: {}{}", e.msg, e.detail))?;
    t.render(ctx).map_err(|e| format!("Error compiling template: {}{}", e.msg, e.detail))
}

pub fn image_path(book: &Book, url: &str) -> (std::path::PathBuf, String) {
    let base = match book.options.get_str("resources.base_path") {
        Some(b) => b,
        None => book.options.str_or("resources.base_path.images", "."),
    };
    let display = std::path::Path::new(&base).join(url).to_string_lossy().to_string();
    (book.root.join(&base).join(url), display)
}

pub fn json_data(book: &Book) -> String {
    let opt = |key: &str, name: &str| match book.options.get_str(key) {
        Some(v) => format!("\"{}\": \"{}\",", name, v),
        None => String::new(),
    };
    format!(
        "\n<script type = 'application/ld+json'>\n{{\n    \"@context\": \"http://schema.org/\",\n    \"@type\": \"Book\",\n    \"author\": \"{}\",\n    \"name\": \"{}\",\n    {}\n    {}\n    {}\n    {}\n    {}\n    \"inLanguage\": \"{}\"\n}}\n</script>",
        book.options.str_or("author", ""),
        book.options.str_or("title", ""),
        opt("version", "version"),
        opt("subtitle", "alternateName"),
        opt("subject", "keywords"),
        opt("license", "license"),
        opt("description", "about"),
        book.lang()
    )
}

pub fn render_css(book: &Book, key_css: &str, default_css: &str, key_add: &str, with_colors: bool) -> Result<String, String> {
    let css_src = get_template(book, key_css, default_css)?;
    let mut ctx = Context::new();
    ctx.insert("lang".into(), Value::Str(book.lang()));
    ctx.insert("additional_code".into(), Value::Str(book.options.str_or(key_add, "")));
    if with_colors {
        let colors = get_template(book, "html.css.colors", HTML_CSS_COLORS)?;
        ctx.insert("colors".into(), Value::Str(colors));
    }
    render_tpl(&css_src, &ctx)
}

/// Render metadata (title, author, ...) as HTML using a renderer
pub fn meta_html(r: &mut HtmlRenderer, key: &str) -> Option<String> {
    let toks = r.book.metadata_tokens(key)?;
    Some(r.render_vec(&toks))
}

pub fn render_standalone(book: &Book) -> Result<String, String> {
    let mut r = HtmlRenderer::new(book, Flavor::Standalone);
    let root = book.root.clone();
    r.image_handler = Some(Box::new(move |url: &str| {
        let (path, display) = image_path(book, url);
        let _ = &root;
        match std::fs::read(&path) {
            Ok(data) => Ok(data_uri(url, &data)),
            Err(_) => Err(format!("Could not find file '{}' for image", display)),
        }
    }));
    let one_chapter = book.options.get_bool("html.standalone.one_chapter");
    // render chapters
    let mut content = String::new();
    let mut fatal: Option<String> = None;
    for (i, ch) in book.chapters.iter().enumerate() {
        r.begin_chapter(i, &ch.number);
        let body = r.render_vec(&ch.content);
        let notes = r.render_notes();
        if let Some(e) = r.fatal.take() {
            if fatal.is_none() {
                fatal = Some(format!("{}: {}", ch.filename, e));
            }
        }
        content.push_str(&format!("<div id = \"chapter-{}\" class = \"chapter\">\n  {}{}\n</div>", i, body, notes));
    }
    if let Some(f) = fatal {
        return Err(f);
    }
    // inline toc
    let toc_html = r.toc.render("ul");
    let has_toc = r.toc.elements.len() > 1 || r.toc.elements.iter().any(|e| !e.children.is_empty());
    let mut ctx = Context::new();
    let lang = book.lang();
    ctx.insert("lang".into(), Value::Str(lang.clone()));
    ctx.insert("author_raw".into(), Value::Str(book.options.str_or("author", "")));
    ctx.insert("title_raw".into(), Value::Str(book.options.str_or("title", "")));
    let favicon = match book.options.get_str("html.icon") {
        Some(icon) => {
            let (path, display) = image_path(book, &icon);
            match std::fs::read(&path) {
                Ok(d) => format!("<link rel = \"icon\" href = \"{}\">", data_uri(&icon, &d)),
                Err(_) => return Err(format!("Could not find file '{}' for icon", display)),
            }
        }
        None => String::new(),
    };
    ctx.insert("favicon".into(), Value::Str(favicon));
    let style = render_css(book, "html.css", HTML_CSS, "html.css.add", true)?;
    ctx.insert("style".into(), Value::Str(style));
    let print_style = get_template(book, "html.css.print", HTML_CSS_PRINT)?;
    ctx.insert("print_style".into(), Value::Str(print_style));
    let highlight_code = book.options.str_or("rendering.highlight", "syntect") == "highlight.js";
    ctx.insert("highlight_code".into(), Value::Bool(highlight_code));
    if highlight_code {
        let css = get_template(book, "html.highlight.css", HTML_HIGHLIGHT_CSS)?;
        let js = get_template(book, "html.highlight.js", HTML_HIGHLIGHT_JS)?;
        ctx.insert("highlight_css".into(), Value::Str(css));
        ctx.insert("highlight_js".into(), Value::Str(format!("data:text/javascript;base64,{}", base64_nopad(js.as_bytes()))));
    }
    // script
    let common = get_template(book, "html.js", HTML_JS)?;
    let js_src = get_template(book, "html.standalone.js", HTML_STANDALONE_JS)?;
    let mut jctx = Context::new();
    jctx.insert("common_script".into(), Value::Str(common));
    jctx.insert("one_chapter".into(), Value::Bool(one_chapter));
    jctx.insert("book_svg".into(), Value::Str(format!("data:image/svg+xml;base64,{}", base64_nopad(BOOK_SVG))));
    jctx.insert("pages_svg".into(), Value::Str(format!("data:image/svg+xml;base64,{}", base64_nopad(PAGES_SVG))));
    jctx.insert("loc_display_all".into(), Value::Str(lang::get(&lang, "display_all")));
    jctx.insert("loc_display_one".into(), Value::Str(lang::get(&lang, "display_one")));
    let script = render_tpl(&js_src, &jctx)?;
    ctx.insert("script".into(), Value::Str(script));
    ctx.insert("json_data".into(), Value::Str(json_data(book)));
    ctx.insert("has_toc".into(), Value::Bool(has_toc));
    ctx.insert("one_chapter".into(), Value::Bool(one_chapter));
    ctx.insert("loc_display_all".into(), Value::Str(lang::get(&lang, "display_all")));
    ctx.insert("loc_display_one".into(), Value::Str(lang::get(&lang, "display_one")));
    ctx.insert("book_svg".into(), Value::Str(format!("data:image/svg+xml;base64,{}", base64_nopad(BOOK_SVG))));
    ctx.insert("pages_svg".into(), Value::Str(format!("data:image/svg+xml;base64,{}", base64_nopad(PAGES_SVG))));
    ctx.insert("menu_svg".into(), Value::Str(format!("data:image/svg+xml;base64,{}", base64_nopad(MENU_SVG))));
    ctx.insert("loc_toc".into(), Value::Str(lang::get(&lang, "toc")));
    ctx.insert("toc".into(), Value::Str(toc_html));
    // metadata
    let title = meta_html(&mut r, "title").unwrap_or_default();
    let author = meta_html(&mut r, "author").unwrap_or_default();
    ctx.insert("title".into(), Value::Str(title));
    ctx.insert("author".into(), Value::Str(author));
    let subtitle = meta_html(&mut r, "subtitle");
    ctx.insert("has_subtitle".into(), Value::Bool(subtitle.is_some()));
    ctx.insert("subtitle".into(), Value::Str(subtitle.unwrap_or_default()));
    let autograph = meta_html(&mut r, "autograph");
    ctx.insert("has_autograph".into(), Value::Bool(autograph.is_some()));
    ctx.insert("autograph".into(), Value::Str(autograph.unwrap_or_default()));
    // header & footer
    let footer = match book.options.get_str("html.footer") {
        Some(f) => {
            let mut toks = crate::parser::parse_markdown(&f, &book.md_options());
            book.clean_tokens(&mut toks);
            format!("<footer id = \"footer\">{}</footer>", r.render_vec(&toks))
        }
        None => String::new(),
    };
    let header = match book.options.get_str("html.header") {
        Some(f) => {
            let mut toks = crate::parser::parse_markdown(&f, &book.md_options());
            book.clean_tokens(&mut toks);
            format!("<div id = \"top\">{}</div>", r.render_vec(&toks))
        }
        None => String::new(),
    };
    ctx.insert("footer".into(), Value::Str(footer));
    ctx.insert("header".into(), Value::Str(header));
    ctx.insert("content".into(), Value::Str(content));
    let tpl = get_template(book, "html.standalone.template", HTML_STANDALONE_TEMPLATE)?;
    render_tpl(&tpl, &ctx)
}
EOF
