    ctx.insert("subtitle".into(), Value::Str(subtitle.unwrap_or_default()));
    let autograph = meta_html(&mut r, "autograph");
    ctx.insert("has_autograph".into(), Value::Bool(autograph.is_some()));
    ctx.insert("autograph".into(), Value::Str(autograph.unwrap_or_default()));
    // header & footer
    let footer = match book.options.get_str("html.footer") {
        Some(f) => {
            let mut toks = crate::parser::parse_markdown(&f, &book.md_options());
            book.clean_tokens(&mut toks);
            format!("<footer id = \"footer\">{}</footer>", r.render_vec(&toks))
        }
        None => String::new(),
    };
    let header = match book.options.get_str("html.header") {
        Some(f) => {
            let mut toks = crate::parser::parse_markdown(&f, &book.md_options());
            book.clean_tokens(&mut toks);
            format!("<div id = \"top\">{}</div>", r.render_vec(&toks))
        }
        None => String::new(),
