fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let search = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_m = vec![false; a.len()];
    let mut b_m = vec![false; b.len()];
    let mut matches = 0.0;
    for i in 0..a.len() {
        let lo = i.saturating_sub(search);
        let hi = (i + search + 1).min(b.len());
        for j in lo..hi {
            if !b_m[j] && a[i] == b[j] {
                a_m[i] = true;
                b_m[j] = true;
                matches += 1.0;
                break;
            }
        }
    }
    if matches == 0.0 {
        return 0.0;
    }
    let mut t = 0.0;
    let mut k = 0;
    for i in 0..a.len() {
        if a_m[i] {
            while !b_m[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1.0;
            }
            k += 1;
        }
    }
    let t = t / 2.0;
    (matches / a.len() as f64 + matches / b.len() as f64 + (matches - t) / matches) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count().min(4) as f64;
    j + 0.1 * prefix * (1.0 - j)
}

struct State {
    used: Vec<Id>,
    book_given: bool,
}

impl State {
    fn usage(&self, extra: &[Id], required: &[Id]) -> String {
        let mut ids: Vec<Id> = Vec::new();
        for r in required {
            ids.push(*r);
        }
        for u in &self.used {
            if !ids.contains(u) {
                ids.push(*u);
            }
        }
        for e in extra {
            if !ids.contains(e) {
                ids.push(*e);
            }
        }
        if ids.is_empty() && !self.book_given {
            return format!("Usage: {} [OPTIONS] [BOOK]", bin_name());
        }
        let mut s = format!("Usage: {}", bin_name());
        for i in ids {
            s.push(' ');
            s.push_str(def(i).display);
        }
        s.push_str(if self.book_given { " <BOOK>" } else { " [BOOK]" });
        s
    }
}

fn generic_usage() -> String {
    format!("Usage: {} [OPTIONS] [BOOK]", bin_name())
}

pub fn parse() -> Args {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut args = Args::default();
    let mut st = State { used: Vec::new(), book_given: false };
    let mut i = 0;
    let mut only_positional = false;

    let possible = "  [possible values: epub, pdf, html, tex, odt, html.dir]\n";

    while i < argv.len() {
        let a = argv[i].clone();
        i += 1;
        if only_positional || a == "-" || !a.starts_with('-') {
            if a == "--" && !only_positional {
                only_positional = true;
                continue;
            }
            if st.book_given {
                exit_error(&format!("error: unexpected argument '{}' found\n\n{}\n\nFor more information, try '--help'.\n", a, generic_usage()));
            }
            args.book = Some(a);
            st.book_given = true;
            continue;
        }
        if a == "--" {
            only_positional = true;
            continue;
        }
        // determine arg and inline value
        let (d, inline_val): (&ArgDef, Option<String>) = if let Some(long) = a.strip_prefix("--") {
            let (name, val) = match long.find('=') {
                Some(p) => (&long[..p], Some(long[p + 1..].to_string())),
                None => (long, None),
            };
            match DEFS.iter().find(|d| d.long == name) {
                Some(d) => (d, val),
                None => {
                    // suggestion
                    let mut best: Option<(&ArgDef, f64)> = None;
                    for d in DEFS {
                        let score = jaro_winkler(name, d.long);
                        if score > 0.7 && best.map(|b| score > b.1).unwrap_or(true) {
                            best = Some((d, score));
                        }
                    }
                    match best {
                        Some((d, _)) => {
                            let usage = st.usage(&[d.id], &[]);
                            exit_error(&format!(
                                "error: unexpected argument '--{}' found\n\n  tip: a similar argument exists: '--{}'\n\n{}\n\nFor more information, try '--help'.\n",
                                name, d.long, usage
                            ));
                        }
                        None => {
                            let usage = st.usage(&[], &[]);
                            exit_error(&format!(
                                "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\n\nFor more information, try '--help'.\n",
                                a, a, a, usage
                            ));
                        }
                    }
                }
            }
        } else {
            // short cluster
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0;
            let mut found: Option<(&ArgDef, Option<String>)> = None;
            while k < chars.len() {
                let c = chars[k];
                let d = match DEFS.iter().find(|d| d.short == Some(c)) {
                    Some(d) => d,
                    None => {
                        exit_error(&format!(
                            "error: unexpected argument '-{}' found\n\n  tip: to pass '-{}' as a value, use '-- -{}'\n\n{}\n\nFor more information, try '--help'.\n",
                            c, c, c, generic_usage()
                        ));
                    }
                };
                if d.takes > 0 {
                    let rest: String = chars[k + 1..].iter().collect();
                    let val = if rest.is_empty() {
                        None
                    } else if let Some(r) = rest.strip_prefix('=') {
                        Some(r.to_string())
                    } else {
                        Some(rest)
                    };
                    found = Some((d, val));
                    break;
                }
                // flag
                handle_flag(d, &mut args, &mut st);
                k += 1;
            }
            match found {
                Some(x) => x,
                None => continue,
            }
        };
        if d.takes == 0 {
            if let Some(v) = inline_val {
                let usage = st.usage(&[d.id], &[]);
                exit_error(&format!(
                    "error: unexpected value '{}' for '--{}' found; no more were expected\n\n{}\n\nFor more information, try '--help'.\n",
                    v, d.long, usage
                ));
            }
            handle_flag(d, &mut args, &mut st);
            continue;
        }
        // option with values
        if st.used.contains(&d.id) {
            exit_error(&format!("error: the argument '{}' cannot be used multiple times\n\n{}\n\nFor more information, try '--help'.\n", d.display, generic_usage()));
        }
        let mut values: Vec<String> = Vec::new();
        if let Some(v) = inline_val {
            values.push(v);
        }
        let is_value = |s: &str| !(s.starts_with('-') && s.len() > 1);
        if d.takes == 1 {
            if values.is_empty() {
                if i < argv.len() && is_value(&argv[i]) {
                    values.push(argv[i].clone());
                    i += 1;
                }
            }
        } else {
            while i < argv.len() && is_value(&argv[i]) {
                values.push(argv[i].clone());
                i += 1;
            }
        }
        if values.is_empty() || (d.id == Id::To && values[0].is_empty()) {
            let extra = if d.id == Id::To { possible } else { "" };
            exit_error(&format!("error: a value is required for '{}' but none was supplied\n{}\nFor more information, try '--help'.\n", d.display, extra));
        }
        if d.takes == 3 && values.len() < 2 {
            exit_error(&format!(
                "error: 2 values required by '{}'; only {} was provided\n\n{}\n\nFor more information, try '--help'.\n",
                d.display,
                values.len(),
                generic_usage()
            ));
        }
        st.used.push(d.id);
        match d.id {
            Id::Create => args.create = Some(values),
            Id::Output => args.output = Some(values[0].clone()),
            Id::To => {
                let v = &values[0];
                if !FORMATS.contains(&v.as_str()) {
                    let mut tip = String::new();
                    let mut best: Option<(&str, f64)> = None;
                    for f in FORMATS {
                        let score = jaro_winkler(v, f);
                        if score > 0.7 && best.map(|b| score > b.1).unwrap_or(true) {
                            best = Some((f, score));
                        }
                    }
                    if let Some((f, _)) = best {
                        tip = format!("\n  tip: a similar value exists: '{}'\n", f);
                    }
                    exit_error(&format!("error: invalid value '{}' for '--to <to>'\n{}{}\nFor more information, try '--help'.\n", v, possible, tip));
                }
                args.to = Some(v.clone());
            }
            Id::Set => args.set = Some(values),
            Id::Lang => args.lang = Some(values[0].clone()),
            Id::PrintTemplate => args.print_template = Some(values[0].clone()),
            _ => {}
        }
    }
    // validation: conflicts
    for (idx, u) in st.used.iter().enumerate() {
        let conflict = match u {
            Id::Quiet => Some(Id::Verbose),
            Id::Verbose => Some(Id::Quiet),
            _ => None,
        };
        if let Some(c) = conflict {
            if st.used.contains(&c) {
                let _ = idx;
                let others: Vec<Id> = st.used.iter().cloned().filter(|x| *x != c).collect();
                let st2 = State { used: others, book_given: st.book_given };
                exit_error(&format!(
                    "error: the argument '{}' cannot be used with '{}'\n\n{}\n\nFor more information, try '--help'.\n",
                    def(*u).display,
                    def(c).display,
                    st2.usage(&[], &[])
                ));
            }
        }
    }
    // requires
    if st.used.contains(&Id::Output) && !st.used.contains(&Id::To) {
        exit_error(&format!(
            "error: the following required arguments were not provided:\n  --to <to>\n\n{}\n\nFor more information, try '--help'.\n",
            st.usage(&[], &[Id::To])
        ));
    }
    args
}

fn handle_flag(d: &ArgDef, args: &mut Args, st: &mut State) {
    match d.id {
        Id::Help => {
            let s = HELP.replace("executable [OPTIONS]", &format!("{} [OPTIONS]", bin_name()));
            let _ = std::io::stdout().write_all(s.as_bytes());
            std::process::exit(0);
        }
        Id::Version => {
            println!("crowbook 0.17.0");
            std::process::exit(0);
        }
        _ => {}
    }
    if st.used.contains(&d.id) {
        exit_error(&format!("error: the argument '{}' cannot be used multiple times\n\n{}\n\nFor more information, try '--help'.\n", d.display, generic_usage()));
    }
    st.used.push(d.id);
    match d.id {
        Id::ForceEmoji => args.force_emoji = true,
        Id::Single => args.single = true,
        Id::NoFancy => args.no_fancy = true,
        Id::Verbose => args.verbose = true,
        Id::Autograph => args.autograph = true,
        Id::Quiet => args.quiet = true,
        Id::ListOptions => args.list_options = true,
        Id::Stats => args.stats = true,
        _ => {}
    }
}
EOF
echo ok"}

