// Rendering dispatch and misc commands
use crate::book::Book;
use crate::cli::Args;
use crate::logger;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

static RT_LANG: Mutex<String> = Mutex::new(String::new());

pub fn set_runtime_lang(l: &str) {
    *RT_LANG.lock().unwrap() = l.to_string();
}

/// Translate a crowbook message to the runtime language if needed
pub fn tr(msg: &str) -> String {
    let l = RT_LANG.lock().unwrap().clone();
    if !l.to_lowercase().starts_with("fr") {
        return msg.to_string();
    }
    // a few known messages
    if let Some(rest) = msg.strip_prefix("Could not find file '") {
        if let Some(p) = rest.find("' for book") {
            let f = &rest[..p];
            let tail = &rest[p + "' for book".len()..];
            return format!("Impossible de trouver le fichier '{}' pour book{}", f, tail);
        }
    }
    msg.to_string()
}

pub fn create_book(args: &Args, files: &[String]) {
    let mut out = String::new();
    if let Some(set) = &args.set {
        let mut b = Book::new();
        for pair in set.chunks(2) {
            if pair.len() < 2 {
                break;
            }
            let y = match crate::yaml::load(&pair[1]) {
                Ok(d) => d.into_iter().next().unwrap_or(crate::yaml::Yaml::Null),
                Err(_) => crate::yaml::Yaml::String(pair[1].clone()),
            };
            let mut w = Vec::new();
            if let Err(e) = b.options.set_yaml(&pair[0], &y, &mut w) {
                logger::print_error(&format!("Error in setting key {}: Error converting BookOption: {}", pair[0], e));
                return;
            }
            out.push_str(&format!("{}: {}\n", pair[0], pair[1]));
        }
    } else {
        out.push_str("\"author: Your name\"\n\"title: Your title\"\n\"lang: en\"\n\n\"## Output formats\"\n\n\"# Uncomment and fill to generate files\"\n\"# output.html: some_file.html\"\n\"# output.epub: some_file.epub\"\n\"# output.pdf: some_file.pdf\"\n\n\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"\n\"# output: [pdf, epub, html]\"\n\n\"# Uncomment and fill to set cover image (for EPUB)\"\n\"# cover: some_cover.png\"\n");
    }
    out.push_str("\n## List of chapters\n");
    for f in files {
        out.push_str(&format!("+ {}\n", f));
    }
    match &args.book {
        Some(b) => {
            if Path::new(b).exists() {
                logger::print_error(&format!("Could not create file {}: it already exists!", b));
                return;
            }
            match std::fs::write(b, out.as_bytes()) {
                Ok(_) => println!("Created {}, now you'll have to complete it!", b),
                Err(e) => logger::print_error(&format!("could not create file {}: {}", b, e)),
            }
        }
        None => {
            print!("{}", out);
            let _ = std::io::stdout().flush();
        }
    }
}

pub fn ask_autograph(book: &mut Book) {
    println!("Enter an autograph for this book (end with Ctrl-D):");
    let mut s = String::new();
    let _ = std::io::Read::read_to_string(&mut std::io::stdin(), &mut s);
    book.options.values.insert("autograph".into(), crate::options::OptValue::Str(s));
}

fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                if !out.pop() {
                    out.push("..");
                }
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}

/// Display a path relative to current dir
pub fn display_path(p: &Path) -> String {
    let cwd = std::env::current_dir().unwrap_or_default();
    let abs = if p.is_absolute() { normalize(p) } else { normalize(&cwd.join(p)) };
    let cwd = normalize(&cwd);
    let a: Vec<_> = abs.components().collect();
    let b: Vec<_> = cwd.components().collect();
    let mut i = 0;
    while i < a.len() && i < b.len() && a[i] == b[i] {
        i += 1;
    }
    let mut rel = PathBuf::new();
    for _ in i..b.len() {
        rel.push("..");
    }
    for c in &a[i..] {
        rel.push(c.as_os_str());
    }
    rel.to_string_lossy().to_string()
}

fn format_name(fmt: &str) -> &'static str {
    match fmt {
        "html" => "HTML (standalone page)",
        "tex" => "LaTeX",
        "pdf" => "PDF",
        "epub" => "EPUB",
        "html.dir" => "HTML (multiple pages)",
        "odt" => "ODT",
        _ => "",
    }
}

/// Render a format to bytes
pub fn render_bytes(book: &Book, fmt: &str) -> Result<Vec<u8>, String> {
    match fmt {
        "html" => crate::html_single::render_standalone(book).map(|s| s.into_bytes()),
        "tex" => crate::latex::render_latex(book).map(|s| s.into_bytes()),
        "epub" => crate::epub::render_epub(book),
        "pdf" => crate::latex::render_pdf(book),
        _ => Err(format!("unknown format {}", fmt)),
    }
}

pub fn render_format(book: &Book, fmt: &str, output: Option<&str>) {
    if fmt == "odt" {
        logger::print_error(&format!("unknown format {}", fmt));
        return;
    }
    let target: Option<PathBuf> = match output {
        Some("-") => None,
        Some(o) => Some(PathBuf::from(o)),
        None => book.options.get_str(&format!("output.{}", fmt)).map(|p| book.root.join(book.options.str_or("output.base_path", "")).join(p)),
    };
    if fmt == "html.dir" {
        match target {
            None => logger::print_error("Error during rendering: can only render HTML directory to a path, not to a stream"),
            Some(t) => {
                let _ = std::fs::create_dir_all(&t);
                match crate::epub::render_html_dir(book, &t, true) {
                    Ok(()) => logger::info(&format!("Succesfully generated {}: {}", format_name(fmt), display_path(&t))),
                    Err(e) => logger::print_error(&e),
                }
            }
        }
        return;
    }
    match render_bytes(book, fmt) {
        Ok(data) => match target {
            None => {
                let _ = std::io::stdout().write_all(&data);
                let _ = std::io::stdout().flush();
                logger::info(&format!("Succesfully generated {}", format_name(fmt)));
            }
            Some(t) => match std::fs::write(&t, &data) {
                Ok(_) => logger::info(&format!("Succesfully generated {}: {}", format_name(fmt), display_path(&t))),
                Err(e) => logger::print_error(&format!("Error creating file {}: {}", t.display(), e)),
            },
        },
        Err(e) => logger::print_error(&e),
    }
}

pub fn render_all(book: &Book) {
    let order = ["tex", "html", "html.dir", "pdf", "epub"];
    for fmt in order.iter() {
        let key = format!("output.{}", fmt);
        let p = match book.options.get_str(&key) {
            Some(p) => p,
            None => continue,
        };
        let target = book.root.join(book.options.str_or("output.base_path", "")).join(&p);
        logger::debug(&format!("Attempting to generate {}...", fmt));
        if *fmt == "html.dir" {
            let _ = std::fs::create_dir_all(&target);
            match crate::epub::render_html_dir(book, &target, false) {
                Ok(()) => logger::info(&format!("Succesfully generated {}: {}", format_name(fmt), display_path(&target))),
                Err(e) => logger::error(&format!("Error rendering {}: {}", fmt, e.lines().next().unwrap_or(""))),
            }
            continue;
        }
        match render_bytes(book, fmt) {
            Ok(data) => match std::fs::write(&target, &data) {
                Ok(_) => logger::info(&format!("Succesfully generated {}: {}", format_name(fmt), display_path(&target))),
                Err(e) => logger::error(&format!("Error rendering {}: Error creating file {}: {}", fmt, target.display(), e)),
            },
            Err(e) => logger::error(&format!("Error rendering {}: {}", fmt, e)),
        }
    }
}
