// LaTeX renderer
use crate::book::{Book, Number};
use crate::highlight;
use crate::html::to_roman;
use crate::resources::TEX_TEMPLATE;
use crate::template::{Context, Template, Value, TEX_SYNTAX};
use crate::token::Token;

pub fn escape_tex(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("\\&"),
            '%' => out.push_str("\\%"),
            '$' => out.push_str("\\$"),
            '#' => out.push_str("\\#"),
            '_' => out.push_str("\\_"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '[' => out.push_str("{[}"),
            ']' => out.push_str("{]}"),
            '~' => out.push_str("\\textasciitilde{}"),
            '^' => out.push_str("\\textasciicircum{}"),
            '\\' => out.push_str("\\textbackslash{}"),
            '<' => out.push_str("\\textless{}"),
            '>' => out.push_str("\\textgreater{}"),
            '!' => out.push_str("!{}"),
            _ => out.push(c),
        }
    }
    out
}

fn escape_code(s: &str, block: bool) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            ' ' if block => out.push_str("\\hphantom{ }\\allowbreak{}"),
            '(' | ')' | '-' | '.' | '/' | ':' => {
                out.push(c);
                out.push_str("\\allowbreak{}");
            }
            '_' => out.push_str("\\_\\allowbreak{}"),
            _ => out.push_str(&escape_tex(&c.to_string())),
        }
    }
    out
}

fn tex_lang(lang: &str) -> &'static str {
    match lang {
        "en" => "english",
        "fr" => "francais",
        "de" => "ngerman",
        "es" => "spanish",
        "it" => "italian",
        "pt" => "portuguese",
        "ru" => "russian",
        "nl" => "dutch",
        _ => "english",
    }
}

pub struct LatexRenderer<'a> {
    book: &'a Book,
    escape_nb: bool,
    current_chapter: [i64; 7],
    current_numbering: i64,
    current_part: bool,
    current_hide: bool,
    chapter_index: usize,
    first_header: bool,
    first_paragraph: bool,
    pub images: Vec<(String, String)>,
    pub use_strikethrough: bool,
    pub use_taskitem: bool,
    pub use_codeblocks: bool,
    pub use_images: bool,
    pub use_tables: bool,
    is_article: bool,
    hyperref: bool,
    links_as_footnotes: bool,
    chapter_filenames: Vec<String>,
}

impl<'a> LatexRenderer<'a> {
    pub fn new(book: &'a Book) -> LatexRenderer<'a> {
        LatexRenderer {
            book,
            escape_nb: book.options.get_bool("tex.escape_nb_spaces"),
            current_chapter: [0; 7],
            current_numbering: book.options.get_int("rendering.num_depth").unwrap_or(1),
            current_part: false,
            current_hide: false,
            chapter_index: 0,
            first_header: true,
            first_paragraph: true,
            images: Vec::new(),
            use_strikethrough: false,
            use_taskitem: false,
            use_codeblocks: false,
            use_images: false,
            use_tables: false,
            is_article: book.options.str_or("tex.class", "book") != "book",
            hyperref: book.options.get_bool("tex.hyperref"),
            links_as_footnotes: book.options.get_bool("tex.links_as_footnotes"),
            chapter_filenames: book.chapters.iter().map(|c| c.filename.clone()).collect(),
        }
    }

    fn text(&self, s: &str) -> String {
        let e = escape_tex(s);
        if self.escape_nb {
            e.replace('\u{a0}', "~").replace('\u{202f}', "\\,")
        } else {
            e
        }
    }

    pub fn render_vec(&mut self, v: &[Token]) -> String {
        let mut s = String::new();
        for t in v {
            s.push_str(&self.render_token(t));
        }
        s
    }

    fn header(&mut self, level: i32, content: &[Token]) -> String {
        let title = self.render_vec(content);
        let level = level.max(1).min(6) as usize;
        let label = if self.first_header {
            self.first_header = false;
            Some(format!("\\label{{chapter-{}}}", self.chapter_index))
        } else {
            None
        };
        if level == 1 && self.current_part {
            let star = if self.current_numbering >= 1 { "" } else { "*" };
            let reset = if self.book.options.get_bool("rendering.part.reset_counter") { "\\setcounter{chapter}{0}" } else { "" };
            let mut s = format!("{}\\part{}{{{}}}\n", reset, star, title);
            if star == "*" {
                s.push_str(&format!("\\addcontentsline{{toc}}{{part}}{{{}}}\n", title));
            }
            if let Some(l) = label {
                s.push_str(&l);
                s.push('\n');
            }
            return s;
        }
        if level == 1 && self.current_hide {
            let mut s = format!("\\chapter*{{}}");
            if let Some(l) = label {
                s.push_str(&l);
            }
            s.push('\n');
            return s;
        }
        let cmd = match (level, self.is_article) {
            (1, false) => "chapter",
            (1, true) => "section",
            (2, _) => "section",
            (3, _) => "subsection",
            (4, _) => "subsubsection",
            _ => "paragraoh",
        };
        let numbered = self.current_numbering >= 1;
        let star = if numbered { "" } else { "*" };
        let mut s = format!("\\{}{}{{{}}}\n", cmd, star, title);
        if level == 1 && !numbered {
            s.push_str(&format!("\\addcontentsline{{toc}}{{{}}}{{{}}}\n", cmd, title));
        }
        if let Some(l) = label {
            s.push_str(&l);
            s.push('\n');
        }
        s
    }

    fn resolve_link(&self, url: &str) -> Option<usize> {
        if url.contains("://") {
            return None;
        }
        let base = match url.find('#') {
            Some(p) => &url[..p],
            None => url,
        };
        let with_md = crate::html::with_extension_md(url);
        for (i, f) in self.chapter_filenames.iter().enumerate() {
            if f.is_empty() {
                continue;
            }
            if f == url || f == &with_md || (!base.is_empty() && f == base) {
                return Some(i);
            }
        }
        None
    }

    fn image(&mut self, url: &str) -> Option<String> {
        if url.contains("://") {
            return None;
        }
        if let Some((_, n)) = self.images.iter().find(|(u, _)| u == url) {
            return Some(n.clone());
        }
        let ext = std::path::Path::new(url).extension().map(|e| format!(".{}", e.to_string_lossy())).unwrap_or_default();
        let name = format!("images/image_{}{}", self.images.len(), ext);
        self.images.push((url.to_string(), name.clone()));
        Some(name)
    }

    pub fn render_token(&mut self, t: &Token) -> String {
        match t {
            Token::Str(s) => self.text(s),
            Token::Paragraph(v) => {
                if self.first_paragraph {
                    self.first_paragraph = false;
                    if self.book.options.get_bool("rendering.initials") {
                        if let Some(Token::Str(s)) = v.first() {
                            let chars: Vec<char> = s.chars().collect();
                            if !chars.is_empty() && chars[0].is_alphanumeric() {
                                let first = chars[0].to_string();
                                let mut k = 1;
                                while k < chars.len() && !chars[k].is_whitespace() {
                                    k += 1;
                                }
                                let rest: String = chars[1..k].iter().collect();
                                let after: String = chars[k..].iter().collect();
                                let mut out = format!("\\lettrine{{{}}}{{{}}}{}", self.text(&first), self.text(&rest), self.text(&after));
                                out.push_str(&self.render_vec(&v[1..]));
                                return format!("{}\n\n", out);
                            }
                        }
                    }
                }
                format!("{}\n\n", self.render_vec(v))
            }
            Token::Header(l, v) => {
                if *l == 1 {
                    self.first_paragraph = true;
                }
                self.header(*l, v)
            }
            Token::Emphasis(v) => format!("\\emph{{{}}}", self.render_vec(v)),
            Token::Strong(v) => format!("\\mdstrong{{{}}}", self.render_vec(v)),
            Token::Strikethrough(v) => {
                self.use_strikethrough = true;
                format!("\\sout{{{}}}", self.render_vec(v))
            }
            Token::Superscript(v) => format!("\\textsuperscript{{{}}}", self.render_vec(v)),
            Token::Subscript(v) => format!("\\textsubscript{{{}}}", self.render_vec(v)),
            Token::Code(s) => format!("\\mdcode{{{}}}", escape_code(s, false)),
            Token::BlockQuote(v) => format!("\\begin{{mdblockquote}}\n{}\n\\end{{mdblockquote}}\n", self.render_vec(v)),
            Token::CodeBlock(lang, code) => self.code_block(lang, code),
            Token::Rule => "\\mdrule\n".to_string(),
            Token::SoftBreak => " ".to_string(),
            Token::HardBreak => "\\mdhardbreak\n".to_string(),
            Token::List(v) => format!("\\begin{{itemize}}\n{}\\end{{itemize}}", self.render_vec(v)),
            Token::OrderedList(n, v) => {
                let start = if *n != 1 { format!("\\setcounter{{enumi}}{{{}}}\n", n - 1) } else { String::new() };
                format!("\\begin{{enumerate}}\n{}{}\n\\end{{enumerate}}\n", start, self.render_vec(v))
            }
            Token::Item(v) => format!("\\item {}\n", self.render_vec(v)),
            Token::TaskItem(checked, v) => {
                self.use_taskitem = true;
                let b = if *checked { "[$\\boxtimes$] " } else { "[$\\square$] " };
                format!("{}{}", b, self.render_vec(v))
            }
            Token::DescriptionList(v) => format!("\\begin{{description}}[style=nextline, labelwidth=0pt]\n{}\n\\end{{description}}", self.render_vec(v)),
            Token::DescriptionItem(v) => self.render_vec(v),
            Token::DescriptionTerm(v) => format!("\\item[{}]\n", self.render_vec(v)),
            Token::DescriptionDetails(v) => self.render_vec(v),
            Token::Table(n, v) => {
                self.use_tables = true;
                let cols = "|X".repeat(*n) + "|";
                format!("\\begin{{mdtable}}{{{}}}\n\\hline\n{}\n\\hline\n\\end{{mdtable}}\n\n", cols, self.render_vec(v))
            }
            Token::TableHead(v) => {
                let cells: Vec<String> = v.iter().map(|c| if let Token::TableCell(i) = c { self.render_vec(i) } else { String::new() }).collect();
                format!("{}\\\\ \n\\hline\n", cells.join(" & "))
            }
            Token::TableRow(v) => {
                let cells: Vec<String> = v.iter().map(|c| if let Token::TableCell(i) = c { self.render_vec(i) } else { String::new() }).collect();
                format!("{}\\\\ \n", cells.join(" & "))
            }
            Token::TableCell(v) => self.render_vec(v),
            Token::Link(url, _title, v) => {
                let content = self.render_vec(v);
                if let Some(i) = self.resolve_link(url) {
                    if self.hyperref {
                        let tpl = self.book.options.str_or("tex.pageref_template", "");
                        let key = format!("chapter-{}", i);
                        let foot = tpl.replace("<<key>>", &key);
                        return format!("\\hyperref[{}]{{{}}}{}", key, content, foot);
                    }
                }
                let u = escape_tex(url);
                let plain: String = crate::token::view_as_text(v);
                if plain == *url {
                    format!("\\url{{{}}}", u)
                } else if self.links_as_footnotes {
                    format!("\\href{{{}}}{{{}}}\\protect\\footnote{{\\url{{{}}}}}", u, content, u)
                } else {
                    format!("\\href{{{}}}{{{}}}", u, content)
                }
            }
            Token::Image(url, _, _) => match self.image(url) {
                Some(p) => {
                    self.use_images = true;
                    format!("\\mdimage{{{}}}", p)
                }
                None => String::new(),
            },
            Token::StandaloneImage(url, _, _) => match self.image(url) {
                Some(p) => {
                    self.use_images = true;
                    format!("\\mdstandaloneimage{{{}}}\n", p)
                }
                None => String::new(),
            },
            Token::FootnoteReference(name) => format!("\\footnotemark[{}]", name),
            Token::FootnoteDefinition(name, v) => format!("\\footnotetext[{}]{{{}}}", name, self.render_vec(v)),
            Token::RawBlock(s) => self.text(s),
        }
    }

    fn code_block(&mut self, lang: &str, code: &str) -> String {
        self.use_codeblocks = true;
        let hl = self.book.options.str_or("rendering.highlight", "syntect");
        if hl != "syntect" {
            return format!("\\begin{{spverbatim}}\n{}\\end{{spverbatim}}\n", code);
        }
        let mut s = String::from("\\begin{mdcodeblock}\n{\\sloppy ");
        for line in highlight::highlight_regions(code, lang) {
            for (color, bold, italic, text) in line {
                let mut r = format!(
                    "\\textcolor[rgb]{{{}, {}, {}}}{{\\texttt{{{}}}}}",
                    highlight::rgb_f32(color.0),
                    highlight::rgb_f32(color.1),
                    highlight::rgb_f32(color.2),
                    escape_code(&text, true)
                );
                if bold {
                    r = format!("\\textbf{{{}}}", r);
                }
                if italic {
                    r = format!("\\emph{{{}}}", r);
                }
                s.push_str(&r);
            }
            s.push_str("\\\\{}\n");
        }
        s.push_str("}\n\\end{mdcodeblock}");
        s
    }

    pub fn begin_chapter(&mut self, index: usize, number: &Number) {
        self.chapter_index = index;
        self.first_header = true;
        self.current_part = number.is_part();
        self.current_hide = matches!(number, Number::Hidden);
        let nd = self.book.options.get_int("rendering.num_depth").unwrap_or(1);
        self.current_numbering = match number {
            Number::Unnumbered | Number::UnnumberedPart | Number::Hidden => 0,
            _ => nd,
        };
        let _ = &self.current_chapter;
    }
}

fn meta_tex(r: &mut LatexRenderer, book: &Book, key: &str) -> Option<String> {
    let toks = book.metadata_tokens(key)?;
    Some(r.render_vec(&toks))
}

pub fn render_latex(book: &Book) -> Result<String, String> {
    let mut r = LatexRenderer::new(book);
    let mut content = String::new();
    for (i, ch) in book.chapters.iter().enumerate() {
        r.begin_chapter(i, &ch.number);
        content.push_str(&r.render_vec(&ch.content));
    }
    let lang = book.lang();
    let class = book.options.str_or("tex.class", "book");
    let is_book = class == "book";
    let mut ctx = Context::new();
    let size = book.options.get_int("tex.font.size");
    ctx.insert("has_tex_size".into(), Value::Bool(size.is_some()));
    ctx.insert("tex_size".into(), Value::Str(size.map(|s| s.to_string()).unwrap_or_default()));
    ctx.insert("class".into(), Value::Str(class.clone()));
    ctx.insert("book".into(), Value::Bool(is_book));
    ctx.insert("xelatex".into(), Value::Bool(book.options.str_or("tex.command", "xelatex") == "xelatex"));
    ctx.insert("tex_lang".into(), Value::Str(tex_lang(&lang).to_string()));
    ctx.insert("use_strikethrough".into(), Value::Bool(r.use_strikethrough));
    ctx.insert("use_taskitem".into(), Value::Bool(r.use_taskitem));
    ctx.insert("use_codeblocks".into(), Value::Bool(r.use_codeblocks));
    ctx.insert("use_images".into(), Value::Bool(r.use_images));
    ctx.insert("use_tables".into(), Value::Bool(r.use_tables));
    ctx.insert("initials".into(), Value::Bool(book.options.get_bool("rendering.initials")));
    ctx.insert("stdpage".into(), Value::Bool(book.options.get_bool("tex.stdpage")));
    ctx.insert("papersize".into(), Value::Str(book.options.str_or("tex.paper.size", "a5paper")));
    ctx.insert("margin_top".into(), Value::Str(book.options.str_or("tex.margin.top", "2cm")));
    ctx.insert("margin_bottom".into(), Value::Str(book.options.str_or("tex.margin.bottom", "1.5cm")));
    let (dl, dr) = if is_book { ("2.5cm", "1.5cm") } else { ("2cm", "2cm") };
    ctx.insert("margin_left".into(), Value::Str(book.options.get_str("tex.margin.left").unwrap_or_else(|| dl.to_string())));
    ctx.insert("margin_right".into(), Value::Str(book.options.get_str("tex.margin.right").unwrap_or_else(|| dr.to_string())));
    let use_cover = book.options.get_bool("tex.cover") && book.options.get_str("cover").is_some();
    ctx.insert("use_cover".into(), Value::Bool(use_cover));
    ctx.insert("cover_path".into(), Value::Str(book.options.str_or("cover", "")));
    let author = meta_tex(&mut r, book, "author").unwrap_or_default();
    let title = meta_tex(&mut r, book, "title").unwrap_or_default();
    ctx.insert("has_author".into(), Value::Bool(!book.options.str_or("author", "").is_empty()));
    ctx.insert("author".into(), Value::Str(author));
    ctx.insert("title".into(), Value::Str(title));
    for key in ["description", "subtitle", "autograph", "version", "license", "date"] {
        let v = meta_tex(&mut r, book, key);
        ctx.insert(format!("has_{}", key), Value::Bool(v.is_some()));
        ctx.insert(key.to_string(), Value::Str(v.unwrap_or_default()));
    }
    ctx.insert("additional_code".into(), Value::Str(book.options.str_or("tex.template.add", "")));
    let chapter_name = book.options.get_str("rendering.chapter");
    ctx.insert("chapter_name".into(), Value::Str(chapter_name.unwrap_or_default()));
    let part_name = book.options.get_str("rendering.part");
    ctx.insert("part_name".into(), Value::Str(part_name.unwrap_or_default()));
    ctx.insert("tex_title".into(), Value::Bool(book.options.get_bool("tex.title")));
    ctx.insert("inline_toc".into(), Value::Bool(book.options.get_bool("rendering.inline_toc")));
    ctx.insert("content".into(), Value::Str(content));
    let _ = to_roman(1);
    let tpl = crate::html_single::get_template(book, "tex.template", TEX_TEMPLATE)?;
    let t = Template::compile(&tpl, &TEX_SYNTAX).map_err(|e| format!("Error compiling template: {}{}", e.msg, e.detail))?;
    t.render(&ctx).map_err(|e| format!("Error compiling template: {}{}", e.msg, e.detail))
}

pub fn render_pdf(book: &Book) -> Result<Vec<u8>, String> {
    let tex = render_latex(book)?;
    let cmd = book.options.str_or("tex.command", "xelatex");
    let dir = std::env::temp_dir().join(format!("crowbook{}", std::process::id()));
    let _ = std::fs::create_dir_all(&dir);
    let _ = std::fs::write(dir.join("result.tex"), tex);
    let res = std::process::Command::new(&cmd).arg("-interaction=nonstopmode").arg("result.tex").current_dir(&dir).output();
    match res {
        Err(_) => {
            let _ = std::fs::remove_dir_all(&dir);
            Err(format!("Error during temporary files editing: failed to run command '{}'", cmd))
        }
        Ok(_) => {
            let _ = std::process::Command::new(&cmd).arg("-interaction=nonstopmode").arg("result.tex").current_dir(&dir).output();
            let pdf = std::fs::read(dir.join("result.pdf"));
            let _ = std::fs::remove_dir_all(&dir);
            pdf.map_err(|_| "Error during temporary files editing: Error during PDF generation".to_string())
        }
    }
}
