    pub fn new() -> ZipWriter {
        let secs = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0) as i64;
        let (y, mo, d, h, mi, s) = crate::epub::civil(secs);
        let time = ((h as u16) << 11) | ((mi as u16) << 5) | ((s as u16) / 2);
        let date = (((y - 1980).max(0) as u16) << 9) | ((mo as u16) << 5) | (d as u16);
        ZipWriter { data: Vec::new(), central: Vec::new(), count: 0, time, date }
    }

    pub fn add(&mut self, name: &str, content: &[u8], store: bool) {
        let crc = crc32(content);
        let (method, comp) = if store { (0u16, content.to_vec()) } else { (8u16, deflate_stored(content)) };
        let version = if store { 10 } else { 20 };
        let offset = self.data.len() as u32;
        let d = &mut self.data;
        put32(d, 0x04034b50);
        put16(d, version);
        put16(d, 0);
        put16(d, method);
        put16(d, self.time);
        put16(d, self.date);
        put32(d, crc);
        put32(d, comp.len() as u32);
        put32(d, content.len() as u32);
        put16(d, name.len() as u16);
        put16(d, 0);
        d.extend_from_slice(name.as_bytes());
        d.extend_from_slice(&comp);
        let c = &mut self.central;
        put32(c, 0x02014b50);
        put16(c, 0x031e);
        put16(c, version);
        put16(c, 0);
        put16(c, method);
        put16(c, self.time);
        put16(c, self.date);
        put32(c, crc);
        put32(c, comp.len() as u32);
        put32(c, content.len() as u32);
        put16(c, name.len() as u16);
        put16(c, 0);
        put16(c, 0);
        put16(c, 0);
        put16(c, 0);
        put32(c, 0x81a40000);
        put32(c, offset);
        c.extend_from_slice(name.as_bytes());
        self.count += 1;
    }

    pub fn finish(mut self) -> Vec<u8> {
        let cd_offset = self.data.len() as u32;
        let cd_size = self.central.len() as u32;
        let mut out = std::mem::take(&mut self.data);
        out.extend_from_slice(&self.central);
        put32(&mut out, 0x06054b50);
        put16(&mut out, 0);
        put16(&mut out, 0);
        put16(&mut out, self.count);
        put16(&mut out, self.count);
        put32(&mut out, cd_size);
        put32(&mut out, cd_offset);
        put16(&mut out, 0);
        out
    }
}
