pub fn civil(secs: i64) -> (i64, i64, i64, i64, i64, i64) {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (h, mi, s) = (rem / 3600, (rem / 60) % 60, rem % 60);
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d, h, mi, s)
}

fn now_rfc3339() -> String {
    let secs = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0) as i64;
    let (y, mo, d, h, mi, s) = civil(secs);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", y, mo, d, h, mi, s)
}

fn uuid_v4() -> String {
    let mut b = [0u8; 16];
    if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
        let _ = std::io::Read::read_exact(&mut f, &mut b);
    }
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    let h: Vec<String> = b.iter().map(|x| format!("{:02x}", x)).collect();
    format!("{}-{}-{}-{}-{}", h[0..4].concat(), h[4..6].concat(), h[6..8].concat(), h[8..10].concat(), h[10..16].concat())
}

pub fn strip_tags(s: &str) -> String {
    let mut out = String::new();
    let mut in_tag = false;
    for c in s.chars() {
        if c == '<' {
            in_tag = true;
        } else if c == '>' && in_tag {
            in_tag = false;
        } else if !in_tag {
            out.push(c);
        }
    }
    out
}

struct Entry {
    url: String,
    title: String,
    raw: String,
    children: Vec<TocElement>,
}

const V3_CHAPTER: &str = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html>\n<html xmlns=\"http://www.w3.org/1999/xhtml\"\n      xmlns:epub=\"http://www.idpf.org/2007/ops\" xml:lang = \"{{lang}}\" lang=\"{{lang}}\">\n  <head>\n    <meta charset = \"utf-8\" />\n    <meta name=\"generator\" content=\"crowbook\" />\n    <title>{{chapter_title_raw}}</title>\n    <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n  </head>\n  <body xml:lang=\"{{lang}}\" lang=\"{{lang}}\">\n    <section class = \"level1\">\n      {{content}}\n    </section>\n  </body>\n</html>\n";

const V3_TITLEPAGE: &str = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html>\n<html xmlns=\"http://www.w3.org/1999/xhtml\"\n      xmlns:epub=\"http://www.idpf.org/2007/ops\" xml:lang=\"{{lang}}\" lang=\"{{lang}}\">\n<head>\n  <meta charset = \"utf-8\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>{{title_raw}}</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n  <section epub:type = \"titlepage\">\n    <h2 class=\"author\">{{author}}</h2>\n    <h1 class=\"title\">{{title}}</h1>\n    {% if has_subtitle %}<h2 class=\"subtitle\">{{subtitle}}</h2>{% endif %}\n    {% if has_autograph %}\n    <div id = \"autograph\">\n      {{autograph}}\n    </div>\n    {% endif %}\n  </section>\n</body>\n</html>";

fn cover_xhtml(v3: bool, lang: &str, title_raw: &str, url: &str, loc_cover: &str) -> String {
    if v3 {
        format!("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html>\n<html xmlns=\"http://www.w3.org/1999/xhtml\"\n      xmlns:epub=\"http://www.idpf.org/2007/ops\" xml:lang=\"{lang}\" lang=\"{lang}\">\n<head>\n  <meta charset = \"utf-8\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>{title}</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n<div id=\"cover\">\n<img src=\"{url}\" alt=\"{cover}\" />\n</div>\n</body>\n</html>\n\n", lang = lang, title = title_raw, url = url, cover = loc_cover)
    } else {
        format!("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"{lang}\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>{title}</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n<div id=\"cover\">\n<img src=\"{url}\" alt=\"{cover}\" />\n</div>\n</body>\n</html>\n\n", lang = lang, title = title_raw, url = url, cover = loc_cover)
    }
}

fn ncx_points(e: &[(String, String, Vec<TocElement>)], counter: &mut usize, indent: usize, out: &mut String) {
    for (label, url, children) in e {
        *counter += 1;
        let sp = " ".repeat(indent);
        out.push_str(&format!(
            "{sp}<navPoint playOrder=\"{n}\" id=\"navPoint-{n}\">\n{sp}  <navLabel>\n{sp}   <text>{label}</text>\n{sp}  </navLabel>\n{sp}  <content src=\"{url}\"/>\n",
            sp = sp,
            n = counter,
            label = label,
            url = url
        ));
        let kids: Vec<(String, String, Vec<TocElement>)> = children.iter().map(|c| (c.raw.clone(), c.url.clone(), c.children.clone())).collect();
        ncx_points(&kids, counter, indent + 2, out);
        out.push_str(&format!("{}</navPoint>\n", sp));
    }
}

fn nav_items(entries: &[(String, String, Vec<TocElement>)]) -> String {
    let mut items = Vec::new();
    for (title, url, children) in entries {
        let e = TocElement { level: 0, url: url.clone(), title: title.clone(), raw: String::new(), children: children.clone() };
        items.push(e.render_pub(6, "ol"));
    }
    items.join("\n")
}

pub fn render_epub(book: &Book) -> Result<Vec<u8>, String> {
    let v3 = book.options.get_int("epub.version").unwrap_or(2) == 3;
    let lang_s = book.lang();
    let images: Rc<RefCell<Vec<(String, String)>>> = Rc::new(RefCell::new(Vec::new()));
    let mut r = HtmlRenderer::new(book, Flavor::Epub);
    r.link_target = Box::new(|i| format!("chapter_{:03}.xhtml", i));
    let img_ref = images.clone();
    let mut img_error: Rc<RefCell<Option<String>>> = Rc::new(RefCell::new(None));
    let _ = &mut img_error;
    r.image_handler = Some(Box::new(move |url: &str| {
        let (path, display) = image_path(book, url);
        if !path.exists() {
            return Err(format!("Could not find file '{}' for image", display));
        }
        let mut imgs = img_ref.borrow_mut();
        if let Some((_, n)) = imgs.iter().find(|(u, _)| u == url) {
            return Ok(n.clone());
        }
        let ext = std::path::Path::new(url).extension().map(|e| format!(".{}", e.to_string_lossy())).unwrap_or_default();
        let name = format!("images/image_{}{}", imgs.len(), ext);
        imgs.push((url.to_string(), name.clone()));
        Ok(name)
    }));
    // cover
    let cover = book.options.get_str("cover");
    let mut cover_name: Option<String> = None;
    if let Some(c) = &cover {
        let (path, display) = image_path(book, c);
        if !path.exists() {
            return Err(format!("Could not find file '{}' for cover", display));
        }
        let ext = std::path::Path::new(c).extension().map(|e| format!(".{}", e.to_string_lossy())).unwrap_or_default();
        let name = format!("images/image_{}{}", images.borrow().len(), ext);
        images.borrow_mut().push((c.clone(), name.clone()));
        cover_name = Some(name);
    }
    let mut files: Vec<(String, Vec<u8>)> = Vec::new();
    let title_raw = book.options.str_or("title", "");
    let loc_title = lang::get(&lang_s, "title");
    let loc_cover = lang::get(&lang_s, "cover");
    let loc_toc = lang::get(&lang_s, "toc");
    if let Some(cn) = &cover_name {
        files.push(("cover.xhtml".into(), cover_xhtml(v3, &lang_s, &title_raw, cn, &loc_cover).into_bytes()));
    }
    // chapters
    let mut entries: Vec<Entry> = Vec::new();
    let mut in_part = false;
    let mut chapter_files: Vec<(String, String)> = Vec::new();
    let mut fatal: Option<String> = None;
    for (i, ch) in book.chapters.iter().enumerate() {
        r.begin_chapter(i, &ch.number);
        r.toc = crate::toc::Toc::new();
        let body = r.render_vec(&ch.content);
        let notes = r.render_notes();
        if let Some(e) = r.fatal.take() {
            if fatal.is_none() {
                fatal = Some(format!("{}: {}", ch.filename, e));
            }
        }
        let toc = std::mem::replace(&mut r.toc, crate::toc::Toc::new());
        let file = format!("chapter_{:03}.xhtml", i);
        let first = toc.elements.first().cloned();
        let chapter_title = first.as_ref().map(|f| f.title.clone()).unwrap_or_default();
        if ch.number.is_part() {
            in_part = true;
            entries.push(Entry { url: file.clone(), title: chapter_title.clone(), raw: String::new(), children: first.map(|f| f.children).unwrap_or_default() });
        } else if in_part {
            if let Some(last) = entries.last_mut() {
                for e in toc.elements.iter() {
                    last.children.push(e.clone());
                }
            }
        } else if let Some(f) = first {
            entries.push(Entry { url: file.clone(), title: f.title.clone(), raw: f.raw.clone(), children: f.children.clone() });
        }
        let _ = Number::Default;
        let content = format!("{}{}", body, notes);
        chapter_files.push((file, strip_tags(&chapter_title)));
        let mut ctx = Context::new();
        ctx.insert("lang".into(), Value::Str(lang_s.clone()));
        ctx.insert("chapter_title_raw".into(), Value::Str(strip_tags(&chapter_title)));
        ctx.insert("chapter_title".into(), Value::Str(chapter_title.clone()));
        ctx.insert("content".into(), Value::Str(content));
        let tpl = if v3 { get_template(book, "epub.chapter.xhtml", V3_CHAPTER)? } else { get_template(book, "epub.chapter.xhtml", EPUB_CHAPTER_XHTML)? };
        let html = render_tpl(&tpl, &ctx)?;
        files.push((chapter_files.last().unwrap().0.clone(), html.into_bytes()));
    }
    if let Some(f) = fatal {
        return Err(f);
    }
    // title page
    let mut tctx = Context::new();
    tctx.insert("lang".into(), Value::Str(lang_s.clone()));
    tctx.insert("title_raw".into(), Value::Str(title_raw.clone()));
    let title = crate::html_single::meta_html(&mut r, "title").unwrap_or_default();
    let author = crate::html_single::meta_html(&mut r, "author").unwrap_or_default();
    tctx.insert("title".into(), Value::Str(title));
    tctx.insert("author".into(), Value::Str(author));
    let subtitle = crate::html_single::meta_html(&mut r, "subtitle");
    tctx.insert("has_subtitle".into(), Value::Bool(subtitle.is_some()));
    tctx.insert("subtitle".into(), Value::Str(subtitle.unwrap_or_default()));
    let autograph = crate::html_single::meta_html(&mut r, "autograph");
    tctx.insert("has_autograph".into(), Value::Bool(autograph.is_some()));
    tctx.insert("autograph".into(), Value::Str(autograph.unwrap_or_default()));
    let tp_tpl = if v3 { get_template(book, "epub.titlepage.xhtml", V3_TITLEPAGE)? } else { get_template(book, "epub.titlepage.xhtml", EPUB_TITLEPAGE_XHTML)? };
    let title_page = render_tpl(&tp_tpl, &tctx)?;
    let insert_at = if cover_name.is_some() { 1 } else { 0 };
    files.insert(insert_at, ("title_page.xhtml".into(), title_page.into_bytes()));
    // stylesheet
    let css = render_css(book, "epub.css", EPUB_CSS, "epub.css.add", false)?;
    files.push(("stylesheet.css".into(), css.into_bytes()));
    // images
    let mut image_items: Vec<(String, String, bool)> = Vec::new();
    for (url, name) in images.borrow().iter() {
        let (path, display) = image_path(book, url);
        let data = std::fs::read(&path).map_err(|_| format!("Could not find file '{}' for image", display))?;
        files.push((name.clone(), data));
        image_items.push((name.clone(), mime_for(name).to_string(), Some(name) == cover_name.as_ref()));
    }

    // content.opf
    let uuid = uuid_v4();
    let mut opf = String::new();
    opf.push_str(&format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<package version=\"{}\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n  <metadata xmlns:dc=\"http://purl.org/dc/elements/1.1/\"\n            xmlns:opf=\"http://www.idpf.org/2007/opf\">\n    <dc:identifier id=\"epub-id-1\">urn:uuid:{}</dc:identifier>\n    <dc:title>{}</dc:title>\n    \n    \n",
        if v3 { "3.0" } else { "2.0" },
        uuid,
        escape_html(&title_raw)
    ));
    if v3 {
        opf.push_str(&format!("    <dc:language id=\"epub-creator-0\">{}</dc:language>\n    \n    \n", lang_s));
    } else {
        opf.push_str(&format!("    <dc:language>{}</dc:language>\n    \n    \n", lang_s));
    }
    if let Some(a) = book.options.get_str("author") {
        if !a.is_empty() {
            if v3 {
                opf.push_str(&format!("    \n    <dc:creator id=\"epub-creator-0\">{}</dc:creator>\n    <meta refines=\"#epub-creator-0\" property=\"role\" scheme=\"marc:relators\">aut</meta>\n    \n    \n", a));
            } else {
                opf.push_str(&format!("    \n    <dc:creator opf:role=\"aut\">{}</dc:creator>\n    \n    \n", a));
            }
        }
    }
    if v3 {
        opf.push_str(&format!("    <meta property=\"dcterms:modified\">{}</meta>\n", now_rfc3339()));
    }
    let mut optional = Vec::new();
    if let Some(d) = book.options.get_str("description") {
        optional.push(format!("    <dc:description>{}</dc:description>", d));
    }
    if let Some(d) = book.options.get_str("subject") {
        optional.push(format!("    <dc:subject>{}</dc:subject>", d));
    }
    if let Some(d) = book.options.get_str("license") {
        optional.push(format!("    <dc:rights>{}</dc:rights>", d));
    }
    if cover_name.is_some() {
        optional.push("    <meta name=\"cover\" content=\"cover-image\"/>".to_string());
    }
    opf.push_str(&optional.join("\n"));
    opf.push_str("\n  </metadata>\n  <manifest>\n    <item id=\"ncx\" href=\"toc.ncx\" media-type=\"application/x-dtbncx+xml\"/>\n");
    if v3 {
        opf.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\" properties=\"nav\"/>\n");
    } else {
        opf.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\"/>\n");
    }
    let mut spine = Vec::new();
    for (name, _) in files.iter() {
        if name.ends_with(".xhtml") {
            opf.push_str(&format!("    <item media-type=\"application/xhtml+xml\" id=\"id_{}\" href=\"{}\"/>\n", name, name));
            spine.push(name.clone());
        } else if name == "stylesheet.css" {
            opf.push_str("    <item media-type=\"text/css\" id=\"id_stylesheet.css\" href=\"stylesheet.css\"/>\n");
        }
    }
    for (name, mime, is_cover) in &image_items {
        if *is_cover {
            if v3 {
                opf.push_str(&format!("    <item media-type=\"{}\" properties=\"cover-image\" id=\"cover-image\" href=\"{}\"/>\n", mime, name));
            } else {
                opf.push_str(&format!("    <item media-type=\"{}\" id=\"cover-image\" href=\"{}\"/>\n", mime, name));
            }
        } else {
            opf.push_str(&format!("    <item media-type=\"{}\" id=\"id_{}\" href=\"{}\"/>\n", mime, name.replace('/', "_"), name));
        }
    }
    opf.push_str("  </manifest>\n");
    if v3 {
        opf.push_str("  <spine toc=\"ncx\" page-progression-direction=\"ltr\">\n");
    } else {
        opf.push_str("  <spine toc=\"ncx\">\n");
    }
    for s in &spine {
        opf.push_str(&format!("    <itemref idref=\"id_{}\"/>\n", s));
    }
    opf.push_str("  </spine>\n  <guide>\n");
    opf.push_str(&format!("    <reference type=\"toc\" title=\"{}\" href=\"nav.xhtml\"/>\n", loc_toc));
    if cover_name.is_some() {
        opf.push_str(&format!("    <reference type=\"cover\" title=\"{}\" href=\"cover.xhtml\"/>\n", loc_cover));
    }
    opf.push_str(&format!("    <reference type=\"title-page\" title=\"{}\" href=\"title_page.xhtml\"/>\n", loc_title));
    if let Some((f, t)) = chapter_files.first() {
        let t = match entries.first() {
            Some(e) if e.url == *f => strip_tags(&e.title),
            _ => t.clone(),
        };
        opf.push_str(&format!("    <reference type=\"text\" title=\"{}\" href=\"{}\"/>\n", t, f));
    }
    opf.push_str("  </guide>\n</package>\n");

    // toc entries
    let extras = book.options.get_bool("epub.toc.extras");
    let mut top: Vec<(String, String, Vec<TocElement>)> = Vec::new();
    if extras {
        if cover_name.is_some() {
            top.push((loc_cover.clone(), "cover.xhtml".into(), vec![]));
        }
        top.push((loc_title.clone(), "title_page.xhtml".into(), vec![]));
    }
    for e in &entries {
        let _ = &e.raw;
        top.push((e.title.clone(), e.url.clone(), e.children.clone()));
    }
    // ncx
    let mut ncx = format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ncx version=\"2005-1\" xmlns=\"http://www.daisy.org/z3986/2005/ncx/\">\n  <head>\n    <meta name=\"dtb:depth\" content=\"1\" />\n    <meta name=\"dtb:totalPageCount\" content=\"0\" />\n    <meta name=\"dtb:maxPageNumber\" content=\"0\" />\n  </head>\n  <docTitle>\n    <text>{}</text>\n  </docTitle>\n  <navMap>\n",
        loc_toc
    );
    let mut counter = 0;
    ncx_points(&top, &mut counter, 4, &mut ncx);
    ncx.push_str("  </navMap>\n</ncx>\n");
    // nav
    let items = nav_items(&top);
    let nav = if v3 {
        let mut land = Vec::new();
        if cover_name.is_some() {
            land.push(format!("      <li><a epub:type=\"cover\" href=\"cover.xhtml\">{}</a></li>", loc_cover));
        }
        land.push(format!("      <li><a epub:type=\"titlepage\" href=\"title_page.xhtml\">{}</a></li>", loc_title));
        if let Some((f, _)) = chapter_files.first() {
            let t = entries.first().map(|e| e.title.clone()).unwrap_or_default();
            land.push(format!("      <li><a epub:type=\"bodymatter\" href=\"{}\">{}</a></li>", f, t));
        }
        format!("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html>\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xmlns:epub=\"http://www.idpf.org/2007/ops\">\n<head>\n  <meta charset = \"utf-8\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>{toc}</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n  <nav epub:type = \"toc\" id=\"toc\">\n    <h1 id=\"toc-title\">{toc}</h1>\n    <ol>\n{items}\n    </ol>\n  </nav>\n  <nav epub:type = \"landmarks\">\n    <ol>\n{land}\n    </ol>\n  </nav>\n</body>\n</html>\n", toc = loc_toc, items = items, land = land.join("\n"))
    } else {
        format!("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>{toc}</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n  <div id=\"toc\">\n    <h1 id=\"toc-title\">{toc}</h1>\n    <ol>\n{items}\n    </ol>\n  </div>\n</body>\n</html>\n", toc = loc_toc, items = items)
    };

    // zip command check
    let zip_cmd = book.options.str_or("crowbook.zip.command", "zip");
    if std::process::Command::new(&zip_cmd).arg("-h").stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).status().is_err() {
        crate::logger::log(crate::logger::Level::Warn, "crowbook::epub", "Could not run zip command, falling back to zip library");
    }
    let mut z = crate::zip::ZipWriter::new();
    z.add("mimetype", b"application/epub+zip", true);
    z.add("META-INF/container.xml", b"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<container version=\"1.0\" xmlns=\"urn:oasis:names:tc:opendocument:xmlns:container\">\n  <rootfiles>\n    <rootfile full-path=\"OEBPS/content.opf\" media-type=\"application/oebps-package+xml\" />\n  </rootfiles>\n</container>\n", false);
    z.add("META-INF/com.apple.ibooks.display-options.xml", b"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<display_options>\n  <platform name=\"*\">\n    <option name=\"specified-fonts\">true</option>\n  </platform>\n</display_options>\n", false);
    for (name, data) in &files {
        z.add(&format!("OEBPS/{}", name), data, false);
    }
    z.add("OEBPS/content.opf", opf.as_bytes(), false);
    z.add("OEBPS/toc.ncx", ncx.as_bytes(), false);
    z.add("OEBPS/nav.xhtml", nav.as_bytes(), false);
    Ok(z.finish())
}

pub fn render_html_dir(book: &Book, dir: &std::path::Path, direct: bool) -> Result<(), String> {
    // Crowbook 0.17.0 fails on the index template; mimic partial output
    let mut r = HtmlRenderer::new(book, Flavor::Dir);
    r.link_target = Box::new(|i| format!("chapter_{:03}.html", i));
    let err_detail = "Error compiling template: render error\n\n  --> <anonymous>:8:7\n   |\n 8 |     {{favicon}}\n   |       ^^^^^^^\n   |\n   = reason: not found in this scope\n";
    if direct {
        return Err(err_detail.to_string());
    }
    let css = render_css(book, "html.css", HTML_CSS, "html.css.add", true)?;
    let print = get_template(book, "html.css.print", HTML_CSS_PRINT)?;
    let _ = std::fs::write(dir.join("stylesheet.css"), css);
    let _ = std::fs::write(dir.join("print.css"), print);
    let _ = &mut r;
    Err(err_detail.to_string())
}
