// Book statistics
use crate::book::Book;
use crate::token::view_as_text;

pub fn print_stats(book: &Book) {
    let mut rows = Vec::new();
    let mut total_chars = 0usize;
    let mut total_words = 0usize;
    let mut maxlen = 0usize;
    for ch in &book.chapters {
        let text = view_as_text(&ch.raw_content);
        let chars = text.chars().count();
        let words = text.split_whitespace().count();
        total_chars += chars;
        total_words += words;
        maxlen = maxlen.max(ch.filename.chars().count());
        rows.push((ch.filename.clone(), chars, words));
    }
    let w = maxlen + 2;
    let mut out = String::new();
    out.push_str(&format!("{:<w$}{:>10}{:>11}{:>12}\n", "Chapter", "Chars", "Words", "Chars/Word", w = w));
    out.push_str("---------\n");
    for (name, c, wd) in rows {
        let ratio = c as f64 / wd as f64;
        out.push_str(&format!("{:<w$}{:>10}{:>11}{:>12.2}\n", name, c, wd, ratio, w = w));
    }
    out.push_str("---------\n");
    let ratio = total_chars as f64 / total_words as f64;
    out.push_str(&format!("{:<w$}{:>10}{:>11}{:>12.2}\n\n", "TOTAL:", total_chars, total_words, ratio, w = w));
    print!("{}", out);
}
EOF
