    c.is_alphabetic() || c == '_'
}
fn is_ident(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn rust_lines(code: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut in_block_comment = false;
    for raw in code.split('\n') {
        let chars: Vec<char> = raw.chars().collect();
        let mut line: Line = Vec::new();
        let mut i = 0;
        let mut prev_word = String::new();
        while i < chars.len() {
            if in_block_comment {
                let start = i;
                while i < chars.len() && !(chars[i] == '*' && chars.get(i + 1) == Some(&'/')) {
                    i += 1;
                }
                let t: String = chars[start..i].iter().collect();
                push(&mut line, St::Comment, &t, true);
                if i < chars.len() {
                    push(&mut line, St::Comment, "*/", true);
                    i += 2;
                    in_block_comment = false;
                }
                continue;
            }
            let c = chars[i];
            if c == '/' && chars.get(i + 1) == Some(&'/') {
                let mut j = i;
                while j < chars.len() && chars[j] == '/' {
                    j += 1;
                }
                let p: String = chars[i..j].iter().collect();
                push(&mut line, St::Comment, &p, true);
                let rest: String = chars[j..].iter().collect();
                push(&mut line, St::Comment, &rest, true);
                break;
            }
            if c == '/' && chars.get(i + 1) == Some(&'*') {
                push(&mut line, St::Comment, "/*", true);
                i += 2;
                in_block_comment = true;
                continue;
            }
            if c == '"' {
                push(&mut line, St::Str, "\"", true);
                i += 1;
                let mut buf = String::new();
                while i < chars.len() && chars[i] != '"' {
                    if chars[i] == '\\' && i + 1 < chars.len() {
                        push(&mut line, St::Str, &buf, true);
                        buf.clear();
                        let e: String = chars[i..i + 2].iter().collect();
                        push(&mut line, St::Number, &e, true);
                        i += 2;
                        continue;
                    }
                    if chars[i] == '{' {
                        let mut j = i + 1;
                        while j < chars.len() && chars[j] != '}' && chars[j] != '"' {
                            j += 1;
                        }
                        if j < chars.len() && chars[j] == '}' {
                            push(&mut line, St::Str, &buf, true);
                            buf.clear();
                            let e: String = chars[i..=j].iter().collect();
                            push(&mut line, St::Number, &e, true);
                            i = j + 1;
                            continue;
                        }
                    }
                    buf.push(chars[i]);
                    i += 1;
                }
                push(&mut line, St::Str, &buf, true);
                if i < chars.len() {
                    push(&mut line, St::Str, "\"", true);
                    i += 1;
                }
                prev_word.clear();
                continue;
            }
            if c == '\'' {
                // char literal?
                if i + 2 < chars.len() && chars[i + 2] == '\'' {
                    push(&mut line, St::Str, "'", true);
                    push(&mut line, St::Str, &chars[i + 1].to_string(), true);
                    push(&mut line, St::Str, "'", true);
                    i += 3;
                    continue;
                }
                if i + 3 < chars.len() && chars[i + 1] == '\\' && chars[i + 3] == '\'' {
                    push(&mut line, St::Str, "'", true);
                    let e: String = chars[i + 1..i + 3].iter().collect();
                    push(&mut line, St::Number, &e, true);
                    push(&mut line, St::Str, "'", true);
                    i += 4;
                    continue;
                }
                // lifetime
                let mut j = i + 1;
                while j < chars.len() && is_ident(chars[j]) {
                    j += 1;
                }
                let t: String = chars[i..j].iter().collect();
                push(&mut line, St::Keyword, &t, true);
                i = j;
                continue;
            }
            if c.is_ascii_digit() {
                let mut j = i;
                if c == '0' && matches!(chars.get(i + 1), Some('x') | Some('o') | Some('b')) {
                    j += 2;
                    while j < chars.len() && (chars[j].is_ascii_hexdigit() || chars[j] == '_') {
                        j += 1;
                    }
                    let t: String = chars[i..j].iter().collect();
                    push(&mut line, St::Number, &t, true);
                    i = j;
                    continue;
                }
                while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == '_') {
                    j += 1;
                }
                if j < chars.len() && chars[j] == '.' && chars.get(j + 1).map(|c| c.is_ascii_digit()).unwrap_or(false) {
                    let t: String = chars[i..=j].iter().collect();
                    push(&mut line, St::Number, &t, true);
                    i = j + 1;
                    j = i;
                    while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == '_') {
                        j += 1;
                    }
                }
                while j < chars.len() && is_ident(chars[j]) {
                    j += 1;
                }
                let t: String = chars[i..j].iter().collect();
                push(&mut line, St::Number, &t, true);
                i = j;
                continue;
            }
            if is_ident_start(c) {
                let mut j = i;
                while j < chars.len() && is_ident(chars[j]) {
                    j += 1;
                }
                let w: String = chars[i..j].iter().collect();
                if j < chars.len() && chars[j] == '!' && chars.get(j + 1) != Some(&'=') {
                    let t: String = chars[i..=j].iter().collect();
                    push(&mut line, St::Plain, &t, true);
                    i = j + 1;
                    prev_word.clear();
                    continue;
                }
                if w == "true" || w == "false" {
                    push(&mut line, St::Number, &w, true);
                } else if w == "_" {
                    push(&mut line, St::Keyword, &w, true);
                } else if RUST_KW.contains(&w.as_str()) {
                    push(&mut line, St::Keyword, &w, true);
                } else if prev_word == "fn" {
                    push(&mut line, St::Func, &w, true);
                } else if ["struct", "enum", "trait", "impl", "type", "mod"].contains(&prev_word.as_str()) {
                    push(&mut line, St::Plain, &w, true);
                } else if i > 0 && chars[i - 1] == '.' && chars.get(j) == Some(&'(') {
                    push(&mut line, St::Support, &w, true);
                } else {
                    push(&mut line, St::Plain, &w, false);
                }
                prev_word = w;
                i = j;
                continue;
            }
            if c == ' ' || c == '\t' {
                let mut j = i;
                while j < chars.len() && (chars[j] == ' ' || chars[j] == '\t') {
                    j += 1;
                }
                let t: String = chars[i..j].iter().collect();
                push(&mut line, St::Plain, &t, false);
                i = j;
                continue;
            }
            // punctuation / operators
            let two: String = chars[i..(i + 2).min(chars.len())].iter().collect();
            if two == "->" || two == "::" {
                push(&mut line, St::Plain, &two, true);
                i += 2;
                continue;
            }
            if two == "=>" || two == "==" || two == "!=" || two == "<=" || two == ">=" || two == "+=" || two == "-=" || two == "*=" || two == "/=" || two == ".." {
                if two == ".." {
                    push(&mut line, St::Keyword, &two, true);
                } else {
                    push(&mut line, St::Keyword, &two, true);
                }
                i += 2;
                continue;
            }
            match c {
                '(' | ')' | '{' | '}' | '[' | ']' | ';' | ',' | ':' | '#' => push(&mut line, St::Plain, &c.to_string(), true),
                '.' => push(&mut line, St::Plain, ".", false),
                '=' | '+' | '-' | '*' | '/' | '%' | '<' | '>' | '&' | '|' | '!' | '^' | '?' => push(&mut line, St::Keyword, &c.to_string(), true),
                _ => push(&mut line, St::Plain, &c.to_string(), false),
            }
            if c != '.' {
                prev_word.clear();
            }
            i += 1;
        }
        lines.push(line);
    }
    lines
}

