// Syntax highlighting (approximation of syntect with the InspiredGitHub theme)
pub fn escape_syntect(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '\'' => out.push_str("&#39;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

pub const FG: (u8, u8, u8) = (0x32, 0x32, 0x32);

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum St {
    Plain,
    Keyword,
    Number,
    Str,
    Comment,
    Func,
    Support,
    PlainBold,
}

impl St {
    fn color(&self) -> (u8, u8, u8) {
        match self {
            St::Plain | St::PlainBold => FG,
            St::Keyword => (0xa7, 0x1d, 0x5d),
            St::Number => (0x00, 0x86, 0xb3),
            St::Str => (0x18, 0x36, 0x91),
            St::Comment => (0x96, 0x98, 0x96),
            St::Func => (0x79, 0x5d, 0xa3),
            St::Support => (0x62, 0xa3, 0x5c),
        }
    }
    fn bold(&self) -> bool {
        matches!(self, St::Keyword | St::Func | St::PlainBold)
    }
    fn italic(&self) -> bool {
        matches!(self, St::Comment)
    }
}

#[derive(Clone, Debug)]
pub struct Region {
    pub st: St,
    pub text: String,
    pub scoped: bool,
}

type Line = Vec<Region>;

fn push(line: &mut Line, st: St, text: &str, scoped: bool) {
    if text.is_empty() {
        return;
    }
    if !scoped {
        if let Some(last) = line.last_mut() {
            if !last.scoped && last.st == st {
                last.text.push_str(text);
                return;
            }
        }
    }
    line.push(Region { st, text: text.to_string(), scoped });
}

fn lang_of(lang: &str) -> &'static str {
    let l = lang.split_whitespace().next().unwrap_or("").to_lowercase();
    match l.as_str() {
        "rust" | "rs" => "rust",
        "python" | "py" | "py3" | "pyw" => "python",
        _ => "plain",
    }
}

fn plain_lines(code: &str) -> Vec<Line> {
    code.split('\n')
        .map(|l| {
            let mut v = Vec::new();
            push(&mut v, St::Plain, l, true);
            v
        })
        .collect()
}

pub fn highlight(code: &str, lang: &str) -> Vec<Line> {
    match lang_of(lang) {
        "rust" => rust_lines(code),
        "python" => python_lines(code),
        _ => plain_lines(code),
    }
}

pub fn highlight_html(code: &str, lang: &str, _theme: &str) -> String {
    let mut out = String::new();
    for line in highlight(code, lang) {
        let mut prev: Option<St> = None;
        let mut s = String::new();
        for r in &line {
            let unify = match prev {
                Some(p) => p.color() == r.st.color() && p.bold() == r.st.bold() && p.italic() == r.st.italic() || r.text.trim().is_empty(),
                None => false,
            };
            if unify {
                s.push_str(&escape_syntect(&r.text));
            } else {
                if prev.is_some() {
                    s.push_str("</span>");
                }
                prev = Some(r.st);
                let mut style = String::new();
                if r.st.bold() {
                    style.push_str("font-weight:bold;");
                }
                if r.st.italic() {
                    style.push_str("font-style:italic;");
                }
                let c = r.st.color();
                style.push_str(&format!("color:#{:02x}{:02x}{:02x};", c.0, c.1, c.2));
                s.push_str(&format!("<span style=\"{}\">{}", style, escape_syntect(&r.text)));
            }
        }
        if prev.is_some() {
            s.push_str("</span>");
        }
        out.push_str(&s);
        out.push('\n');
    }
    out
}

pub fn rgb_f32(c: u8) -> String {
    let f = c as f32 / 255.0;
    format!("{}", f)
}

/// Returns list of lines; each line is a list of (rgb,bold,italic,text) regions
pub fn highlight_regions(code: &str, lang: &str) -> Vec<Vec<((u8, u8, u8), bool, bool, String)>> {
    highlight(code, lang)
        .into_iter()
        .map(|l| l.into_iter().map(|r| (r.st.color(), r.st.bold(), r.st.italic(), r.text)).collect())
        .collect()
}

