const PY_KW: &[&str] = &[
    "and", "as", "assert", "async", "await", "break", "class", "continue", "def", "del", "elif", "else", "except", "finally", "for", "from", "global", "if",
    "import", "in", "is", "lambda", "nonlocal", "not", "or", "pass", "raise", "return", "try", "while", "with", "yield",
];
const PY_CONST: &[&str] = &["True", "False", "None", "Ellipsis", "NotImplemented"];
const PY_BUILTINS: &[&str] = &[
    "abs", "all", "any", "ascii", "bin", "bool", "bytearray", "bytes", "callable", "chr", "classmethod", "compile", "complex", "delattr", "dict", "dir", "divmod",
    "enumerate", "eval", "exec", "filter", "float", "format", "frozenset", "getattr", "globals", "hasattr", "hash", "help", "hex", "id", "input", "int",
    "isinstance", "issubclass", "iter", "len", "list", "locals", "map", "max", "memoryview", "min", "next", "object", "oct", "open", "ord", "pow", "print",
    "property", "range", "repr", "reversed", "round", "set", "setattr", "slice", "sorted", "staticmethod", "str", "sum", "super", "tuple", "type", "vars", "zip",
];

fn python_lines(code: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut in_triple: Option<(String, St)> = None;
    for raw in code.split('\n') {
        let chars: Vec<char> = raw.chars().collect();
        let mut line: Line = Vec::new();
        let mut i = 0;
        let mut prev_word = String::new();
        let mut at_stmt_start = true;
        while i < chars.len() {
            if let Some((q, st)) = in_triple.clone() {
                let qc: Vec<char> = q.chars().collect();
                let start = i;
                let mut found = None;
                let mut j = i;
                while j + qc.len() <= chars.len() {
                    if chars[j..j + qc.len()] == qc[..] {
                        found = Some(j);
                        break;
                    }
                    j += 1;
                }
                match found {
                    Some(e) => {
                        let t: String = chars[start..e].iter().collect();
                        push(&mut line, st, &t, true);
                        push(&mut line, st, &q, true);
                        i = e + qc.len();
                        in_triple = None;
                    }
                    None => {
                        let t: String = chars[start..].iter().collect();
                        push(&mut line, st, &t, true);
                        i = chars.len();
                    }
                }
                continue;
            }
            let c = chars[i];
            if c == '#' {
                push(&mut line, St::Comment, "#", true);
                let rest: String = chars[i + 1..].iter().collect();
                push(&mut line, St::Comment, &rest, true);
                break;
            }
            // string with optional prefix
            let mut prefix_len = 0;
            while i + prefix_len < chars.len() && "rRbBuUfF".contains(chars[i + prefix_len]) && prefix_len < 2 {
                prefix_len += 1;
            }
            let qpos = i + prefix_len;
            let is_string = qpos < chars.len() && (chars[qpos] == '"' || chars[qpos] == '\'') && (prefix_len == 0 || (i == 0 || !is_ident(chars[i - 1])));
            if is_string && (prefix_len == 0 || chars[i..qpos].iter().all(|c| "rRbBuUfF".contains(*c))) {
                let prefix: String = chars[i..qpos].iter().collect();
                let fstring = prefix.to_lowercase().contains('f');
                let q = chars[qpos];
                let triple = qpos + 2 < chars.len() && chars[qpos + 1] == q && chars[qpos + 2] == q;
                if !prefix.is_empty() {
                    push(&mut line, St::Keyword, &prefix, true);
                }
                if triple {
                    let qs: String = std::iter::repeat(q).take(3).collect();
                    let st = if at_stmt_start && prefix.is_empty() { St::Comment } else { St::Str };
                    push(&mut line, st, &qs, true);
                    in_triple = Some((qs, st));
                    i = qpos + 3;
                    at_stmt_start = false;
                    continue;
                }
                push(&mut line, St::Str, &q.to_string(), true);
                i = qpos + 1;
                let mut buf = String::new();
                while i < chars.len() && chars[i] != q {
                    if chars[i] == '\\' && i + 1 < chars.len() {
                        push(&mut line, St::Str, &buf, true);
                        buf.clear();
                        let e: String = chars[i..i + 2].iter().collect();
                        push(&mut line, St::Number, &e, true);
                        i += 2;
                        continue;
                    }
                    if chars[i] == '%' && i + 1 < chars.len() && "sdifrxXeEgGco%".contains(chars[i + 1]) {
                        push(&mut line, St::Str, &buf, true);
                        buf.clear();
                        let e: String = chars[i..i + 2].iter().collect();
                        push(&mut line, St::Number, &e, true);
                        i += 2;
                        continue;
                    }
                    if fstring && chars[i] == '{' {
                        push(&mut line, St::Str, &buf, true);
                        buf.clear();
                        push(&mut line, St::Plain, "{", true);
                        i += 1;
                        let mut name = String::new();
                        while i < chars.len() && chars[i] != '}' && chars[i] != q {
                            name.push(chars[i]);
                            i += 1;
                        }
                        push(&mut line, St::Plain, &name, true);
                        if i < chars.len() && chars[i] == '}' {
                            push(&mut line, St::Plain, "}", true);
                            i += 1;
                        }
                        continue;
                    }
                    buf.push(chars[i]);
                    i += 1;
                }
                push(&mut line, St::Str, &buf, true);
                if i < chars.len() {
                    push(&mut line, St::Str, &q.to_string(), true);
                    i += 1;
                }
                at_stmt_start = false;
                prev_word.clear();
                continue;
            }
            if c.is_ascii_digit() {
                let mut j = i;
                if c == '0' && matches!(chars.get(i + 1), Some('x') | Some('X') | Some('o') | Some('b')) {
                    push(&mut line, St::Number, &chars[i..i + 2].iter().collect::<String>(), true);
                    j = i + 2;
                    let s = j;
                    while j < chars.len() && chars[j].is_ascii_hexdigit() {
                        j += 1;
                    }
                    push(&mut line, St::Number, &chars[s..j].iter().collect::<String>(), true);
                    i = j;
                    continue;
                }
                while j < chars.len() && chars[j].is_ascii_digit() {
                    j += 1;
                }
                push(&mut line, St::Number, &chars[i..j].iter().collect::<String>(), true);
                if j < chars.len() && chars[j] == '.' {
                    push(&mut line, St::Number, ".", true);
                    j += 1;
                    let s = j;
                    while j < chars.len() && chars[j].is_ascii_digit() {
                        j += 1;
                    }
                    push(&mut line, St::Number, &chars[s..j].iter().collect::<String>(), true);
                }
                i = j;
                at_stmt_start = false;
                continue;
            }
            if is_ident_start(c) {
                let mut j = i;
                while j < chars.len() && is_ident(chars[j]) {
                    j += 1;
                }
                let w: String = chars[i..j].iter().collect();
                let st = if PY_KW.contains(&w.as_str()) {
                    St::Keyword
                } else if PY_CONST.contains(&w.as_str()) {
                    St::Number
                } else if prev_word == "def" {
                    St::PlainBold
                } else if prev_word == "class" {
                    St::Number
                } else if PY_BUILTINS.contains(&w.as_str()) && !(i > 0 && chars[i - 1] == '.') {
                    St::Support
                } else if in_class_bases(&line) {
                    St::Number
                } else {
                    St::Plain
                };
                push(&mut line, st, &w, true);
                prev_word = w;
                i = j;
                at_stmt_start = false;
                continue;
            }
            if c == ' ' || c == '\t' {
                let mut j = i;
                while j < chars.len() && (chars[j] == ' ' || chars[j] == '\t') {
                    j += 1;
                }
                push(&mut line, St::Plain, &chars[i..j].iter().collect::<String>(), false);
                i = j;
                continue;
            }
            let three: String = chars[i..(i + 3).min(chars.len())].iter().collect();
            let two: String = chars[i..(i + 2).min(chars.len())].iter().collect();
            let ops3 = ["**=", "//=", ">>=", "<<="];
            let ops2 = ["**", "//", "==", "!=", "<=", ">=", "+=", "-=", "*=", "/=", "%=", "->", "<<", ">>", "&=", "|=", ":="];
            if ops3.contains(&three.as_str()) {
                push(&mut line, St::Keyword, &three, true);
                i += 3;
            } else if ops2.contains(&two.as_str()) {
                push(&mut line, St::Keyword, &two, true);
                i += 2;
            } else {
                match c {
                    '=' | '+' | '-' | '*' | '/' | '%' | '<' | '>' | '&' | '|' | '^' | '~' => push(&mut line, St::Keyword, &c.to_string(), true),
                    _ => push(&mut line, St::Plain, &c.to_string(), true),
                }
                i += 1;
            }
            at_stmt_start = false;
        }
        lines.push(line);
    }
    lines
}

fn in_class_bases(line: &Line) -> bool {
    // inside "class Name(" ... ")"
    let mut seen_class = false;
    let mut depth = 0;
    for r in line {
        if r.text == "class" && r.st == St::Keyword {
            seen_class = true;
        } else if seen_class && r.text == "(" {
            depth += 1;
        } else if seen_class && r.text == ")" {
            depth -= 1;
        }
    }
    seen_class && depth > 0
}
