                        continue;
                    }
                    if chars[i] == '\\\\' && i + 1 < chars.len() {
                        push(&mut line, St::Str, &buf, true);
                        buf.clear();
                        push(&mut line, St::Number, &s_of(&chars, i, i + 2), true);
                        i += 2;
                        continue;
                    }
                    buf.push(chars[i]);
                    i += 1;
                }
                push(&mut line, St::Str, &buf, true);
                if i < chars.len() {
                    push(&mut line, St::Str, &c.to_string(), true);
                    i += 1;
                }
                prev_word.clear();
                continue;
            }
            if c == '/' {
                let prev = chars[..i].iter().rev().find(|c| **c != ' ').cloned();
                if matches!(prev, Some('(') | Some(',') | Some('=') | Some(':') | Some('[') | None) {
                    if let Some(end) = (i + 1..chars.len()).find(|&j| chars[j] == '/') {
                        push(&mut line, St::Str, &s_of(&chars, i, end + 1), true);
                        let fe = take_while_from(&chars, end + 1, |c| c.is_ascii_alphabetic());
                        push(&mut line, St::Keyword, &s_of(&chars, end + 1, fe), true);
                        i = fe;
                        continue;
                    }
                }
            }
            if c.is_ascii_digit() {
                let j = take_while_from(&chars, i, |c| c.is_ascii_alphanumeric() || c == '.' || c == '_');
                push(&mut line, St::Number, &s_of(&chars, i, j), true);
                i = j;
                continue;
            }
            if is_ident_start(c) || c == '$' {
                let j = take_while_from(&chars, i, |c| is_ident(c) || c == '$');
                let w = s_of(&chars, i, j);
                let after = chars[j..].iter().find(|c| **c != ' ').cloned();
                let st = if JS_KW.contains(&w.as_str()) && !(i > 0 && chars[i - 1] == '.') {
                    St::Keyword
                } else if JS_CONST.contains(&w.as_str()) {
                    St::Number
                } else if w == "this" {
                    St::This
                } else if prev_word == "function" || ((i == first_word_pos || prev_word == "get" || prev_word == "set" || prev_word == "static" || prev_word == "async") && after == Some('(') && raw.trim_end().ends_with('{') || (i == first_word_pos && after == Some('(') && raw.contains(") {"))) {
                    St::Func
                } else if prev_word == "class" || prev_word == "extends" || prev_word == "new" {
                    St::Number
                } else if w == "console" {
                    St::FuncNoBold
                } else if i > 0 && chars[i - 1] == '.' && prev_word == "console" {
                    St::Number
                } else {
                    St::Plain
                };
                push(&mut line, st, &w, st != St::Plain);
                prev_word = w;
                i = j;
                continue;
            }
            if c == ' ' || c == '\\t' {
                let j = take_while_from(&chars, i, |c| c == ' ' || c == '\\t');
                push(&mut line, St::Plain, &s_of(&chars, i, j), false);
                i = j;
                continue;
            }
            let ops = ["===", "!==", "=>", "==", "!=", "<=", ">=", "&&", "||", "++", "--", "+=", "-=", "*=", "/=", "**"];
            let mut matched = false;
            for op in ops.iter() {
                let oc: Vec<char> = op.chars().collect();
                if chars.len() >= i + oc.len() && chars[i..i + oc.len()] == oc[..] {
                    push(&mut line, St::Keyword, op, true);
                    i += oc.len();
                    matched = true;
                    break;
                }
            }
            if matched {
                continue;
            }
            match c {
                '=' | '+' | '-' | '*' | '%' | '<' | '>' | '!' | '?' | '&' | '|' | '^' | '~' | '/' => push(&mut line, St::Keyword, &c.to_string(), true),
                '.' => {
                    push(&mut line, St::Plain, ".", false);
                    i += 1;
                    continue;
                }
                _ => push(&mut line, St::Plain, &c.to_string(), false),
            }
            if c != '.' {
                prev_word.clear();
            }
            i += 1;
        }
        lines.push(line);
    }
    lines
}

// ---------------- JSON ----------------

fn json_lines(code: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    for raw in code.split('\\n') {
        let chars: Vec<char> = raw.chars().collect();
        let mut line: Line = Vec::new();
        let mut i = 0;
        while i < chars.len() {
            let c = chars[i];
            if c == '"' {
                let mut j = i + 1;
                while j < chars.len() && chars[j] != '"' {
                    if chars[j] == '\\\\' {
                        j += 1;
                    }
                    j += 1;
                }
                let e = (j + 1).min(chars.len());
                let next = chars[e..].iter().find(|c| **c != ' ').cloned();
                if next == Some(':') {
                    push(&mut line, St::StrBold, &s_of(&chars, i, e), true);
                } else {
                    push(&mut line, St::Plain, &s_of(&chars, i, e), false);
                }
                i = e;
                continue;
            }
            if c.is_ascii_digit() || (c == '-' && chars.get(i + 1).map(|c| c.is_ascii_digit()).unwrap_or(false)) {
                let j = take_while_from(&chars, i + 1, |c| c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-');
                push(&mut line, St::Number, &s_of(&chars, i, j), true);
                i = j;
                continue;
            }
            if c.is_ascii_alphabetic() {
                let j = take_while_from(&chars, i, |c| c.is_ascii_alphabetic());
                let w = s_of(&chars, i, j);
                if w == "true" || w == "false" || w == "null" {
                    push(&mut line, St::Number, &w, true);
                } else {
                    push(&mut line, St::Plain, &w, false);
                }
                i = j;
                continue;
            }
            push(&mut line, St::Plain, &c.to_string(), false);
            i += 1;
        }
        lines.push(line);
    }
    lines
}

// ---------------- YAML ----------------

fn yaml_value(line: &mut Line, v: &str) {
    let t = v.trim_end();
    let trail = &v[t.len()..];
    if t.is_empty() {
        push(line, St::Plain, v, false);
        return;
    }
    if t.starts_with('#') {
        push(line, St::Comment, "#", true);
        push(line, St::Comment, &t[1..], true);
        return;
    }
    if t.starts_with('[') && t.ends_with(']') {
        push(line, St::Plain, "[", true);
        let inner = &t[1..t.len() - 1];
        let parts: Vec<&str> = inner.split(',').collect();
        for (k, p) in parts.iter().enumerate() {
            let pt = p.trim();
            let lead = &p[..p.len() - p.trim_start().len()];
            push(line, St::Plain, lead, false);
            yaml_scalar(line, pt);
            let tail = &p[lead.len() + pt.len()..];
            push(line, St::Plain, tail, false);
            if k + 1 < parts.len() {
                push(line, St::Plain, ",", true);
            }
        }
        push(line, St::Plain, "]", true);
        push(line, St::Plain, trail, false);
        return;
    }
    yaml_scalar(line, t);
    push(line, St::Plain, trail, false);
}

fn yaml_scalar(line: &mut Line, t: &str) {
    if t.is_empty() {
        return;
    }
    let is_num = t.parse::<f64>().is_ok();
    if is_num || ["true", "false", "null", "~", "yes", "no", "True", "False", "Null"].contains(&t) {
        push(line, St::Number, t, true);
    } else {
        push(line, St::Str, t, true);
    }
}

fn yaml_lines(code: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    for raw in code.split('\\n') {
        let mut line: Line = Vec::new();
        let indent_len = raw.len() - raw.trim_start().len();
        let indent = &raw[..indent_len];
        let mut rest = &raw[indent_len..];
        push(&mut line, St::Plain, indent, false);
        if rest.starts_with('#') {
            push(&mut line, St::Comment, "#", true);
            push(&mut line, St::Comment, &rest[1..], true);
            lines.push(line);
            continue;
        }
        while rest.starts_with("- ") {
            push(&mut line, St::Plain, "-", true);
            push(&mut line, St::Plain, " ", false);
            rest = &rest[2..];
        }
        if let Some(p) = rest.find(": ").or_else(|| if rest.ends_with(':') { Some(rest.len() - 1) } else { None }) {
            let key = &rest[..p];
            if !key.is_empty() && !key.starts_with('"') && !key.starts_with('\\'') {
                push(&mut line, St::Tag, key, true);
                push(&mut line, St::Plain, ":", true);
                let after = &rest[p + 1..];
                let sp = after.len() - after.trim_start().len();
                push(&mut line, St::Plain, &after[..sp], false);
                yaml_value(&mut line, &after[sp..]);
                lines.push(line);
                continue;
            }
        }
        yaml_value(&mut line, rest);
        lines.push(line);
    }
    lines
}

// ---------------- Bash ----------------

const SH_KW: &[&str] = &["if", "then", "else", "elif", "for", "in", "do", "while", "until", "case", "esac", "function", "select", "export", "local", "return", "readonly", "declare", "unset"];
const SH_BUILTIN: &[&str] = &["echo", "cd", "printf", "read", "source", "alias", "eval", "exec", "exit", "set", "shift", "test", "trap", "type", "ulimit", "umask", "wait", "kill", "pwd", "true", "false"];

fn bash_lines(code: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    for raw in code.split('\\n') {
        let chars: Vec<char> = raw.chars().collect();
        let mut line: Line = Vec::new();
        let mut i = 0;
        let mut cmd_pos = true;
        while i < chars.len() {
            let c = chars[i];
            if c == '#' && (i == 0 || chars[i - 1] == ' ') {
                push(&mut line, St::Comment, "#", true);
                push(&mut line, St::Comment, &s_of(&chars, i + 1, chars.len()), true);
                break;
            }
            if c == '"' {
                push(&mut line, St::Str, "\\"", true);
                i += 1;
                let mut buf = String::new();
                while i < chars.len() && chars[i] != '"' {
                    if chars[i] == '$' {
                        buf.push('$');
                        push(&mut line, St::Str, &buf, true);
                        buf.clear();
                        let j = take_while_from(&chars, i + 1, |c| is_ident(c));
                        push(&mut line, St::Plain, &s_of(&chars, i + 1, j), true);
                        i = j;
                        continue;
                    }
                    buf.push(chars[i]);
                    i += 1;
                }
                push(&mut line, St::Str, &buf, true);
                if i < chars.len() {
                    push(&mut line, St::Str, "\\"", true);
                    i += 1;
                }
                cmd_pos = false;
                continue;
            }
            if c == '\\'' {
                let j = (i + 1..chars.len()).find(|&j| chars[j] == '\\'').map(|j| j + 1).unwrap_or(chars.len());
                push(&mut line, St::Str, &s_of(&chars, i, j), true);
                i = j;
                cmd_pos = false;
                continue;
            }
            if c == ' ' || c == '\\t' {
                let j = take_while_from(&chars, i, |c| c == ' ' || c == '\\t');
                push(&mut line, St::Plain, &s_of(&chars, i, j), false);
                i = j;
                continue;
            }
            let two = s_of(&chars, i, (i + 2).min(chars.len()));
            if two == "&&" || two == "||" || two == ">>" || two == ";;" {
                if two == ";;" {
                    push(&mut line, St::Plain, ";;", false);
                } else {
                    push(&mut line, St::Keyword, &two, true);
                }
                i += 2;
                cmd_pos = true;
                continue;
            }
            match c {
                ';' | '|' | '>' | '<' | '&' => {
                    push(&mut line, St::Keyword, &c.to_string(), true);
                    i += 1;
                    cmd_pos = true;
                    continue;
                }
                ')' if cmd_pos == false && raw.contains(" in") => {
                    push(&mut line, St::Keyword, ")", true);
                    i += 1;
                    cmd_pos = true;
                    continue;
                }
                '*' => {
                    push(&mut line, St::Keyword, "*", true);
                    i += 1;
                    continue;
                }
                '[' | ']' if (i + 1 >= chars.len() || chars[i + 1] == ' ' || chars[i + 1] == ';') && (i == 0 || chars[i - 1] == ' ') => {
                    push(&mut line, St::Support, &c.to_string(), true);
                    i += 1;
                    cmd_pos = false;
                    continue;
                }
                _ => {}
            }
            // word
            let j = take_while_from(&chars, i, |c| !matches!(c, ' ' | '\\t' | ';' | '|' | '&' | '>' | '<' | '"' | '\\'' | '*' | '='));
            let j = if j == i { i + 1 } else { j };
            let w = s_of(&chars, i, j);
            if chars.get(j) == Some(&'=') {
                // assignment or option
                let before_cmd = cmd_pos;
                push(&mut line, St::Plain, &w, false);
                push(&mut line, St::Keyword, "=", true);
                let k = take_while_from(&chars, j + 1, |c| !matches!(c, ' ' | '\\t' | ';' | '|' | '&'));
                let val = s_of(&chars, j + 1, k);
                if before_cmd || w.chars().all(|c| is_ident(c)) {
                    if let Some(d) = val.find('$') {
                        push(&mut line, St::Str, &val[..d + 1], true);
                        push(&mut line, St::Plain, &val[d + 1..], true);
                    } else {
                        push(&mut line, St::Str, &val, true);
                    }
                } else {
                    push(&mut line, St::Plain, &val, false);
                }
                i = k;
                cmd_pos = before_cmd;
                continue;
            }
            if SH_KW.contains(&w.as_str()) && (cmd_pos || w == "in" || w == "do" || w == "then") {
                push(&mut line, St::Keyword, &w, true);
                cmd_pos = w != "in" && w != "case" && w != "for";
            } else if cmd_pos && SH_BUILTIN.contains(&w.as_str()) {
                push(&mut line, St::Support, &w, true);
                cmd_pos = false;
            } else {
                push(&mut line, St::Plain, &w, false);
                cmd_pos = false;
            }
            i = j;
        }
        lines.push(line);
    }
    lines
}
