    c == '—' || c == '–' || c == '-'
}

pub fn french_clean(s: &str) -> String {
    let s = s.replace("...", "…");
    let mut chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    if len == 0 {
        return String::new();
    }
    let mut dash_open = false;
    let mut skip_until = 0usize;
    for i in 0..len {
        let current = chars[i];
        if !is_ws(current) {
            continue;
        }
        if i + 1 >= len {
            continue;
        }
        let next = chars[i + 1];
        match next {
            '?' | '!' | ';' => {
                chars[i] = NB_CHAR_NARROW;
                continue;
            }
            ':' => {
                chars[i] = NB_CHAR;
                continue;
            }
            _ => {}
        }
        let prev = if i > 0 { Some(chars[i - 1]) } else { None };
        if prev == Some('«') {
            if i <= 2 {
                chars[i] = NB_CHAR;
            } else {
                let mut found = None;
                let end = (i + 20).min(len);
                for j in (i + 1)..end {
                    if chars[j] == '»' {
                        found = Some(j);
                        break;
                    }
                }
                match found {
                    Some(j) if is_ws(chars[j - 1]) => {
                        chars[i] = NB_CHAR_NARROW;
                        chars[j - 1] = NB_CHAR_NARROW;
                    }
                    _ => {
                        chars[i] = NB_CHAR;
                    }
                }
            }
            continue;
        }
        if let Some(p) = prev {
            if p.is_ascii_digit() && number_before(&chars, i) && digit_rule(&chars, i) {
                chars[i] = NB_CHAR_NARROW;
                continue;
            }
        }
        if next == '»' {
            if current == ' ' {
                chars[i] = NB_CHAR;
            }
            continue;
        }
        // closing dash
        if dash_open && is_dash_or_hyphen(next) {
            chars[i] = NB_CHAR;
            dash_open = false;
            let mut j = i + 1;
            while j < len && !is_ws(chars[j]) {
                j += 1;
            }
            skip_until = j;
            continue;
        }
        if let Some(p) = prev {
            if is_dash_or_hyphen(p) && i > skip_until {
                // word before the space
                let mut j = i;
                while j > 0 && !is_ws(chars[j - 1]) {
                    j -= 1;
                }
                let word = &chars[j..i];
                if word.iter().all(|c| *c == '-') {
                    continue;
                }
                if is_dash(p) && i <= 2 {
                    chars[i] = NB_CHAR_EM;
                } else {
                    chars[i] = NB_CHAR;
                    dash_open = true;
                }
            }
        }
    }
    chars.into_iter().collect()
}

