const CPP_KW: &[&str] = &["class", "public", "private", "protected", "namespace", "using", "template", "typename", "new", "delete", "virtual", "override", "this", "throw", "try", "catch", "auto"];
const JAVA_KW: &[&str] = &["public", "private", "protected", "class", "interface", "extends", "implements", "static", "final", "void", "return", "if", "else", "for", "while", "do", "new", "import", "package", "try", "catch", "finally", "throw", "throws", "abstract", "switch", "case", "break", "continue", "int", "char", "boolean", "double", "float", "long", "short", "byte", "this", "super"];
const GO_KW: &[&str] = &["package", "import", "func", "return", "if", "else", "for", "range", "var", "const", "type", "struct", "interface", "map", "chan", "go", "defer", "select", "switch", "case", "default", "break", "continue"];

fn cfam_lines(code: &str, lang: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut in_comment = false;
    for raw in code.split('\\n') {
        let chars: Vec<char> = raw.chars().collect();
        let mut line: Line = Vec::new();
        let mut i = 0;
        let mut prev_word = String::new();
        while i < chars.len() {
            if in_comment {
                let start = i;
                while i < chars.len() && !(chars[i] == '*' && chars.get(i + 1) == Some(&'/')) {
                    i += 1;
                }
                push(&mut line, St::Comment, &s_of(&chars, start, i), true);
                if i < chars.len() {
                    push(&mut line, St::Comment, "*/", true);
                    i += 2;
                    in_comment = false;
                }
                continue;
            }
            let c = chars[i];
            if c == '/' && chars.get(i + 1) == Some(&'/') {
                push(&mut line, St::Comment, &s_of(&chars, i, chars.len()), true);
                break;
            }
            if c == '/' && chars.get(i + 1) == Some(&'*') {
                push(&mut line, St::Comment, "/*", true);
                i += 2;
                in_comment = true;
                continue;
            }
            if c == '#' && (lang == "c" || lang == "cpp") {
                let j = take_while_from(&chars, i + 1, |c| c.is_ascii_alphabetic());
                push(&mut line, St::Keyword, &s_of(&chars, i, j), true);
                i = j;
                let k = take_while_from(&chars, i, |c| c == ' ');
                push(&mut line, St::Plain, &s_of(&chars, i, k), false);
                i = k;
                if i < chars.len() && chars[i] == '<' {
                    let e = (i..chars.len()).find(|&e| chars[e] == '>').map(|e| e + 1).unwrap_or(chars.len());
                    push(&mut line, St::Str, &s_of(&chars, i, e), true);
                    i = e;
                }
                continue;
            }
            if c == '"' || c == '\\'' || (c == '`' && lang == "go") {
                push(&mut line, St::Str, &c.to_string(), true);
                i += 1;
                let mut buf = String::new();
                while i < chars.len() && chars[i] != c {
                    if (chars[i] == '\\\\' && i + 1 < chars.len()) || (chars[i] == '%' && i + 1 < chars.len() && chars[i + 1].is_ascii_alphabetic() && lang == "c") {
                        push(&mut line, St::Str, &buf, true);
                        buf.clear();
                        let mut j = i + 2;
                        while j + 1 < chars.len() && chars[j] == '\\\\' {
                            j += 2;
                        }
                        push(&mut line, St::Number, &s_of(&chars, i, j.min(chars.len())), true);
                        i = j.min(chars.len());
                        continue;
                    }
                    buf.push(chars[i]);
                    i += 1;
                }
                push(&mut line, St::Str, &buf, true);
                if i < chars.len() {
                    push(&mut line, St::Str, &c.to_string(), true);
                    i += 1;
                }
                continue;
            }
            if c.is_ascii_digit() {
                let j = take_while_from(&chars, i, |c| c.is_ascii_alphanumeric() || c == '.');
                push(&mut line, St::Number, &s_of(&chars, i, j), true);
                i = j;
                continue;
            }
            if is_ident_start(c) {
                let j = take_while_from(&chars, i, |c| is_ident(c));
                let w = s_of(&chars, i, j);
                let after = chars[j..].iter().find(|c| **c != ' ').cloned();
                let kw = match lang {
                    "java" => JAVA_KW.contains(&w.as_str()),
                    "go" => GO_KW.contains(&w.as_str()),
                    "cpp" => C_KW.contains(&w.as_str()) || C_TYPES.contains(&w.as_str()) || CPP_KW.contains(&w.as_str()),
                    _ => C_KW.contains(&w.as_str()) || C_TYPES.contains(&w.as_str()),
                };
                let is_type_word = C_TYPES.contains(&prev_word.as_str()) || (lang == "java" && (prev_word == "void" || JAVA_KW.contains(&prev_word.as_str()) && after == Some('(')) ) || prev_word == "func";
                let st = if kw {
                    St::Keyword
                } else if w == "true" || w == "false" || w == "NULL" || w == "null" || w == "nil" {
                    St::Number
                } else if after == Some('(') && is_type_word {
                    St::Func
                } else if lang == "c" && C_FUNCS.contains(&w.as_str()) {
                    St::Support
                } else if lang == "java" && (prev_word == "class" || prev_word == "new" || prev_word == "extends" || w == "String" || w == "System") {
                    St::Number
                } else {
                    St::Plain
                };
                push(&mut line, st, &w, st != St::Plain);
                prev_word = w;
                i = j;
                continue;
            }
            if c == ' ' || c == '\\t' {
                let j = take_while_from(&chars, i, |c| c == ' ' || c == '\\t');
                push(&mut line, St::Plain, &s_of(&chars, i, j), false);
                i = j;
                continue;
            }
            let two = s_of(&chars, i, (i + 2).min(chars.len()));
            if two == "[]" && lang == "java" {
                push(&mut line, St::Keyword, "[]", true);
                i += 2;
                continue;
            }
            let ops = [":=", "==", "!=", "<=", ">=", "&&", "||", "++", "--", "+=", "-=", "->"];
            if ops.contains(&two.as_str()) {
                push(&mut line, if two == "->" { St::Plain } else { St::Keyword }, &two, true);
                i += 2;
                continue;
            }
            match c {
                '=' | '+' | '-' | '/' | '%' | '<' | '>' | '!' | '&' | '|' | '^' | '?' => push(&mut line, St::Keyword, &c.to_string(), true),
                '*' => {
                    let st = if C_TYPES.contains(&prev_word.as_str()) || prev_word == "*" { St::Keyword } else { St::Keyword };
                    push(&mut line, st, "*", true);
                    prev_word = "*".to_string();
                    i += 1;
                    continue;
                }
                _ => push(&mut line, St::Plain, &c.to_string(), false),
            }
            prev_word.clear();
            i += 1;
        }
        lines.push(line);
    }
    lines
}

// ---------------- HTML ----------------

fn html_lines(code: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut in_tag = false;
    for raw in code.split('\\n') {
        let chars: Vec<char> = raw.chars().collect();
        let mut line: Line = Vec::new();
        let mut i = 0;
        while i < chars.len() {
            let c = chars[i];
            if !in_tag {
                if c == '<' {
                    let mut j = i + 1;
                    if chars.get(j) == Some(&'/') || chars.get(j) == Some(&'!') {
                        j += 1;
                    }
                    push(&mut line, St::Plain, &s_of(&chars, i, j), false);
                    let k = take_while_from(&chars, j, |c| c.is_alphanumeric() || c == '-' || c == ':');
                    push(&mut line, St::Tag, &s_of(&chars, j, k), true);
                    i = k;
                    in_tag = true;
                    continue;
                }
                if c == '&' {
                    if let Some(e) = (i + 1..chars.len().min(i + 12)).find(|&e| chars[e] == ';') {
                        push(&mut line, St::Number, &s_of(&chars, i, e + 1), true);
                        i = e + 1;
                        continue;
                    }
                }
                push(&mut line, St::Plain, &c.to_string(), false);
                i += 1;
            } else {
                if c == '>' {
                    push(&mut line, St::Plain, ">", false);
                    in_tag = false;
                    i += 1;
                    continue;
                }
                if c == '"' || c == '\\'' {
                    let e = (i + 1..chars.len()).find(|&e| chars[e] == c).map(|e| e + 1).unwrap_or(chars.len());
                    push(&mut line, St::Str, &s_of(&chars, i, e), true);
                    i = e;
                    continue;
                }
                if is_ident_start(c) {
                    let j = take_while_from(&chars, i, |c| is_ident(c) || c == '-' || c == ':');
                    let w = s_of(&chars, i, j);
                    if chars.get(j) == Some(&'=') {
                        push(&mut line, St::FuncNoBold, &w, true);
                    } else {
                        push(&mut line, St::Plain, &w, false);
                    }
                    i = j;
                    continue;
                }
                push(&mut line, St::Plain, &c.to_string(), false);
                i += 1;
            }
        }
        lines.push(line);
    }
    lines
}

// ---------------- SQL ----------------

const SQL_KW: &[&str] = &["select", "from", "where", "insert", "into", "values", "update", "set", "delete", "create", "table", "drop", "alter", "and", "or", "not", "null", "join", "left", "right", "inner", "outer", "on", "as", "order", "by", "group", "having", "limit", "distinct", "union", "all", "in", "is", "like", "primary", "key", "index", "exists", "between", "case", "when", "then", "else", "end"];

fn sql_lines(code: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    for raw in code.split('\\n') {
        let chars: Vec<char> = raw.chars().collect();
        let mut line: Line = Vec::new();
        let mut i = 0;
        while i < chars.len() {
            let c = chars[i];
            if c == '-' && chars.get(i + 1) == Some(&'-') {
                push(&mut line, St::Comment, &s_of(&chars, i, chars.len()), true);
                break;
            }
            if c == '\\'' || c == '"' {
                let e = (i + 1..chars.len()).find(|&e| chars[e] == c).map(|e| e + 1).unwrap_or(chars.len());
                push(&mut line, St::Str, &s_of(&chars, i, e), true);
                i = e;
                continue;
            }
            if c.is_ascii_digit() {
                let j = take_while_from(&chars, i, |c| c.is_ascii_digit() || c == '.');
                push(&mut line, St::Number, &s_of(&chars, i, j), true);
                i = j;
                continue;
            }
            if is_ident_start(c) {
                let j = take_while_from(&chars, i, |c| is_ident(c));
                let w = s_of(&chars, i, j);
                if SQL_KW.contains(&w.to_lowercase().as_str()) {
                    push(&mut line, St::Keyword, &w, true);
                } else {
                    push(&mut line, St::Plain, &w, false);
                }
                i = j;
                continue;
            }
            match c {
                '=' | '<' | '>' | '+' | '-' | '/' | '!' => push(&mut line, St::Keyword, &c.to_string(), true),
                _ => push(&mut line, St::Plain, &c.to_string(), false),
            }
            i += 1;
        }
        lines.push(line);
    }
    lines
}
